"use strict";(globalThis.webpackChunkmy_tech_blog=globalThis.webpackChunkmy_tech_blog||[]).push([[6713],{8386:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"data-center-power-grid-structure","metadata":{"permalink":"/blog/finance/data-center-power-grid-structure","source":"@site/finance/2026-10-23-data-center-power-grid/index.mdx","title":"AI \ub370\uc774\ud130\uc13c\ud130\uc640 \uc804\ub825 \uc778\ud504\ub77c \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-23T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"sector","permalink":"/blog/finance/tags/sector"},{"inline":true,"label":"power-infrastructure","permalink":"/blog/finance/tags/power-infrastructure"}],"readingTime":2.68,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"data-center-power-grid-structure","title":"AI \ub370\uc774\ud130\uc13c\ud130\uc640 \uc804\ub825 \uc778\ud504\ub77c \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124","authors":["way"],"tags":["finance","sector","power-infrastructure"]},"unlisted":false,"nextItem":{"title":"\ubc30\ub2f9\uacfc \ubc30\ub2f9\ub77d\uc77c, \ubc30\ub2f9\uc218\uc775\ub960 \uacc4\uc0b0\ubc95","permalink":"/blog/finance/dividend-exdividend-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\nAI \ub370\uc774\ud130\uc13c\ud130\uac00 \uc65c \uc804\ub825 \uc124\ube44 \uc0b0\uc5c5\uc744 \ub04c\uc5b4\uc62c\ub9ac\ub294\uc9c0, \uadf8 \uad6c\uc870\ub97c \uad50\uc721 \ubaa9\uc801\uc73c\ub85c \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uc0b0\uc220\uc774 \uc544\ub2c8\ub77c \uc804\uae30\uac00 \ubc1c\ubaa9\uc744 \uc7a1\ub294\ub2e4\\n\\nAI \ub370\uc774\ud130\uc13c\ud130\uac00 \ub298\uc5b4\ub098\uba74\uc11c \ud76c\uc18c \uc790\uc6d0\uc774 \ubc18\ub3c4\uccb4 \uce69\uc5d0\uc11c \uc804\ub825\ub9dd\uc73c\ub85c \uc62e\uaca8\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\ub825\ub9dd \uc5f0\uacb0 \uc9c0\uc5f0\uc774 3\ub144\uc5d0\uc11c \uae38\uac8c\ub294 5\ub144\uae4c\uc9c0 \uae38\uc5b4\uc9c0\uc790, \uc720\ud2f8\ub9ac\ud2f0 \ud68c\uc0ac\uc758 \uc1a1\uc804\uc120 \uad6c\ucd95\uc744 \uae30\ub2e4\ub9b4 \uc218 \uc5c6\ub294 \uc0c1\ud669\uc774 \ub418\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\nHD\ud604\ub300\uc77c\ub809\ud2b8\ub9ad\uc740 10\uc6d4 28~30\uc77c \ucf54\uc5d1\uc2a4\uc5d0\uc11c \uc5f4\ub9ac\ub294 [SEP 2026](https://www.mt.co.kr/industry/2026/10/08/2026100714420243542) \ubc1c\ud45c\ub97c \uc55e\ub450\uace0 \\"\ud604\uc7ac\uc758 \ubcc0\uc555\uae30 \uc218\uc694\ub294 \uc288\ud37c\uc0ac\uc774\ud074\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0 \ub274\ub178\uba40\ub85c \uc790\ub9ac \uc7a1\uc744 \uac83\\"\uc774\ub77c\uace0 \ubc1d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc804\ub825\uc774 \ub2e8\uc21c\ud55c \ubd80\ud488\uc774 \uc544\ub2c8\ub77c \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124\uc758 \uc120\uacb0 \uc870\uac74\uc774 \ub418\uc5c8\ub2e4\ub294 \uc758\ubbf8\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExdXg5dzR0MTUyeXB1aWFlYWo4a2wxM2phaGszbW96a2FxZDdheDh3biZlcD12MV9naWZzX3NlYXJjaCZjdD1n/AXLv8xVMmASjtr9xeD/giphy.gif\\" alt=\\"Electricity\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc804\ub825\uc774 \ub370\uc774\ud130\uc13c\ud130\uc5d0 \ub3c4\ucc29\ud558\ub294 \uacbd\ub85c\\n\\n#### \uc1a1\uc804 \u2014 \ubc1c\uc804\uc18c\uc5d0\uc11c \ub370\uc774\ud130\uc13c\ud130\uae4c\uc9c0\\n\\n\ubc1c\uc804\uc18c\uc5d0\uc11c \uc0dd\uc0b0\ub41c \uc804\uae30\ub294 \uc1a1\uc804\uc120\uc744 \ud0c0\uace0 \uc7a5\uac70\ub9ac\ub97c \uc774\ub3d9\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5\uac70\ub9ac \uc1a1\uc804\uc5d0\ub294 `154kV`, `345kV`, `765kV` \uac19\uc740 \ucd08\uace0\uc555\uc774 \uc4f0\uc774\uba70, \uc804\uc555\uc774 \ub192\uc744\uc218\ub85d \uc190\uc2e4\uc774 \uc801\uc2b5\ub2c8\ub2e4.<br/>\\n\ub3c4\ucc29\ud55c \uc804\uae30\ub294 \ubcc0\uc804\uc18c\uc758 \ubcc0\uc555\uae30\ub97c \uac70\uccd0 \ub2e8\uacc4\uc801\uc73c\ub85c \uc804\uc555\uc774 \ub0ae\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\ucd5c\uc885\uc801\uc73c\ub85c \ub370\uc774\ud130\uc13c\ud130 \ub0b4\ubd80\uc5d0\uc11c\ub294 \uc11c\ubc84 \ub799\uc774 \uc4f0\ub294 \uc804\uc555\uc73c\ub85c \ubcc0\ud658\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ubcc0\uc555\uae30 \ub0a9\uae30\uac00 2~3\ub144\uc778 \uc774\uc720\\n\\n\ub300\ud615 \ubcc0\uc555\uae30\ub294 \uc8fc\ubb38 \uc81c\uc791 \ubc29\uc2dd\uc774\ub77c \uc0dd\uc0b0 \ub9ac\ub4dc\ud0c0\uc784\uc774 2~3\ub144\uc5d0 \uc774\ub985\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc5d0\ub108\uc9c0\uc815\ubcf4\uccad(EIA)\uc740 2026\ub144 \ubbf8\uad6d \uc5f0\uac04 \uc804\ub825 \ud310\ub9e4\ub7c9\uc744 4.135\uc870 kWh, 2027\ub144\uc744 4.211\uc870 kWh\ub85c \uc804\ub9dd\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615 \ub370\uc774\ud130\uc13c\ud130\uac00 \uc694\uad6c\ud558\ub294 \ubcc0\uc555\uae30 \uc6a9\ub7c9\uc740 `150~200 MVA`\uae09\uae4c\uc9c0 \uc62c\ub77c\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uc694\uac00 \ub298\uc5b4\ub3c4 \uacf5\uc7a5\uc774 \ub2f9\uc7a5 \ub530\ub77c\uac00\uc9c0 \ubabb\ud558\ubbc0\ub85c, \uc218\uc8fc\uc794\uace0\uac00 \uc2e4\uc801\uc758 \uc120\ud589\uc9c0\ud45c \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uc804\ub9dd \u2014 \uac74\ubb3c \ub0b4\ubd80\ub85c \uc804\uae30\ub97c \ucabc\uac1c\ub294 \uc77c\\n\\n\uc1a1\uc804\uc774 \'\ubc1c\uc804\uc18c\uc5d0\uc11c \ub370\uc774\ud130\uc13c\ud130\uae4c\uc9c0\'\ub77c\uba74, \ubc30\uc804\uc740 \'\ub370\uc774\ud130\uc13c\ud130 \uac74\ubb3c \uc548\uc5d0\uc11c \uc11c\ubc84 \ub799\uae4c\uc9c0\' \uc804\uae30\ub97c \ub098\ub204\ub294 \ub2e8\uacc4\uc785\ub2c8\ub2e4.<br/>\\n\ubc84\uc2a4\ub355\ud2b8(\uc804\uae30 \ud1b5\ub85c)\uc640 \uc911\uc804\uc555 \ucf00\uc774\ube14\uc774 \uc774 \uad6c\uac04\uc744 \ub2f4\ub2f9\ud569\ub2c8\ub2e4.<br/>\\n\uc1a1\uc804 \ubcd1\ubaa9\uc774 \uae38\uc5b4\uc9c0\uba74\uc11c \uc2dc\uc7a5\uc758 \uad00\uc2ec\uc774 \ubc30\uc804 \uad6c\uac04\uc73c\ub85c\uae4c\uc9c0 \ud655\uc0b0\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### BTM(Behind The Meter) \u2014 \uc804\ub825\ub9dd\uc744 \uac70\uce58\uc9c0 \uc54a\ub294 \uc804\uc6d0\\n\\nBTM\uc740 \uc720\ud2f8\ub9ac\ud2f0 \uc804\ub825\ub9dd\uc744 \uac70\uce58\uc9c0 \uc54a\uace0 \ud604\uc7a5\uc5d0\uc11c \uc9c1\uc811 \uc804\ub825\uc744 \uacf5\uae09\ud558\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\uc218\uc18c \uc5f0\ub8cc\uc804\uc9c0, \uac00\uc2a4\ud130\ube48, \ubc30\ud130\ub9ac \uc5d0\ub108\uc9c0\uc800\uc7a5\uc7a5\uce58(BESS)\ub97c \ub370\uc774\ud130\uc13c\ud130 \uc606\uc5d0 \uc124\uce58\ud574 \uc790\uae09\uc790\uc871\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uc804\ub825\uc744 \uc81c\uc5b4\ud558\ub294 \ud2b9\uc218\ubcc0\uc555\uae30\uac00 \ubcc4\ub3c4 \uc2dc\uc7a5\uc744 \ud615\uc131\ud558\uace0 \uc788\uc73c\uba70, \uae30\uc874 \ubc94\uc6a9 \ubcc0\uc555\uae30\ubcf4\ub2e4 \ub09c\ub3c4\uac00 \ub192\uc544 \ub9c8\uc9c4\uc774 \ub450\ud130\uc6b4 \ud3b8\uc785\ub2c8\ub2e4.<br/>\\n\uc804\ub825\ub9dd \uc5f0\uacc4\uac00 3~5\ub144\uc529 \uc9c0\uc5f0\ub418\ub294 \ud658\uacbd\uc5d0\uc11c BTM\uc740 \uc6b0\ud68c\ub85c\uc774\uc790 \ud544\uc218 \uacbd\ub85c\uac00 \ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc5c5\uacc4\uc758 \ub300\uc751 \u2014 \uc0dd\uc0b0\ub2a5\ub825 \ud655\ucda9\\n\\nHD\ud604\ub300\uc77c\ub809\ud2b8\ub9ad\uc740 \uc62c\ud574 4\ubd84\uae30 \uc6b8\uc0b0 \uacf5\uc7a5 \uc99d\uc124\uc744 \uc644\ub8cc\ud558\uace0, \ub0b4\ub144 \uc0c1\ubc18\uae30 \ubbf8\uad6d \uc568\ub77c\ubc30\ub9c8 \ubc95\uc778 \uc81c2\uacf5\uc7a5\uc744 \uac00\ub3d9\ud560 \uacc4\ud68d\uc785\ub2c8\ub2e4.<br/>\\n\uc568\ub77c\ubc30\ub9c8 \uc99d\uc124\uc774 \ub05d\ub098\uba74 \ud604\uc9c0 \ubcc0\uc555\uae30 \uc0dd\uc0b0\ub2a5\ub825\uc740 \uae30\uc874\ubcf4\ub2e4 50% \ub298\uc5b4\ub0a0 \uc804\ub9dd\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \ud68c\uc0ac\uc758 \ubd81\ubbf8 \ub9e4\ucd9c\uc740 2024\ub144 1\uc870 \uc6d0\uc5d0\uc11c \uc9c0\ub09c\ud574 1\uc870 6\ucc9c\uc5b5 \uc6d0\uc73c\ub85c \uc99d\uac00\ud588\uace0, \uc62c\ud574 \uc0c1\ubc18\uae30\uc5d0\ub3c4 1\uc870 \uc6d0\uc744 \ub118\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\ub825\uae30\uae30 \uc5c5\uccb4\ub4e4\uc758 \uacf5\ud1b5 \uc804\ub7b5\uc740 \uc0dd\uc0b0\ub2a5\ub825 \ud655\ucda9\uacfc \ubd81\ubbf8 \ud604\uc9c0\ud654\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc804\ub825 \uc778\ud504\ub77c \uc0b0\uc5c5\uc744 \ubcfc \ub54c\ub294 \uc218\uc8fc\uc794\uace0, \ub9ac\ub4dc\ud0c0\uc784, \ub0a9\uae30 \ub2e8\ucd95 \uc5ec\ubd80\ub97c \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc8fc\ubb38\uc774 \ubab0\ub824\ub3c4 \ub0a9\uae30\uac00 2~3\ub144\uc774\ubbc0\ub85c, \uc2e0\uaddc \uacf5\uc7a5\uc758 \uac00\ub3d9 \uc2dc\uc810\uc774 \uc2e4\uc801 \ubc18\uc601 \uc2dc\uc810\uc744 \uac00\ub985\ub2c8\ub2e4.<br/>\\nBTM \uad6c\uc870\uac00 \ud655\uc0b0\ub418\ub294\uc9c0, \ud574\uc678 \ud604\uc9c0 \uc0dd\uc0b0 \ube44\uc911\uc774 \ub298\uc5b4\ub098\ub294\uc9c0\ub3c4 \uad6c\uc870\uc801 \ubcc0\ud654\uc758 \ub2e8\uc11c\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uc0b0\uc5c5 \uad6c\uc870\ub97c \uc124\uba85\ud558\ub294 \uad50\uc721 \ubaa9\uc801\uc758 \ud574\uc124\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\nAI \uc2dc\ub300\uc758 \uc9c4\uc9dc \ubcd1\ubaa9\uc740 \uce69\uc774 \uc544\ub2c8\ub77c \uc804\ub825\uc774 \ub420 \uac00\ub2a5\uc131\uc774 \ucee4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc1a1\uc804\uc5d0\uc11c \ubc30\uc804, BTM\uae4c\uc9c0 \uc804\ub825 \ud750\ub984\uc744 \uc774\ud574\ud558\uba74 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828 \ub274\uc2a4\uac00 \ub2ec\ub9ac \ubcf4\uc774\uae30 \uc2dc\uc791\ud569\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExdXg5dzR0MTUyeXB1aWFlYWo4a2wxM2phaGszbW96a2FxZDdheDh3biZlcD12MV9naWZzX3NlYXJjaCZjdD1n/Yd9BNyMoC6d6NFZ1iW/giphy.gif\\" alt=\\"Power\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"dividend-exdividend-guide","metadata":{"permalink":"/blog/finance/dividend-exdividend-guide","source":"@site/finance/2026-10-23-dividend-exdividend/index.mdx","title":"\ubc30\ub2f9\uacfc \ubc30\ub2f9\ub77d\uc77c, \ubc30\ub2f9\uc218\uc775\ub960 \uacc4\uc0b0\ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-23T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"dividend","permalink":"/blog/finance/tags/dividend"},{"inline":true,"label":"basics","permalink":"/blog/finance/tags/basics"}],"readingTime":2.58,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"dividend-exdividend-guide","title":"\ubc30\ub2f9\uacfc \ubc30\ub2f9\ub77d\uc77c, \ubc30\ub2f9\uc218\uc775\ub960 \uacc4\uc0b0\ubc95","authors":["way"],"tags":["finance","dividend","basics"]},"unlisted":false,"prevItem":{"title":"AI \ub370\uc774\ud130\uc13c\ud130\uc640 \uc804\ub825 \uc778\ud504\ub77c \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124","permalink":"/blog/finance/data-center-power-grid-structure"},"nextItem":{"title":"FOMC\uc640 \uae08\ud1b5\uc704 \uae08\ub9ac \uacb0\uc815 \uc77d\ub294 \ubc95","permalink":"/blog/finance/fomc-bok-rate-decision-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc5f0\ub9d0 \ubc30\ub2f9 \uc2dc\uc98c\uc744 \uc55e\ub450\uace0 \ubc30\ub2f9\uacfc \ubc30\ub2f9\ub77d\uc77c, \ubc30\ub2f9\uc218\uc775\ub960\uc758 \uac1c\ub150\uc744 \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \ubc30\ub2f9\uc740 \'\uacf5\uc9dc \ub3c8\'\uc774 \uc544\ub2c8\ub2e4\\n\\n\uc8fc\uc2dd\uc744 \uac00\uc9c4 \uc8fc\uc8fc\ub294 \ud68c\uc0ac\uc758 \uc774\uc775\uc744 \ubc30\ub2f9\uc73c\ub85c \ub098\ub220 \ubc1b\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7f0\ub370 \ubc30\ub2f9\uc744 \ubc1b\ub294 \ub0a0 \uc8fc\uac00\uac00 \ub5a8\uc5b4\uc9c0\ub294 \uac83\uc744 \ubcf4\uace0 \ub2f9\ud669\ud558\ub294 \ud22c\uc790\uc790\uac00 \uc801\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\ub77d\uc77c\uc758 \uc6d0\ub9ac\ub97c \uc54c\uba74, \ubc30\ub2f9\uc774 \uacf5\uc9dc\ub85c \uc0dd\uae30\ub294 \ub3c8\uc774 \uc544\ub2c8\ub77c \uad6c\uc870\uc801\uc73c\ub85c \uc815\uc0b0\ub418\ub294 \uae08\uc561\uc784\uc744 \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZzc2dXR3YTRrY2R2dXJuMXU1aTFzMnF6MWk3YTBmb3B1dzA1NTRhMiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/RGXhikrzGUUyh8vrsH/giphy.gif\\" alt=\\"Money\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ubc30\ub2f9\uc758 \uc885\ub958\\n\\n#### \uc911\uac04\ubc30\ub2f9\uacfc \uae30\ub9d0\ubc30\ub2f9\\n\\n\ubc30\ub2f9\uc740 \uc9c0\uae09 \uc2dc\uae30\uc5d0 \ub530\ub77c \uc911\uac04\ubc30\ub2f9\uacfc \uae30\ub9d0\ubc30\ub2f9\uc73c\ub85c \ub098\ub269\ub2c8\ub2e4.<br/>\\n\uc911\uac04\ubc30\ub2f9\uc740 \ud68c\uacc4\uc5f0\ub3c4 \uc911\uac04\uc5d0 \uc9c0\uae09\ud558\ub294 \ubc30\ub2f9\uc774\uace0, \uae30\ub9d0\ubc30\ub2f9\uc740 \uacb0\uc0b0 \ud6c4 \uc9c0\uae09\ud558\ub294 \ubc30\ub2f9\uc785\ub2c8\ub2e4.<br/>\\n12\uc6d4 \uacb0\uc0b0\ubc95\uc778\uc758 \uae30\ub9d0\ubc30\ub2f9\uc740 \ubcf4\ud1b5 \ub2e4\uc74c \ud574 3~4\uc6d4 \uc8fc\uc8fc\ucd1d\ud68c \ub4a4\uc5d0 \uc9c0\uae09\ub429\ub2c8\ub2e4.<br/>\\n\uc774 \ubc16\uc5d0 \ud2b9\ubcc4\ud55c \uc0ac\uc720\ub85c \ud55c \ubc88\ub9cc \uc9c0\uae09\ud558\ub294 \ud2b9\ubcc4\ubc30\ub2f9\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\ub2f9\ubc1b\uc744 \uad8c\ub9ac\ub294 \uae30\uc900\uc77c\ub85c \uc815\ud574\uc9c4\ub2e4\\n\\n\ubc30\ub2f9\uc744 \ubc1b\uc744 \uc8fc\uc8fc\ub294 \'\ubc30\ub2f9\uae30\uc900\uc77c\' \ud604\uc7ac \uc8fc\uc8fc\uba85\ubd80\uc5d0 \uc788\ub294 \uc0ac\ub78c\uc785\ub2c8\ub2e4.<br/>\\n12\uc6d4 \uacb0\uc0b0\ubc95\uc778\uc758 \uae30\ub9d0\ubc30\ub2f9 \uae30\uc900\uc77c\uc740 \ud1b5\uc0c1 12\uc6d4 \ub9d0\uc77c\uc785\ub2c8\ub2e4.<br/>\\n\uae30\uc900\uc77c\uc5d0 \uc8fc\uc8fc\uc5ec\uc57c \ud558\ubbc0\ub85c, \uadf8 \uc804\uc5d0 \uc8fc\uc2dd\uc744 \uc0ac\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\ub2f9\ub77d\uc77c\uc758 \uc6d0\ub9ac\\n\\n#### \ubc30\ub2f9\ubc1b\uc744 \uad8c\ub9ac\uac00 \ub5a8\uc5b4\uc9c0\ub294 \ub0a0\\n\\n\ubc30\ub2f9\ub77d\uc77c(ex-dividend date)\uc740 \ubc30\ub2f9\ubc1b\uc744 \uad8c\ub9ac\uac00 \uc0c8\ub85c \ub5a8\uc5b4\uc9c0\ub294 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \ubc30\ub2f9\uae30\uc900\uc77c 2\uc601\uc5c5\uc77c \uc804\ubd80\ud130 \uac70\ub798\ud55c \uc8fc\uc2dd\uc774 \ubc30\ub2f9 \uad8c\ub9ac\ub97c \uac16\uc2b5\ub2c8\ub2e4.<br/>\\n\uc989 \ubc30\ub2f9\ub77d\uc77c\uc5d0 \uc8fc\uc2dd\uc744 \uc0ac\uba74 \ud574\ub2f9 \ubc30\ub2f9\uc740 \ubc1b\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\ub77d\uc77c \uc774\uc804\uc5d0 \ub9e4\uc218\ud55c \uc8fc\uc8fc\ub9cc\uc774 \ubc30\ub2f9 \ub300\uc0c1\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### \uc65c \ubc30\ub2f9\ub77d\uc77c\uc5d0 \uc8fc\uac00\uac00 \uc870\uc815\ub418\ub294\uac00\\n\\n\ubc30\ub2f9\ub77d\uc77c\uc5d0\ub294 \uc8fc\uac00\uac00 \ubc30\ub2f9\uae08\ub9cc\ud07c \uae30\uc900\uac00\uaca9\uc5d0\uc11c \uc870\uc815\ub429\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4 \uc8fc\uac00\uac00 `50,000\uc6d0`\uc774\uace0 \ubc30\ub2f9\uae08\uc774 `1,000\uc6d0`\uc778 \uc885\ubaa9\uc740 \ubc30\ub2f9\ub77d\uc77c \uae30\uc900\uac00\uac00 `49,000\uc6d0`\uc5d0\uc11c \ucd9c\ubc1c\ud569\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\ub77d\uc77c\uc758 \uc8fc\uac00 \ud558\ub77d\uc740 \uc545\uc7ac\uac00 \uc544\ub2c8\ub77c \ubc30\ub2f9\uae08\uc744 \ubc18\uc601\ud55c \uc815\uc0b0\uc785\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uae08\uc744 \ud604\uae08\uc73c\ub85c \ubc1b\uc740 \uc8fc\uc8fc \uc785\uc7a5\uc5d0\uc11c\ub294 \uc804\uccb4 \uc7ac\uc0b0\uc774 \ub2ec\ub77c\uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\ub77d\uc77c\uc5d0 \\"\uc8fc\uac00\uac00 \ub5a8\uc5b4\uc84c\ub2e4\\"\uba70 \ub2f9\ud669\ud560 \ud544\uc694\uac00 \uc5c6\ub294 \uc774\uc720\uac00 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\ub2f9\uc218\uc775\ub960 \uacc4\uc0b0\\n\\n#### \ubc30\ub2f9\uc218\uc775\ub960 \uacf5\uc2dd\\n\\n\ubc30\ub2f9\uc218\uc775\ub960\uc740 \uc8fc\ub2f9\ubc30\ub2f9\uae08\uc744 \uc8fc\uac00\ub85c \ub098\ub208 \ube44\uc728\uc785\ub2c8\ub2e4.<br/>\\n\\n`\ubc30\ub2f9\uc218\uc775\ub960(%) = \uc8fc\ub2f9\ubc30\ub2f9\uae08 \xf7 \uc8fc\uac00 \xd7 100`\\n\\n\uc8fc\ub2f9\ubc30\ub2f9\uae08\uc774 `1,000\uc6d0`\uc774\uace0 \uc8fc\uac00\uac00 `50,000\uc6d0`\uc774\uba74 \ubc30\ub2f9\uc218\uc775\ub960\uc740 2%\uc785\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ubc30\ub2f9\uae08\uc774\ub77c\ub3c4 \uc8fc\uac00\uac00 \uc624\ub974\uba74 \uc218\uc775\ub960\uc740 \ub0ae\uc544\uc9c0\uace0, \uc8fc\uac00\uac00 \ub0b4\ub9ac\uba74 \uc218\uc775\ub960\uc740 \ub192\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\ub2f9\uc218\uc775\ub960\uc758 \ud568\uc815\\n\\n\ubc30\ub2f9\uc218\uc775\ub960\uc774 \ub192\ub2e4\uace0 \ubb34\uc870\uac74 \uc88b\uc740 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc8fc\uac00\uac00 \uc2e4\uc801 \uc545\ud654\ub85c \uae09\ub77d\ud558\uba74 \ubc30\ub2f9\uc218\uc775\ub960\uc740 \uc218\uce58\uc0c1 \ub192\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uae08\uc740 \ud68c\uc0ac\uc758 \uc774\uc775\uc5d0\uc11c \ub098\uc624\ub294 \uac83\uc774\ubbc0\ub85c, \uc774\uc775\uc774 \uc904\uc5b4\ub4e4\uba74 \ubc30\ub2f9\ub3c4 \uc904\uc5b4\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uc218\uc775\ub960\uc744 \ubcfc \ub54c\ub294 \ubc30\ub2f9\uc131\ud5a5(\uc21c\uc774\uc775 \uc911 \ubc30\ub2f9 \ube44\uc728)\uacfc \uc774\uc775 \ucd94\uc774\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\ub2f9\uc18c\ub4dd\uc5d0\ub294 \uc138\uae08\uc774 \ubd99\ub294\ub2e4\\n\\n\ubc1b\uc740 \ubc30\ub2f9\uc740 \ubc30\ub2f9\uc18c\ub4dd\uc73c\ub85c \ubd84\ub958\ub418\uc5b4 `15.4%`\uc758 \uc138\uc728\ub85c \uc6d0\ucc9c\uc9d5\uc218\ub429\ub2c8\ub2e4.<br/>\\n\uc8fc\ub2f9 `1,000\uc6d0` \ubc30\ub2f9\uc744 \ubc1b\uc73c\uba74 \uc2e4\uc81c \uc218\ub839\uc561\uc740 `846\uc6d0`\uc785\ub2c8\ub2e4.<br/>\\n\uc5f0\uac04 \uae08\uc735\uc18c\ub4dd\uc774 \uc77c\uc815 \uae30\uc900\uc744 \ub118\uc73c\uba74 \uae08\uc735\uc18c\ub4dd\uc885\ud569\uacfc\uc138 \ub300\uc0c1\uc774 \ub418\ubbc0\ub85c, \ubc30\ub2f9\uc774 \ud070 \ud22c\uc790\uc790\ub294 \uc5f0\ub9d0\uc5d0 \ud569\uc0b0\uc744 \ud568\uaed8 \uacc4\uc0b0\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\ubc30\ub2f9\uae30\uc900\uc77c\uacfc \ubc30\ub2f9\ub77d\uc77c \uc77c\uc815\uc744 \ubbf8\ub9ac \ud655\uc778\ud558\uba74 \ub9e4\uc218 \uc2dc\uc810\uc744 \uacc4\ud68d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\ub77d\uc77c \uc804\ud6c4\uc758 \uc8fc\uac00 \uc6c0\uc9c1\uc784\uc744 \'\ub77d \ud6a8\uacfc\'\uc640 \ud63c\ub3d9\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uc218\uc775\ub960\uc740 \ud604\uc7ac \uc8fc\uac00 \uae30\uc900\uc774\ubbc0\ub85c, \uacfc\uac70 \ub192\uc740 \uc218\uc775\ub960\uc5d0 \uae30\ub300\uc5b4 \ub9e4\uc218 \uacb0\uc815\uc744 \ub0b4\ub9ac\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ubc30\ub2f9 \uad6c\uc870\ub97c \uc124\uba85\ud558\ub294 \uad50\uc721 \ubaa9\uc801\uc758 \ud574\uc124\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ubc30\ub2f9\uc740 \uad6c\uc870\ub97c \uc54c\uba74 \ub2e8\uc21c\ud55c \ud604\uae08 \uc9c0\uae09\uc774 \uc544\ub2c8\ub77c \uad8c\ub9ac\uc640 \uac00\uaca9\uc758 \uc815\uc0b0 \uacfc\uc815\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5f0\ub9d0 \ubc30\ub2f9 \uc2dc\uc98c\uc5d0 \ubc30\ub2f9\ub77d\uc77c \uc77c\uc815\uc744 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \uc758\uc678\ub85c \uc2e4\uc218\ub97c \ub9ce\uc774 \ub9c9\uc544\uc90d\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZzc2dXR3YTRrY2R2dXJuMXU1aTFzMnF6MWk3YTBmb3B1dzA1NTRhMiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/XfDqt93JwrfwgoHkrq/giphy.gif\\" alt=\\"Dividend\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"fomc-bok-rate-decision-guide","metadata":{"permalink":"/blog/finance/fomc-bok-rate-decision-guide","source":"@site/finance/2026-10-23-fomc-bok-rate-decision/index.mdx","title":"FOMC\uc640 \uae08\ud1b5\uc704 \uae08\ub9ac \uacb0\uc815 \uc77d\ub294 \ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-23T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"interest-rate","permalink":"/blog/finance/tags/interest-rate"},{"inline":true,"label":"fomc","permalink":"/blog/finance/tags/fomc"}],"readingTime":2.99,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"fomc-bok-rate-decision-guide","title":"FOMC\uc640 \uae08\ud1b5\uc704 \uae08\ub9ac \uacb0\uc815 \uc77d\ub294 \ubc95","authors":["way"],"tags":["finance","interest-rate","fomc"]},"unlisted":false,"prevItem":{"title":"\ubc30\ub2f9\uacfc \ubc30\ub2f9\ub77d\uc77c, \ubc30\ub2f9\uc218\uc775\ub960 \uacc4\uc0b0\ubc95","permalink":"/blog/finance/dividend-exdividend-guide"},"nextItem":{"title":"ISA(\uac1c\uc778\uc885\ud569\uc790\uc0b0\uad00\ub9ac\uacc4\uc88c) \uae30\ucd08 \ud574\uc124","permalink":"/blog/finance/isa-basics-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\ub2e4\uc74c \uc8fc FOMC\ub97c \uc55e\ub450\uace0, \ubbf8\uad6d \uc5f0\uc900\uacfc \ud55c\uad6d\uc740\ud589\uc758 \uae08\ub9ac \uacb0\uc815\uc744 \uc5b4\ub5bb\uac8c \uc77d\uc5b4\uc57c \ud558\ub294\uc9c0 \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uae08\ub9ac \uacb0\uc815 \uc8fc\uac04\uc774 \uc628\ub2e4\\n\\n2026\ub144 10\uc6d4 22\uc77c, \ud55c\uad6d\uc740\ud589 \uae08\uc735\ud1b5\ud654\uc704\uc6d0\ud68c\ub294 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 3.00%\ub85c \ub3d9\uacb0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubb3c\uac00 \uc555\ubc15\uc774 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370 \ucd94\uac00 \uc778\uc0c1 \uac00\ub2a5\uc131\ub3c4 \uac70\ub860\ub418\ub294 \'\ub9e4\ud30c\uc801 \ub3d9\uacb0\'\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\uc5b4\uc11c 10\uc6d4 27~28\uc77c\uc5d0\ub294 \ubbf8\uad6d \uc5f0\ubc29\uacf5\uac1c\uc2dc\uc7a5\uc704\uc6d0\ud68c(FOMC)\uac00 \uc5f4\ub9ac\uace0, \uacb0\uacfc\ub294 \ud55c\uad6d \uc2dc\uac01 10\uc6d4 29\uc77c \uc0c8\ubcbd 3\uc2dc\uc5d0 \ubc1c\ud45c\ub429\ub2c8\ub2e4.<br/>\\n\ub450 \uae08\ub9ac \uacb0\uc815\uc758 \uc77d\ub294 \ubc95\uc740 \ube44\uc2b7\ud558\uc9c0\ub9cc, \ud655\uc778\ud574\uc57c \ud560 \ud3ec\uc778\ud2b8\uac00 \uc870\uae08\uc529 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMnl5OGQ1djMwMWx2eDZtODI5OXB1OWk4YmF6dTR2eDV5ZTA5d2NtZCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/GFIpUu2yP0C5UEN10L/giphy.gif\\" alt=\\"Interest rate\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uae30\uc900\uae08\ub9ac\uac00 \ubb34\uc5c7\uc778\uac00\\n\\n#### \uc5f0\uc900\uc758 \uc5f0\ubc29\uae30\uae08\uae08\ub9ac\\n\\n\ubbf8\uad6d \uc5f0\uc900\uc774 \uc815\ud558\ub294 \uae30\uc900\uae08\ub9ac\ub294 \uc5f0\ubc29\uae30\uae08\uae08\ub9ac \ubaa9\ud45c \ubc94\uc704\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 9\uc6d4 15~16\uc77c \ud68c\uc758\uc5d0\uc11c 0.25%\ud3ec\uc778\ud2b8 \uc778\uc0c1\ub41c \ub4a4, \ud604\uc7ac \ubaa9\ud45c \ubc94\uc704\ub294 `3.75~4.00%`\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc740\ud589 \uac04 \ucd08\ub2e8\uae30 \ub300\ucd9c \uae08\ub9ac\ub97c \uaca8\ub0e5\ud55c \uac83\uc73c\ub85c, \ubbf8\uad6d \ub2ec\ub7ec \uc790\uae08\uc758 \uae30\uc900 \uac00\uaca9 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ud55c\uad6d\uc740\ud589\uc758 \uae30\uc900\uae08\ub9ac\\n\\n\ud55c\uad6d\uc740\ud589 \uae30\uc900\uae08\ub9ac\ub294 \ud604\uc7ac \uc5f0 3.00%\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 7\uc6d4\uacfc 8\uc6d4 \ub450 \ucc28\ub840\uc5d0 \uac78\uccd0 0.25%\ud3ec\uc778\ud2b8\uc529 \uc62c\ub790\uace0, 10\uc6d4 22\uc77c\uc5d0\ub294 \ub3d9\uacb0\ub418\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc900\uae08\ub9ac\ub294 \uc608\uae08\uacfc \ub300\ucd9c \uae08\ub9ac\uc758 \ucd9c\ubc1c\uc810\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc740\ud589 \ub300\ucd9c\uae08\ub9ac\ub294 \uae30\uc900\uae08\ub9ac\ubcf4\ub2e4 \ucf54\ud53d\uc2a4(COFIX) \uac19\uc740 \uc2dc\uc7a5 \uc9c0\ud45c\uc758 \uc601\ud5a5\uc744 \ub354 \ud06c\uac8c \ubc1b\uc2b5\ub2c8\ub2e4.<br/>\\n9\uc6d4 \uc2e0\uaddc\ucde8\uae09\uc561 \uae30\uc900 \ucf54\ud53d\uc2a4\ub294 `3.43%`\ub85c, \uc774\ubbf8 \uae30\uc900\uae08\ub9ac\ub97c \uc6c3\ub3cc\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### FOMC \ubc1c\ud45c \uc77d\ub294 \ubc95\\n\\n#### \uc5b8\uc81c, \ubb34\uc5c7\uc744 \ud655\uc778\ud558\ub294\uac00\\n\\nFOMC\ub294 10\uc6d4 27~28\uc77c \uc774\ud2c0\uac04 \ud68c\uc758\ub97c \ud558\uace0, \ubbf8\uad6d \ub3d9\ubd80 \uc2dc\uac01 28\uc77c \uc624\ud6c4 2\uc2dc\uc5d0 \uc131\uba85\uc11c\ub97c \ubc1c\ud45c\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d \uc2dc\uac01\uc73c\ub85c\ub294 10\uc6d4 29\uc77c \uc0c8\ubcbd 3\uc2dc\uc785\ub2c8\ub2e4.<br/>\\n30\ubd84 \ub4a4\uc5d0\ub294 \uc758\uc7a5 \uae30\uc790\ud68c\uacac\uc774 \uc774\uc5b4\uc9c0\ubbc0\ub85c, \uc0c8\ubcbd 3\uc2dc 30\ubd84\ubd80\ud130 \ucd94\uac00 \ubc1c\uc5b8\uc774 \ub098\uc635\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d\uc740 11\uc6d4 1\uc77c\uc5d0 \uc11c\uba38\ud0c0\uc784\uc774 \ub05d\ub098\ubbc0\ub85c, 12\uc6d4 \ud68c\uc758\ubd80\ud130\ub294 \uac19\uc740 \uc624\ud6c4 2\uc2dc \ubc1c\ud45c\uac00 \ud55c\uad6d \uc2dc\uac01 \uc0c8\ubcbd 4\uc2dc\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### 10\uc6d4 \ud68c\uc758\uc5d0\ub294 \uc810\ub3c4\ud45c\uac00 \uc5c6\ub2e4\\n\\n\uc5f0\uc900 \uc704\uc6d0\ub4e4\uc758 \uae08\ub9ac \uc804\ub9dd\uc744 \uc810\uc73c\ub85c \ucc0d\uc740 \uc810\ub3c4\ud45c(dot plot)\ub294 3\uc6d4, 6\uc6d4, 9\uc6d4, 12\uc6d4 \ud68c\uc758\uc5d0\ub9cc \ub098\uc635\ub2c8\ub2e4.<br/>\\n10\uc6d4 \ud68c\uc758\ub294 \uc810\ub3c4\ud45c\uac00 \uc5c6\ub294 \ud68c\uc758\uc774\ubbc0\ub85c, \uc131\uba85\uc11c \ubb38\uad6c\uc640 \uc758\uc7a5 \ubc1c\uc5b8\uc774 \ub354 \uc911\uc694\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\'\uc778\ub0b4\uc2ec\uc744 \uac00\uc9c8 \uc218 \uc788\ub2e4\', \'\ub370\uc774\ud130\uc5d0 \uc758\uc874\ud558\uaca0\ub2e4\' \uac19\uc740 \ubb38\uad6c\uc758 \ubbf8\ubb18\ud55c \ubcc0\ud654\uac00 \uc2dc\uc7a5\uc758 \ub2e8\uc11c\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ub3d9\uacb0\xb7\uc778\uc0c1\xb7\uc778\ud558\ubcf4\ub2e4 \ubc29\ud5a5\uc758 \ub2e8\uc11c\\n\\n\uae08\ub9ac\ub97c \uc62c\ub838\ub294\uc9c0 \ub0b4\ub838\ub294\uc9c0\ubcf4\ub2e4, \uc55e\uc73c\ub85c \uc5b4\ub514\ub85c \uac08\uc9c0\uac00 \ub354 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n10\uc6d4 22\uc77c \ud55c\uad6d\uc740\ud589 \uacb0\uc815\ub3c4 \ub3d9\uacb0\uc774\uc5c8\uc9c0\ub9cc \'\ub9e4\ud30c\uc801 \ub3d9\uacb0\'\ub85c \uc77d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc1c\ud45c\ubb38\uacfc \ucd1d\uc7ac \uae30\uc790\uac04\ub2f4\ud68c, FOMC\uc5d0\uc11c\ub294 \uc758\uc7a5 \uae30\uc790\ud68c\uacac\uc758 \ud45c\ud604\uc774 \ud5a5\ud6c4 \ubc29\ud5a5\uc744 \uac00\ub2a0\ud558\ub294 \ub2e8\uc11c\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc774 \uba3c\uc800 \uc6c0\uc9c1\uc774\ub294 \uac83\uc740 \uae08\ub9ac \uacb0\uc815 \uc790\uccb4\uac00 \uc544\ub2c8\ub77c \uadf8 \ud574\uc11d\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uae08\ub9ac\uac00 \uc2dc\uc7a5\uc5d0 \uc804\ub2ec\ub418\ub294 \uacbd\ub85c\\n\\n#### \ucc44\uad8c\uacfc \ub300\ucd9c\\n\\n\uae30\uc900\uae08\ub9ac\uac00 \uc624\ub974\uba74 \uc2dc\uc7a5\uae08\ub9ac\ub3c4 \ub530\ub77c \uc624\ub974\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucc44\uad8c \uac00\uaca9\uc740 \uae08\ub9ac\uc640 \ubc18\ub300\ub85c \uc6c0\uc9c1\uc774\ubbc0\ub85c, \uae08\ub9ac \uc0c1\uc2b9\uae30\uc5d0\ub294 \uae30\uc874 \ucc44\uad8c \uac00\uaca9\uc774 \ub5a8\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc740\ud589 \ubcc0\ub3d9\uae08\ub9ac \ub300\ucd9c\uc740 \ucf54\ud53d\uc2a4 \uc0c1\uc2b9\ubd84\ub9cc\ud07c \uc7ac\uc0b0\uc815\uc77c\uc5d0 \uae08\ub9ac\uac00 \uc62c\ub77c\uac11\ub2c8\ub2e4.<br/>\\n\\n#### \ud658\uc728\\n\\n\ubbf8\uad6d \uae08\ub9ac\uac00 \uc624\ub974\uba74 \ub2ec\ub7ec\uac00 \uac15\uc138\ub97c \ubcf4\uc774\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ubbf8 \uae08\ub9ac \ucc28\uc774\uc640 \ub2ec\ub7ec \ubc29\ud5a5\uc740 \uad6d\ub0b4 \uc99d\uc2dc\uc758 \uc678\uad6d\uc778 \uc218\uae09\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 10\uc6d4 23\uc77c `1,324.6\uc6d0`\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uae08\ub9ac \ubc1c\ud45c \ub2f9\uc77c\uc5d0\ub294 \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c, \ubc1c\ud45c \uc804\ud6c4\uc758 \ub274\uc2a4 \ud574\uc11d\uc744 \uc11c\ub450\ub974\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ub3d9\uacb0\xb7\uc778\uc0c1\xb7\uc778\ud558\uc758 \uc5ec\ubd80\ubcf4\ub2e4 \uc131\uba85\uc11c \ubb38\uad6c \ubcc0\ud654\uc640 \uc758\uc7a5 \ubc1c\uc5b8\uc744 \ud568\uaed8 \uc77d\ub294 \uc2b5\uad00\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ub0b4 \ub300\ucd9c \uae08\ub9ac\ub294 \uae30\uc900\uae08\ub9ac\ubcf4\ub2e4 \ucf54\ud53d\uc2a4\uc640 \uc7ac\uc0b0\uc815\uc77c\uc758 \uc601\ud5a5\uc744 \uba3c\uc800 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uae08\ub9ac \uacb0\uc815 \uad6c\uc870\ub97c \uc124\uba85\ud558\ub294 \uad50\uc721 \ubaa9\uc801\uc758 \ud574\uc124\uc774\uba70, \uae08\ub9ac \ubc29\ud5a5\uc744 \uc608\uce21\ud558\uac70\ub098 \ud22c\uc790\ub97c \uad8c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uae08\ub9ac \uacb0\uc815\uc740 \uc22b\uc790\ub97c \uc77d\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ubb38\uad6c\ub97c \uc77d\ub294 \uc77c\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.<br/>\\n10\uc6d4 29\uc77c \uc0c8\ubcbd \ubc1c\ud45c \ub4a4\uc5d0\ub294 \uc131\uba85\uc11c \uc6d0\ubb38\uc758 \ubb38\uad6c \ubcc0\ud654\ubd80\ud130 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc744 \uad8c\ud574\ub4dc\ub9bd\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media1.giphy.com/media/v1.Y2lkPTc5MGI3NjExMnl5OGQ1djMwMWx2eDZtODI5OXB1OWk4YmF6dTR2eDV5ZTA5d2NtZCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/M8doLiB9p18QFo8XIM/giphy.gif\\" alt=\\"Fed\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"isa-basics-guide","metadata":{"permalink":"/blog/finance/isa-basics-guide","source":"@site/finance/2026-10-23-isa-basics/index.mdx","title":"ISA(\uac1c\uc778\uc885\ud569\uc790\uc0b0\uad00\ub9ac\uacc4\uc88c) \uae30\ucd08 \ud574\uc124","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-23T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"personal-finance","permalink":"/blog/finance/tags/personal-finance"},{"inline":true,"label":"isa","permalink":"/blog/finance/tags/isa"},{"inline":true,"label":"tax","permalink":"/blog/finance/tags/tax"}],"readingTime":2.99,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"isa-basics-guide","title":"ISA(\uac1c\uc778\uc885\ud569\uc790\uc0b0\uad00\ub9ac\uacc4\uc88c) \uae30\ucd08 \ud574\uc124","authors":["way"],"tags":["finance","personal-finance","isa","tax"]},"unlisted":false,"prevItem":{"title":"FOMC\uc640 \uae08\ud1b5\uc704 \uae08\ub9ac \uacb0\uc815 \uc77d\ub294 \ubc95","permalink":"/blog/finance/fomc-bok-rate-decision-guide"},"nextItem":{"title":"\ucf54\uc2a4\ud53c, \uc7a5\uc911 4% \uae09\ub77d \ub51b\uace0 \ubc18\ub4f1 \u2014 10\uc6d4 23\uc77c \uc2dc\uc7a5 \uc815\ub9ac","permalink":"/blog/finance/kospi-4percent-rebound-oct23"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\ud558\ub098\uc758 \uacc4\uc88c\ub85c \uc5ec\ub7ec \uae08\uc735\uc0c1\ud488\uc744 \uad74\ub9ac\uba74\uc11c \uc138\uae08 \ud61c\ud0dd\uc744 \ubc1b\ub294 ISA\uc758 \uae30\ubcf8 \uad6c\uc870\ub97c \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uacc4\uc88c \ud558\ub098\uc5d0 \ub2f4\ub294 \uc808\uc138 \uad6c\uc870\\n\\nISA\ub294 Individual Savings Account\uc758 \uc57d\uc790\ub85c, \uc6b0\ub9ac\ub9d0\ub85c\ub294 \uac1c\uc778\uc885\ud569\uc790\uc0b0\uad00\ub9ac\uacc4\uc88c\uc785\ub2c8\ub2e4.<br/>\\n\uc608\uae08, \ud380\ub4dc, ETF, \uad6d\ub0b4 \uc0c1\uc7a5\uc8fc\uc2dd \ub4f1\uc744 \ud558\ub098\uc758 \uacc4\uc88c\uc5d0 \ub2f4\uc544 \uc6b4\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud575\uc2ec\uc740 \uac01 \uc0c1\ud488\uc758 \uc218\uc775\uc744 \ub530\ub85c\ub530\ub85c \uacfc\uc138\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uacc4\uc88c \uc804\uccb4\uc758 \uc21c\uc774\uc775\uc744 \uae30\uc900\uc73c\ub85c \uc138\uae08 \ud61c\ud0dd\uc744 \uc8fc\ub294 \uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc190\uc2e4\uacfc \uc774\uc775\uc744 \ud569\uc0b0\ud558\ub294 \'\uc190\uc775\ud1b5\uc0b0\' \uad6c\uc870 \ub355\ubd84\uc5d0 \uc2e4\ud6a8\uc138\uc728\uc774 \ub0ae\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExaW50YW51MXp0dGFrbHI4MnBhbjdxd2ZvMWFhbGwxNnFwcHN4bjVuayZlcD12MV9naWZzX3NlYXJjaCZjdD1n/7JMFaaqRtn6K2jUd2O/giphy.gif\\" alt=\\"Savings\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uac00\uc785\uacfc \ub0a9\uc785\uc758 \uaddc\uce59\\n\\n#### \ub204\uac00 \uac00\uc785\ud560 \uc218 \uc788\ub294\uac00\\n\\n\uac00\uc785\uc77c \uae30\uc900\uc73c\ub85c 19\uc138 \uc774\uc0c1\uc778 \uac70\uc8fc\uc790\uac00 \uac00\uc785 \ub300\uc0c1\uc785\ub2c8\ub2e4.<br/>\\n15\uc138 \uc774\uc0c1\uc774\ub77c\ub3c4 \uac00\uc785\uc77c\uc774 \uc18d\ud55c \ud574\uc758 \uc9c1\uc804 \uacfc\uc138\uae30\uac04\uc5d0 \uadfc\ub85c\uc18c\ub4dd\uc774 \uc788\uc73c\uba74 \uac00\uc785\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n1\uc778\ub2f9 1\uac1c\uc758 \uacc4\uc88c\ub9cc \ubcf4\uc720\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc9c1\uc804 3\uac1c \uacfc\uc138\uae30\uac04 \uc911 \ud55c \ubc88\uc774\ub77c\ub3c4 \uae08\uc735\uc18c\ub4dd\uc885\ud569\uacfc\uc138 \ub300\uc0c1\uc774\uc5c8\ub358 \uacbd\uc6b0\uc5d0\ub294 \uacfc\uc138\ud2b9\ub840\uac00 \uc801\uc6a9\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub0a9\uc785\ud55c\ub3c4\uc640 \uc758\ubb34\uae30\uac04\\n\\n\uc5f0\uac04 \ub0a9\uc785\ud55c\ub3c4\ub294 `2,000\ub9cc \uc6d0`, \ucd1d \ub0a9\uc785\ud55c\ub3c4\ub294 `1\uc5b5 \uc6d0`\uc785\ub2c8\ub2e4.<br/>\\n\ubabb \ucc44\uc6b4 \uc5f0\uac04 \ud55c\ub3c4\ub294 \ub2e4\uc74c \ud574\ub85c \uc774\uc6d4\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uacc4\uc57d\uae30\uac04\uc740 3\ub144 \uc774\uc0c1\uc774\uc5b4\uc57c \ud569\ub2c8\ub2e4.<br/>\\n3\ub144 \uc804\uc5d0 \ud574\uc9c0\ud558\uba74 \uac10\uba74\ubc1b\uc740 \uc138\uae08\uc744 \ucd94\uc9d5\ub2f9\ud558\ubbc0\ub85c, 3\ub144\uac04 \ubb36\uc77c \uc218 \uc788\ub294 \uc5ec\uc720 \uc790\uae08\uc73c\ub85c \ub0a9\uc785\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc138 \uac00\uc9c0 \uc720\ud615\\n\\nISA\ub294 \uc6b4\uc6a9 \ubc29\uc2dd\uc5d0 \ub530\ub77c \uc911\uac1c\ud615, \uc2e0\ud0c1\ud615, \uc77c\uc784\ud615\uc73c\ub85c \ub098\ub269\ub2c8\ub2e4.<br/>\\n\uc911\uac1c\ud615\uc740 \ud22c\uc790\uc790\uac00 \uc9c1\uc811 \uc8fc\uc2dd\uacfc ETF\ub97c \uc0ac\uace0\ud314 \uc218 \uc788\ub294 \uc720\ud615\uc73c\ub85c, \uc99d\uad8c\uc0ac\uc5d0\uc11c\ub9cc \uac1c\uc124\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e0\ud0c1\ud615\uc740 \uae08\uc735\ud68c\uc0ac\uac00 \ud22c\uc790\uc790\uc758 \uc9c0\uc2dc\ub97c \ubc1b\uc544 \uc6b4\uc6a9\ud558\uba70 \uc608\uae08 \uc704\uc8fc\uc758 \ubcf4\uc218\uc801 \uc6b4\uc6a9\uc5d0 \uc801\ud569\ud569\ub2c8\ub2e4.<br/>\\n\uc77c\uc784\ud615\uc740 \uc6b4\uc6a9\uc0ac\uc5d0 \uc790\uc0b0 \uc6b4\uc6a9\uc744 \ub9e1\uae30\ub294 \ubc29\uc2dd\uc73c\ub85c, \uc218\uc218\ub8cc\uac00 \ubc1c\uc0dd\ud569\ub2c8\ub2e4.<br/>\\n\\n### \uc138\uc81c \ud61c\ud0dd\uc758 \uad6c\uc870\\n\\n#### \ube44\uacfc\uc138 \ud55c\ub3c4\\n\\n\uacc4\uc88c\uc5d0\uc11c \ubc1c\uc0dd\ud55c \uc774\uc790\xb7\ubc30\ub2f9 \uc18c\ub4dd\uc740 \uc77c\ubc18\ud615 \uae30\uc900 `200\ub9cc \uc6d0`\uae4c\uc9c0 \ube44\uacfc\uc138\uc785\ub2c8\ub2e4.<br/>\\n\uc11c\ubbfc\ud615(\ucd1d\uae09\uc5ec 5,000\ub9cc \uc6d0 \uc774\ud558 \ub4f1)\uacfc \ub18d\uc5b4\ubbfc\ud615\uc740 `400\ub9cc \uc6d0`\uae4c\uc9c0 \ube44\uacfc\uc138\uc785\ub2c8\ub2e4.<br/>\\n\uc77c\ubc18 \uacc4\uc88c\uc5d0\uc11c ETF\ub85c \ubc88 \uc218\uc775\uc5d0 \ubd99\ub294 \uc138\uc728\uc774 `15.4%`\uc778 \uac83\uacfc \ube44\uad50\ud558\uba74 \ucc28\uc774\uac00 \ud07d\ub2c8\ub2e4.<br/>\\n\\n#### \ucd08\uacfc\ubd84\uc740 9% \ubd84\ub9ac\uacfc\uc138\\n\\n\ube44\uacfc\uc138 \ud55c\ub3c4\ub97c \ucd08\uacfc\ud558\ub294 \uc21c\uc774\uc775\uc5d0\ub294 `9%`\uc758 \uc138\uc728\ub85c \ubd84\ub9ac\uacfc\uc138\uac00 \uc801\uc6a9\ub429\ub2c8\ub2e4.<br/>\\n\ub18d\uc5b4\ucd0c\ud2b9\ubcc4\uc138\ub97c \ud3ec\ud568\ud558\uba74 \uc2e4\ud6a8\uc138\uc728\uc740 `9.9%`\uc785\ub2c8\ub2e4.<br/>\\n\ubd84\ub9ac\uacfc\uc138\uc774\ubbc0\ub85c \uae08\uc735\uc18c\ub4dd\uc885\ud569\uacfc\uc138\uc5d0 \ud569\uc0b0\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\ub3c4 \uc7a5\uc810\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ubc30\ub2f9\uc18c\ub4dd \uc790\uccb4\ub294 ISA \uc548\uc5d0\uc11c\ub3c4 \uc6d0\ucc9c\uc9d5\uc218 \uac1c\ub150\uc774 \uc801\uc6a9\ub418\ubbc0\ub85c, \uc21c\uc774\uc775 \uae30\uc900\uc73c\ub85c \uc815\uc0b0\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \uc190\uc775\ud1b5\uc0b0\uc758 \ud6a8\uacfc\\n\\n\ud55c \uc0c1\ud488\uc5d0\uc11c \uc190\uc2e4\uc774 \ub098\ub3c4 \ub2e4\ub978 \uc0c1\ud488\uc758 \uc774\uc775\uacfc \uc0c1\uc1c4\ud55c \ub4a4 \uc21c\uc774\uc775\uc5d0\ub9cc \uacfc\uc138\ud569\ub2c8\ub2e4.<br/>\\n\uac1c\ubcc4 \uc0c1\ud488\ub9c8\ub2e4 \uc138\uae08\uc744 \uacc4\uc0b0\ud558\ub294 \uc77c\ubc18 \uacc4\uc88c\ubcf4\ub2e4 \uc2e4\ud6a8\uc138\uc728\uc774 \ub0ae\uc544\uc9c0\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \ub54c\ubb38\uc5d0 ISA\ub294 \ub2e8\uc77c \uc0c1\ud488\ubcf4\ub2e4\ub294 \uc5ec\ub7ec \uc0c1\ud488\uc744 \ud568\uaed8 \ub2f4\uc744 \ub54c \ud6a8\uacfc\uac00 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\\n### 2026\ub144 \ub17c\uc758 \uc911\uc778 \uac1c\ud3b8\\n\\n#### \ubb34\uc5c7\uc774 \ubc14\ub00c\ub824 \ud558\ub294\uac00\\n\\n2026\ub144 \uc138\uc81c\uac1c\ud3b8\uc548\uc5d0\ub294 ISA \uad00\ub828 \uac1c\ud3b8\uc774 \ud3ec\ud568\ub418\uc5b4 \ub17c\uc758 \uc911\uc785\ub2c8\ub2e4.<br/>\\n\uc5f0\uac04 \ub0a9\uc785\ud55c\ub3c4 \ud655\ub300, \ubbf8\uc0ac\uc6a9 \uc5f0\uac04 \ud55c\ub3c4\uc758 \ub2e4\uc74c \ud574 \uc774\uc6d4 \uc81c\ub3c4 \ud3d0\uc9c0(2027\ub144 \uc2dc\ud589 \uc608\uc815), \uc0dd\uc0b0\uc801\uae08\uc735 ISA \uc2e0\uc124 \ub4f1\uc774 \uac70\ub860\ub429\ub2c8\ub2e4.<br/>\\n\uc0dd\uc0b0\uc801\uae08\uc735 ISA\ub294 \uad6d\ub0b4 \uc8fc\uc2dd\xb7\ud380\ub4dc \uc804\uc6a9 \uacc4\uc88c\ub85c \uc774\uc790\xb7\ubc30\ub2f9\uc18c\ub4dd \uc804\uc561 \ube44\uacfc\uc138\ub97c \ud2b9\uc9d5\uc73c\ub85c \ud558\ub294 \ubc29\uc548\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc544\uc9c1 \uc2dc\ud589 \uc804\uc774\ub2e4\\n\\n\uc704 \ub0b4\uc6a9\uc740 \ubaa8\ub450 \ub17c\uc758\xb7\uc608\uace0 \ub2e8\uacc4\uc774\uba70, \uc785\ubc95 \uacfc\uc815\uc744 \uac70\uccd0 \ud655\uc815\ub429\ub2c8\ub2e4.<br/>\\n\uc2dc\ud589 \uc804\uc5d0\ub294 \uae30\uc874 \uaddc\uce59\uc774 \uc801\uc6a9\ub418\ubbc0\ub85c, \ud604\uc7ac \ub0a9\uc785 \uacc4\ud68d\uc740 \ud604\ud589 \uae30\uc900\uc73c\ub85c \uc138\uc6c1\ub2c8\ub2e4.<br/>\\n\uac1c\ud3b8\uc774 \ud655\uc815\ub418\uba74 \ub0a9\uc785 \uc804\ub7b5\ub3c4 \uadf8\ub54c \ub2e4\uc2dc \uc810\uac80\ud558\uba74 \ub429\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\nISA\ub294 3\ub144 \uc758\ubb34\uae30\uac04\uc774 \uc788\uc73c\ubbc0\ub85c \ub2e8\uae30 \uc790\uae08\uc774 \uc544\ub2cc \uc911\uc7a5\uae30 \uc5ec\uc720 \uc790\uae08\uc73c\ub85c \uc6b4\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uc5f0\uae08\uc800\ucd95\xb7IRP\ub294 \ub178\ud6c4 \uc790\uae08\uc758 \uc138\uc561\uacf5\uc81c\uac00 \ubaa9\uc801\uc774\uace0, ISA\ub294 \uc6b4\uc6a9 \uc911 \uc138\uae08 \uc808\uac10\uc774 \ubaa9\uc801\uc774\ub77c\ub294 \uc810\uc774 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\uc911\ub3c4\ud574\uc9c0 \uc2dc \uc138\uae08 \ucd94\uc9d5\uc774 \ubc1c\uc0dd\ud558\ubbc0\ub85c, \ud574\uc9c0 \uc2dc\uc810\ub3c4 3\ub144 \uc774\ud6c4\ub85c \uacc4\ud68d\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 ISA \uc81c\ub3c4\ub97c \uc124\uba85\ud558\ub294 \uad50\uc721 \ubaa9\uc801\uc758 \ud574\uc124\uc774\uba70, ISA \uac00\uc785 \uc790\uccb4\ub97c \uad8c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\nISA\ub294 \uc190\uc775\ud1b5\uc0b0\uacfc \ube44\uacfc\uc138 \ud55c\ub3c4\uac00 \ub9cc\ub4dc\ub294 \uc808\uc138 \uad6c\uc870\ub97c \uc774\ud574\ud558\uba74 \ud65c\uc6a9\ub3c4\uac00 \ub192\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n3\ub144 \uc758\ubb34\uae30\uac04\uc744 \uac10\ub2f9\ud560 \uc218 \uc788\ub294 \uc790\uae08\uc778\uc9c0 \uba3c\uc800 \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uac00\uc7a5 \uc911\uc694\ud55c \ucd9c\ubc1c\uc810\uc785\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExaW50YW51MXp0dGFrbHI4MnBhbjdxd2ZvMWFhbGwxNnFwcHN4bjVuayZlcD12MV9naWZzX3NlYXJjaCZjdD1n/zbsMLe0hKqS2nNJ7LT/giphy.gif\\" alt=\\"ISA\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"kospi-4percent-rebound-oct23","metadata":{"permalink":"/blog/finance/kospi-4percent-rebound-oct23","source":"@site/finance/2026-10-23-kospi-4percent-rebound/index.mdx","title":"\ucf54\uc2a4\ud53c, \uc7a5\uc911 4% \uae09\ub77d \ub51b\uace0 \ubc18\ub4f1 \u2014 10\uc6d4 23\uc77c \uc2dc\uc7a5 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-23T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"market-recap","permalink":"/blog/finance/tags/market-recap"},{"inline":true,"label":"kospi","permalink":"/blog/finance/tags/kospi"}],"readingTime":2.66,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kospi-4percent-rebound-oct23","title":"\ucf54\uc2a4\ud53c, \uc7a5\uc911 4% \uae09\ub77d \ub51b\uace0 \ubc18\ub4f1 \u2014 10\uc6d4 23\uc77c \uc2dc\uc7a5 \uc815\ub9ac","authors":["way"],"tags":["finance","market-recap","kospi"]},"unlisted":false,"prevItem":{"title":"ISA(\uac1c\uc778\uc885\ud569\uc790\uc0b0\uad00\ub9ac\uacc4\uc88c) \uae30\ucd08 \ud574\uc124","permalink":"/blog/finance/isa-basics-guide"},"nextItem":{"title":"\ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uad00\uacc4 \u2014 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \ucc44\uad8c\uac12\uc774 \ub5a8\uc5b4\uc9c0\ub294 \uc774\uc720","permalink":"/blog/finance/bond-price-yield"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n10\uc6d4 23\uc77c \uae08\uc694\uc77c \uc7a5 \ub9c8\uac10 \ub3d9\ud5a5\uacfc \ub2e4\uc74c \uc8fc\uc5d0 \ud655\uc778\ud560 \uc77c\uc815\uc744 \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 4% \ub118\uac8c \ud754\ub4e4\ub9b0 \ud558\ub8e8\\n\\n\uac04\ubc24 \ub274\uc695\uc99d\uc2dc\uc5d0\uc11c \ubc18\ub3c4\uccb4\uc8fc\uac00 \uc57d\uc138\ub97c \ubcf4\uc778 \uc5ec\ud30c\ub85c, 10\uc6d4 23\uc77c \ucf54\uc2a4\ud53c\ub294 2.36% \ud558\ub77d\ud55c `5,403.17`\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc774\ud6c4 \uc678\uad6d\uc778\uc758 \ub9e4\ub3c4\uc138\uac00 \ud655\ub300\ub418\uba70 \uc7a5\uc911 \ud55c\ub54c `5,305.98`\uae4c\uc9c0 \ubc00\ub838\uace0, \uc804\uc77c \ub300\ube44 \ub099\ud3ed\uc740 4%\ub97c \ub118\uc5b4\uc130\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uc624\ud6c4 \ub4e4\uc5b4 \uae30\uad00\uc758 \ub9e4\uc218\uc138\uac00 \uc720\uc785\ub418\uba70 \ub099\ud3ed\uc744 \ube60\ub974\uac8c \uc904\uc600\uace0, \uc7a5\uc911 \ucd5c\uace0\uc810\uc5d0\uc11c `5,550.30`(+0.30%, +16.53\ud3ec\uc778\ud2b8)\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub8e8 \ub4f1\ub77d\ub960\uc740 0.30%\uc5d0 \ubd88\uacfc\ud588\uc9c0\ub9cc, \uc7a5\uc911 \uc9c4\ud3ed\uc774 4%\ud3ec\uc778\ud2b8\ub97c \ub118\uc740 \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZmR1MzltcWFlZmFzcDNnMWJjZWl1ZDNxYnZ0a3gzN3U4Y2JvZ2d1MSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/1AjFk7MzJBT2UPYKLB/giphy.gif\\" alt=\\"Market\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc678\uad6d\uc778\uc774 \ud310 \ub9cc\ud07c \uae30\uad00\uc774 \ubc1b\uc544 \uc0c0\ub2e4\\n\\n#### \uc218\uae09 \uad6c\uc870\\n\\n\uc678\uad6d\uc778\uc774 \uc57d 1\uc870 \uc6d0 \uac00\uae4c\uc774 \uc21c\ub9e4\ub3c4\ud558\uba70 \ub9e4\ub3c4 \uc6b0\uc704\ub97c \uc774\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uae30\uad00\uc740 8\ucc9c\uc5b5 \uc6d0\ub300 \uc21c\ub9e4\uc218, \uac1c\uc778\ub3c4 \uc21c\ub9e4\uc218\uc5d0 \ub3d9\ucc38\ud558\uba70 \uc9c0\uc218 \ubc18\ub4f1\uc744 \ub4b7\ubc1b\uce68\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\ub3c4 \ubb3c\ub7c9\uc758 \ubc18\ub300\ud3b8\uc5d0 \uad6d\ub0b4 \uae30\uad00\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \uc624\ub298 \uc2dc\uc7a5\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ubc18\ub4f1\uc758 \uc911\uc2ec \u2014 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\\n\\n\uc7a5 \ucd08\ubc18 5% \ub118\uac8c \ubc00\ub838\ub358 SK\ud558\uc774\ub2c9\uc2a4\ub294 \uc190\uc790\ud68c\uc0ac \uc194\ub9ac\ub2e4\uc784\uc758 \ubbf8\uad6d \uc99d\uc2dc \uc0c1\uc7a5 \uc808\ucc28 \uc911\ub2e8 \uc18c\uc2dd\uc774 \uc804\ud574\uc9c4 \ub4a4 \uc0c1\uc2b9 \uc804\ud658\ud574 4.42% \uc624\ub978 `1,277,000\uc6d0`\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0bc\uc131\uc804\uc790\ub294 \uc7a5\uc911 5% \ub118\uac8c \ud558\ub77d\ud588\ub2e4\uac00 \uc624\ud6c4\uc5d0 \uc0c1\uc2b9 \uc804\ud658\ud574 0.47% \uc624\ub978 `215,500\uc6d0`\uc5d0 \uac70\ub798\ub97c \ub9c8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc885\ubaa9\uc744 \ubb36\uc5b4 \ubd80\ub974\ub294 \'\uc0bc\uc804\ub2c9\uc2a4\'\uac00 \uc9c0\uc218 \ud68c\ubcf5\uc744 \uacac\uc778\ud55c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc0c1\uc2b9 \uc885\ubaa9\uacfc \ud558\ub77d \uc885\ubaa9\\n\\n\uc0bc\uc131\ubc14\uc774\uc624\ub85c\uc9c1\uc2a4\ub294 7.71% \uae09\ub4f1\ud55c `1,466,000\uc6d0`\uc5d0 \uac70\ub798\ub97c \ub9c8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0bc\uc131\uc804\uc790\uc6b0(+0.48%), SK\uc2a4\ud018\uc5b4(+3.20%), \uc0bc\uc131\uc0dd\uba85(+1.45%)\ub3c4 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 LG\uc5d0\ub108\uc9c0\uc194\ub8e8\uc158(-1.79%), \uc0bc\uc131SDI(-4.20%), \ud604\ub300\ucc28(-1.99%), KB\uae08\uc735(-3.29%)\uc740 \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc \uc548\uc5d0\uc11c\ub3c4 \uc5c7\uac08\ub9b0 \ud750\ub984\uc774 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ucf54\uc2a4\ub2e5\uc740 \ubc18\ub4f1\uc5d0 \uc2e4\ud328\ud588\ub2e4\\n\\n\ucf54\uc2a4\ub2e5\uc740 12.41\ud3ec\uc778\ud2b8(-1.62%) \ub0b4\ub9b0 `751.69`\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uac01\uac01 \uc218\ubc31\uc5b5 \uc6d0\uc529 \uc21c\ub9e4\ub3c4\ud588\uace0, \uac1c\uc778\uc740 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00\ucd1d\uc561 \uc0c1\uc704 \uc885\ubaa9 \ub300\ubd80\ubd84\uc774 \uc57d\uc138\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5d0\ucf54\ud504\ub85c(-5.83%, 72,700\uc6d0), \uc5d0\ucf54\ud504\ub85c\ube44\uc5e0(-5.50%), \uc54c\ud14c\uc624\uc820(-2.81%), \ub9ac\ub178\uacf5\uc5c5(-4.05%), \ub808\uc778\ubcf4\uc6b0\ub85c\ubcf4\ud2f1\uc2a4(-3.42%) \ub4f1\uc774 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ucc28\uc804\uc9c0\uc8fc\uc640 \ubc18\ub3c4\uccb4 \uc7a5\ube44\uc8fc\uac00 \ud568\uaed8 \ub20c\ub9b0 \uac83\uc774 \ucf54\uc2a4\ub2e5 \uc57d\uc138\uc758 \ubc30\uacbd\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ud658\uc728\uacfc \ud574\uc678 \ubcc0\uc218\\n\\n\uc11c\uc6b8 \uc678\ud658\uc2dc\uc7a5\uc5d0\uc11c \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 \uc804\uc77c \uc8fc\uac04 \uc885\uac00\ubcf4\ub2e4 0.4\uc6d0 \uc624\ub978 `1,324.6\uc6d0`\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d\uc5d0\uc11c\ub294 \ub098\uc2a4\ub2e5\uc885\ud569\uc9c0\uc218\uac00 2.60%, S&P500\uc774 1.21% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nAI \ud22c\uc790 \uc9c0\uc18d\uc131\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uad6d\ub0b4 \ubc18\ub3c4\uccb4\uc8fc\ub85c \uc804\uc774\ub41c \ub4a4 \uc624\ud6c4\uc5d0 \uc9c4\uc815\ub41c \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \ub9c8\uac10 \uc2dc\ud669\uc740 [\ub354\ud329\ud2b8](https://news.tf.co.kr/read/economy/2380152.htm)\uc640 [\ub274\uc2a4\ud54c](https://m.newspim.com/news/view/20261023001023) \uae30\uc0ac\ub85c \uad50\ucc28 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc7a5\uc911 4% \uae09\ub77d\uacfc \uc885\uac00 \ubc18\ub4f1\uc740 \uc131\uaca9\uc774 \ub2e4\ub978 \uc2e0\ud638\uc785\ub2c8\ub2e4.<br/>\\n\uc885\uac00\ub9cc \ubcf4\uba74 0.30% \uc0c1\uc2b9\uc774\uc9c0\ub9cc, \uc7a5\uc911 \ud754\ub4e4\ub9bc\uc758 \ud3ed\uc744 \ud568\uaed8 \ubd10\uc57c \ub2e4\uc74c \uc8fc \ubcc0\ub3d9\uc131\uc744 \uac00\ub2a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \uc21c\ub9e4\ub3c4\uac00 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370 \ubc18\ub4f1\uc774 \uad6d\ub0b4 \uc218\uae09\uc5d0 \uc758\uc874\ud588\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uc8fc \uc77c\uc815\uc740 10\uc6d4 27~28\uc77c \ubbf8\uad6d FOMC \ud68c\uc758(\ud55c\uad6d \uc2dc\uac01 10\uc6d4 29\uc77c \uc0c8\ubcbd 3\uc2dc \uacb0\uacfc \ubc1c\ud45c)\uc640 \uc8fc\uc694 \uae30\uc5c5 \uc2e4\uc801 \ubc1c\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uacb0\uc815\uacfc \uc2e4\uc801 \uc22b\uc790\uac00 \ub098\uc628 \ub4a4\uc5d0\ub294, \uc624\ub298 \ubc18\ub4f1\uc758 \uadfc\uac70\uac00 \uc720\uc9c0\ub418\ub294\uc9c0 \ub2e4\uc2dc \uc810\uac80\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc7a5\uc911 4% \uae09\ub77d\uc744 \ub51b\uace0 \uc624\ub978 0.30%\ub294 \uc885\uac00\ubcf4\ub2e4 \uc9c4\ud3ed\uc5d0 \uc8fc\ubaa9\ud574\uc57c \ud558\ub294 \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uc8fc FOMC \uacb0\uacfc\uae4c\uc9c0 \ud655\uc778\ud55c \ub4a4\uc5d0 \uc774\ubc88 \ubc18\ub4f1\uc758 \uc131\uaca9\uc744 \ub2e4\uc2dc \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExNWJ1ZHMwM2FvbHFvZXQ4NjBhdjFpcjR3d2VuYyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/4xpB3eE00FfBm/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"bond-price-yield","metadata":{"permalink":"/blog/finance/bond-price-yield","source":"@site/finance/2026-10-22-bond-price-yield/index.mdx","title":"\ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uad00\uacc4 \u2014 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \ucc44\uad8c\uac12\uc774 \ub5a8\uc5b4\uc9c0\ub294 \uc774\uc720","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-22T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"bond","permalink":"/blog/finance/tags/bond"},{"inline":true,"label":"interest-rate","permalink":"/blog/finance/tags/interest-rate"}],"readingTime":2.87,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"bond-price-yield","title":"\ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uad00\uacc4 \u2014 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \ucc44\uad8c\uac12\uc774 \ub5a8\uc5b4\uc9c0\ub294 \uc774\uc720","authors":["way"],"tags":["finance","bond","interest-rate"]},"unlisted":false,"prevItem":{"title":"\ucf54\uc2a4\ud53c, \uc7a5\uc911 4% \uae09\ub77d \ub51b\uace0 \ubc18\ub4f1 \u2014 10\uc6d4 23\uc77c \uc2dc\uc7a5 \uc815\ub9ac","permalink":"/blog/finance/kospi-4percent-rebound-oct23"},"nextItem":{"title":"\ucf54\uc2a4\ud53c 3.52% \uae09\ub77d \u2014 \ud558\ub8e8 \ub9cc\uc5d0 \ub4a4\uc9d1\ud78c \uc2dc\uc7a5, \ud558\ub77d\uc7a5\uc5d0\uc11c \ud655\uc778\ud560 \uac83\ub4e4","permalink":"/blog/finance/kospi-plunge-oct22"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \ud55c\uad6d\uc740\ud589\uc774 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 3.00%\ub85c \ub3d9\uacb0\ud55c \ub0a0\uc5d0 \ub9de\ucdb0, \ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uad00\uacc4\ub97c \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uc624\ub298\uc758 \uae08\ub9ac \uacb0\uc815\\n\\n2026\ub144 10\uc6d4 22\uc77c, \ud55c\uad6d\uc740\ud589 \uae08\uc735\ud1b5\ud654\uc704\uc6d0\ud68c\ub294 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 3.00%\ub85c \ub3d9\uacb0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubb3c\uac00 \uc555\ubc15\uc774 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370 11\uc6d4 \ucd94\uac00 \uc778\uc0c1 \uac00\ub2a5\uc131\ub3c4 \uac70\ub860\ub418\ub294 \uc0c1\ud669\uc785\ub2c8\ub2e4.<br/>\\n\uae30\uc900\uae08\ub9ac\ub294 \uc2dc\uc911 \uae08\ub9ac\uc758 \uae30\uc900\uc810\uc774 \ub418\uace0, \uc2dc\uc911 \uae08\ub9ac\ub294 \ucc44\uad8c \uac00\uaca9\uc744 \uc6c0\uc9c1\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \ub274\uc2a4\uac00 \ucc44\uad8c \ud22c\uc790\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \uc8fc\ub294\uc9c0 \uc774\ud574\ud558\ub824\uba74, \uba3c\uc800 \ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uad00\uacc4\ub97c \uc54c\uc544\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExNHc0MjBibDZvZDY0dzFib2g0YzNmbzFkZTVwb3N3MDV1c2loZm04MiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/1BPvv1QvbKV156jyul/giphy.gif\\" alt=\\"Money\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\ub294 \uc65c \ubc18\ub300\ub85c \uc6c0\uc9c1\uc774\ub294\uac00\\n\\n#### \ucc44\uad8c\uc758 \uae30\ubcf8 \uad6c\uc870\\n\\n\ucc44\uad8c\uc740 \ubc1c\ud589\uc790\uac00 \ud22c\uc790\uc790\uc5d0\uac8c \uc6d0\uae08\uacfc \uc774\uc790\ub97c \uc57d\uc18d\ud558\ub294 \uc99d\uc11c\uc785\ub2c8\ub2e4.<br/>\\n\uc561\uba74\uae08\uc561, \ud45c\uba74\uae08\ub9ac(\ucfe0\ud3f0\uae08\ub9ac), \ub9cc\uae30\uac00 \ubc1c\ud589 \uc2dc\uc810\uc5d0 \uc815\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4 \uc561\uba74 10,000\uc6d0, \ud45c\uba74\uae08\ub9ac \uc5f0 3%, \ub9cc\uae30 3\ub144\uc778 \ucc44\uad8c\uc740 \ub9e4\ub144 300\uc6d0\uc758 \uc774\uc790\ub97c \uc9c0\uae09\ud558\uace0 \ub9cc\uae30\uc5d0 10,000\uc6d0\uc744 \ub3cc\ub824\uc90d\ub2c8\ub2e4.<br/>\\n\uc774 \uc870\uac74\uc740 \ubc1c\ud589 \uc774\ud6c4\uc5d0\ub3c4 \ubc14\ub00c\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc2dc\uc7a5\uae08\ub9ac\uac00 \uc624\ub974\uba74 \uae30\uc874 \ucc44\uad8c\uc758 \ub9e4\ub825\uc774 \ub5a8\uc5b4\uc9c4\ub2e4\\n\\n\ucc44\uad8c\uc740 \ubc1c\ud589 \ud6c4\uc5d0\ub3c4 \uc2dc\uc7a5\uc5d0\uc11c \uc0ac\uace0\ud314 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub54c \ucc44\uad8c \uac00\uaca9\uc740 \uc2dc\uc7a5\uae08\ub9ac\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uae08\ub9ac\uac00 3%\uc77c \ub54c \uc5f0 3% \uc774\uc790\ub97c \uc8fc\ub294 \ucc44\uad8c\uc740 \uc561\uba74\uac00\uc778 10,000\uc6d0\uc5d0 \uac70\ub798\ub429\ub2c8\ub2e4.<br/>\\n\uadf8\ub7f0\ub370 \uc2dc\uc7a5\uae08\ub9ac\uac00 4%\ub85c \uc624\ub974\uba74, \uc0c8\ub85c \ubc1c\ud589\ub418\ub294 \ucc44\uad8c\uc740 \uc5f0 4%\uc758 \uc774\uc790\ub97c \uc90d\ub2c8\ub2e4.<br/>\\n\uae30\uc874\uc758 \uc5f0 3% \ucc44\uad8c\uc740 \uc0c8 \ucc44\uad8c\ubcf4\ub2e4 \ub9e4\ub825\uc774 \ub5a8\uc5b4\uc9c0\ubbc0\ub85c, \ub204\uad70\uac00 \uc0ac\ub824\uba74 \uac00\uaca9\uc774 10,000\uc6d0\ubcf4\ub2e4 \ub0ae\uc544\uc838\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uac00\uaca9\uc774 \ub5a8\uc5b4\uc9c0\uba74 \uadf8 \ucc44\uad8c\uc744 \uc0b0 \ud22c\uc790\uc790\uc758 \uc2e4\uc9c8 \uc218\uc775\ub960(\ub9cc\uae30\uc218\uc775\ub960)\uc740 4%\uc5d0 \uac00\uae4c\uc6cc\uc9d1\ub2c8\ub2e4.<br/>\\n\uc989, \uc2dc\uc7a5\uae08\ub9ac \uc0c1\uc2b9\uc740 \uae30\uc874 \ucc44\uad8c \uac00\uaca9 \ud558\ub77d\uc73c\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\\n#### \uc2dc\uc7a5\uae08\ub9ac\uac00 \ub0b4\ub9ac\uba74 \ubc18\ub300\ub85c \uc6c0\uc9c1\uc778\ub2e4\\n\\n\ubc18\ub300\ub85c \uc2dc\uc7a5\uae08\ub9ac\uac00 2%\ub85c \ub0b4\ub9ac\uba74, \uc5f0 3% \uc774\uc790\ub97c \uc8fc\ub294 \uae30\uc874 \ucc44\uad8c\uc740 \uadc0\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\uc0c8 \ucc44\uad8c\ubcf4\ub2e4 \uc774\uc790\ub97c \ub9ce\uc774 \uc8fc\ubbc0\ub85c, \uac00\uaca9\uc774 10,000\uc6d0\ubcf4\ub2e4 \ub192\uac8c \ud615\uc131\ub429\ub2c8\ub2e4.<br/>\\n\uac00\uaca9\uc774 \uc624\ub974\uba74 \uc2e4\uc9c8 \uc218\uc775\ub960\uc740 2%\uc5d0 \uac00\uae4c\uc6cc\uc9d1\ub2c8\ub2e4.<br/>\\n\uc815\ub9ac\ud558\uba74 \ucc44\uad8c \uac00\uaca9\uacfc \uc2dc\uc7a5\uae08\ub9ac\ub294 \ud56d\uc0c1 \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uacc4\uc0b0 \uc608\uc2dc\ub85c \ud655\uc778\ud558\uae30\\n\\n#### \ub2e8\uc21c\ud654\ub41c \ud604\uc7ac\uac00\uce58 \uacc4\uc0b0\\n\\n\ucc44\uad8c \uac00\uaca9\uc740 \ubbf8\ub798\uc5d0 \ubc1b\uc744 \ud604\uae08\ud750\ub984\uc744 \ud604\uc7ac \uac00\uce58\ub85c \ud560\uc778\ud55c \ud569\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\uc561\uba74 10,000\uc6d0, \ud45c\uba74\uae08\ub9ac 3%, \ub9cc\uae30 3\ub144, \ub9e4\ub144 \uc774\uc790 \uc9c0\uae09 \ucc44\uad8c\uc73c\ub85c \uacc4\uc0b0\ud574 \ubd05\ub2c8\ub2e4.<br/>\\n\ub9e4\ub144 \ubc1b\ub294 \uae08\uc561\uc740 `300\uc6d0`, `300\uc6d0`, `10,300\uc6d0`\uc785\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uae08\ub9ac\uac00 3%\uc77c \ub54c \uac00\uaca9\uc740 `10,000\uc6d0`\uc73c\ub85c \uc561\uba74\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uae08\ub9ac\uac00 4%\ub85c \uc624\ub974\uba74 \uac00\uaca9\uc740 \uc57d `9,723\uc6d0`\uc73c\ub85c \ub5a8\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uae08\ub9ac\uac00 2%\ub85c \ub0b4\ub9ac\uba74 \uac00\uaca9\uc740 \uc57d `10,288\uc6d0`\uc73c\ub85c \uc624\ub985\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ucc44\uad8c\uc778\ub370 \uc2dc\uc7a5\uae08\ub9ac\uc5d0 \ub530\ub77c \uac00\uaca9\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc744 \uc218\uce58\ub85c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub4c0\ub808\uc774\uc158 \u2014 \uac00\uaca9\uc774 \uc5bc\ub9c8\ub098 \ubbfc\uac10\ud55c\uac00\\n\\n\uae08\ub9ac\uac00 1%\ud3ec\uc778\ud2b8 \uc6c0\uc9c1\uc77c \ub54c \ucc44\uad8c \uac00\uaca9\uc774 \uba87 % \uc6c0\uc9c1\uc774\ub294\uc9c0\ub97c \ub098\ud0c0\ub0b4\ub294 \uc9c0\ud45c\uac00 \ub4c0\ub808\uc774\uc158\uc785\ub2c8\ub2e4.<br/>\\n\ub9cc\uae30\uac00 \uae38\uace0 \ud45c\uba74\uae08\ub9ac\uac00 \ub0ae\uc744\uc218\ub85d \ub4c0\ub808\uc774\uc158\uc774 \ucee4\uc11c \uac00\uaca9 \ubcc0\ub3d9\uc774 \ud07d\ub2c8\ub2e4.<br/>\\n\uc7a5\uae30\ucc44\uac00 \ub2e8\uae30\ucc44\ubcf4\ub2e4 \uae08\ub9ac \ubcc0\ud654\uc5d0 \ubbfc\uac10\ud55c \uc774\uc720\uac00 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uc0c1\uc2b9\uc774 \uc608\uc0c1\ub418\ub294 \uad6d\uba74\uc5d0\uc11c\ub294 \ub4c0\ub808\uc774\uc158\uc774 \uc9e7\uc740 \ucc44\uad8c\uc774 \uac00\uaca9 \ud558\ub77d \ud3ed\uc774 \uc791\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\n\uae30\uc900\uae08\ub9ac \uacb0\uc815\ubb38\uc744 \uc77d\uc744 \ub54c\ub294 \ub3d9\uacb0\xb7\uc778\uc0c1\xb7\uc778\ud558 \uc5ec\ubd80\ubcf4\ub2e4 \ud5a5\ud6c4 \ubc29\ud5a5\uc5d0 \ub300\ud55c \ubb38\uad6c\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\uc624\ub298\ucc98\ub7fc \ub3d9\uacb0\uc774\uba74\uc11c\ub3c4 \ubb3c\uac00 \uc555\ubc15\uacfc \ucd94\uac00 \uc778\uc0c1 \uac00\ub2a5\uc131\uc774 \uac70\ub860\ub418\ub294 \uacbd\uc6b0, \uc2dc\uc7a5\uae08\ub9ac\ub294 \ub3d9\uacb0\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \uc624\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucc44\uad8c \uae08\ub9ac\ub294 \uad6d\uace0\ucc44 \uc218\uc775\ub960 \uace1\uc120\uc73c\ub85c \ud655\uc778\ud558\uace0, \uae30\uc900\uae08\ub9ac\uc640\uc758 \ucc28\uc774\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\ubcf4\uc720 \uc911\uc778 \ucc44\uad8c\uc758 \ub4c0\ub808\uc774\uc158\uc744 \uc54c\uba74, \uae08\ub9ac \ubcc0\ud654 \uc2dc \ud3c9\uac00\uae08\uc561\uc774 \uc5b4\ub290 \uc815\ub3c4 \uc6c0\uc9c1\uc77c\uc9c0 \uac00\ub2a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc608\uae08\uacfc \ub2ec\ub9ac \ucc44\uad8c\uc740 \uc911\ub3c4 \ub9e4\ub3c4 \uc2dc \uac00\uaca9 \ubcc0\ub3d9\uc774 \ubc1c\uc0dd\ud55c\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \uae30\uc5b5\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uc5ed\uad00\uacc4\ub294 \ud55c \ubc88 \uc774\ud574\ud558\uba74 \ud3c9\uc0dd \uc4f0\ub294 \uae30\ubcf8\uae30\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \ub274\uc2a4\ub97c \ubcfc \ub54c\ub9c8\ub2e4 \\"\uadf8\ub798\uc11c \ucc44\uad8c \uac00\uaca9\uc740 \uc5b4\ub290 \ubc29\ud5a5\uc778\uac00\\"\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExNHc0MjBibDZvZDY0dzFib2g0YzNmbzFkZTVwb3N3MDV1c2loZm04MiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/67ThRZlYBvibtdF9JH/giphy.gif\\" alt=\\"Finance\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"kospi-plunge-oct22","metadata":{"permalink":"/blog/finance/kospi-plunge-oct22","source":"@site/finance/2026-10-22-kospi-plunge-oct22/index.mdx","title":"\ucf54\uc2a4\ud53c 3.52% \uae09\ub77d \u2014 \ud558\ub8e8 \ub9cc\uc5d0 \ub4a4\uc9d1\ud78c \uc2dc\uc7a5, \ud558\ub77d\uc7a5\uc5d0\uc11c \ud655\uc778\ud560 \uac83\ub4e4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-22T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"market","permalink":"/blog/finance/tags/market"},{"inline":true,"label":"kospi","permalink":"/blog/finance/tags/kospi"}],"readingTime":3.71,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kospi-plunge-oct22","title":"\ucf54\uc2a4\ud53c 3.52% \uae09\ub77d \u2014 \ud558\ub8e8 \ub9cc\uc5d0 \ub4a4\uc9d1\ud78c \uc2dc\uc7a5, \ud558\ub77d\uc7a5\uc5d0\uc11c \ud655\uc778\ud560 \uac83\ub4e4","authors":["way"],"tags":["finance","market","kospi"]},"unlisted":false,"prevItem":{"title":"\ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uad00\uacc4 \u2014 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \ucc44\uad8c\uac12\uc774 \ub5a8\uc5b4\uc9c0\ub294 \uc774\uc720","permalink":"/blog/finance/bond-price-yield"},"nextItem":{"title":"\uc5f0\uae08\uc800\ucd95\uacfc IRP \uc138\uc561\uacf5\uc81c \u2014 2026\ub144 \uae30\uc900 \ud55c\ub3c4\uc640 \uacc4\uc0b0\ubc95","permalink":"/blog/finance/pension-tax-credit-2026"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \uc5b4\uc81c\uc758 \uc0c1\uc2b9\ubd84\uc744 \ud558\ub8e8 \ub9cc\uc5d0 \ubc18\ub0a9\ud55c \uad6d\ub0b4 \uc99d\uc2dc\uc758 \uae09\ub77d\uacfc, \uc9c0\uc218\uac00 \ud06c\uac8c \ub5a8\uc5b4\uc9c4 \ub0a0\uc5d0 \ud655\uc778\ud574\uc57c \ud560 \uc9c0\ud45c\ub4e4\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc624\ub298\uc758 \uc2dc\uc7a5\\n\\n2026\ub144 10\uc6d4 22\uc77c, \ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 201.89\ud3ec\uc778\ud2b8, 3.52% \ud558\ub77d\ud55c 5,533.77\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5b4\uc81c 5,700\uc120\uc744 \ub118\uc5c8\ub358 \uc0c1\uc2b9\ubd84\uc744 \ud558\ub8e8 \ub9cc\uc5d0 \uace0\uc2a4\ub780\ud788 \ubc18\ub0a9\ud55c \uc148\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\ub294 5,670.11\uc5d0 \ucd9c\ubc1c\ud574 \uc7a5\uc911 5,740.28\uae4c\uc9c0 \ubc18\ub4f1\uc744 \uc2dc\ub3c4\ud588\uc9c0\ub9cc, \uc774\ud6c4 \ub099\ud3ed\uc744 \ud0a4\uc6cc \uc7a5\uc911 \ud55c\ub54c 5,485.98\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 \uc804\uc77c \ub300\ube44 28.66\ud3ec\uc778\ud2b8, 3.62% \ud558\ub77d\ud55c 764.10\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615\uc8fc \uc911\uc2ec\uc758 \ucf54\uc2a4\ud53c200 \uc9c0\uc218\ub294 3.71% \ud558\ub77d\ud55c 858.02\ub85c, \ucf54\uc2a4\ud53c\ubcf4\ub2e4 \ub099\ud3ed\uc774 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 1,324.6\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.11% \ud558\ub77d\ud574 \uc6d0\ud654\uac00 \uc18c\ud3ed \uac15\uc138\ub97c \uc774\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uc2dc\uc7a5\uc740 \ub098\uc2a4\ub2e5 \uc885\ud569\uc9c0\uc218\uac00 1.05%, S&P500\uc774 0.58% \uc624\ub974\ub294 \ub4f1 \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc989, \uc624\ub298 \uad6d\ub0b4 \uc99d\uc2dc\uc758 \uae09\ub77d\uc740 \ud574\uc678 \uc2dc\uc7a5\uc758 \ud750\ub984\uacfc \ubc18\ub300\ub85c \uc6c0\uc9c1\uc778, \uad6d\ub0b4 \uc694\uc778\uc774 \uac15\ud558\uac8c \uc791\uc6a9\ud55c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExanZuZzl0cmFhanF3Z290c3F3YjdrYjJsa2hvODVmejAzMm45aHZiaiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/JtBZm3Getg3dqxK0zP/giphy.gif\\" alt=\\"Falling chart\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uae09\ub77d\uc758 \ubc30\uacbd\\n\\n\uc624\ub298\uc758 \ud558\ub77d\uc740 \ud558\ub098\uc758 \uc6d0\uc778\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ec\ub7ec \uc545\uc7ac\uac00 \uacb9\uce58\uba70 \ud22c\uc790\uc2ec\ub9ac\uac00 \ud55c \ubc88\uc5d0 \uc5bc\uc5b4\ubd99\uc740 \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### AI \ud22c\uc790 \uc218\uc775\uc131 \uc6b0\ub824\uc640 \ubc18\ub3c4\uccb4 \ucc28\uc775 \uc2e4\ud604\\n\\n\ud558\ub77d\uc744 \uc8fc\ub3c4\ud55c \uac83\uc740 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0bc\uc131\uc804\uc790\uc640 SK\ud558\uc774\ub2c9\uc2a4\ub294 \uac01\uac01 4.03%, 5.49% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n([\uc544\uc8fc\uacbd\uc81c \ubcf4\ub3c4](https://www.ajunews.com/view/20261022154721705)\ub97c \uae30\uc900\uc73c\ub85c \ud569\ub2c8\ub2e4.)<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uc2dc\uc7a5\uc5d0\uc11c \uba54\ud0c0\uac00 3\ubd84\uae30 \ud638\uc2e4\uc801\uc744 \ubc1c\ud45c\ud588\uc74c\uc5d0\ub3c4, \ub0b4\ub144 \uc124\ube44\ud22c\uc790 \uac00\uc774\ub358\uc2a4\ub97c \uc81c\uc2dc\ud558\uc9c0 \uc54a\uc558\uace0 3\ubd84\uae30 \uc789\uc5ec\ud604\uae08\ud750\ub984\uc774 21\uc5b52\ucc9c\ub9cc \ub2ec\ub7ec \uc801\uc790\ub85c \uc804\ud658\ud55c \uc810\uc774 \ubd80\ub2f4\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nAI \uc0ac\uc5c5\uc758 \uc131\uc7a5\uc138\uc640 \ubcc4\uac1c\ub85c, \ub300\uaddc\ubaa8 \ud22c\uc790 \ube44\uc6a9\uc744 \uac10\ub2f9\ud560 \ud604\uae08\ud750\ub984\uacfc \uc218\uc775\uc131\uc744 \ud655\ubcf4\ud560 \uc218 \uc788\uc744\uc9c0\uc5d0 \ub300\ud55c \uc758\ubb38\uc774 \ud574\uc18c\ub418\uc9c0 \uc54a\uc740 \uac83\uc785\ub2c8\ub2e4.<br/>\\n\uc5ec\uae30\uc5d0 \uc804\ub0a0 \uae09\ub4f1\uc5d0 \ub530\ub978 \ucc28\uc775 \uc2e4\ud604 \ub9e4\ubb3c\uc774 \uacb9\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc790\uc0ac\uc8fc \ub9e4\uc785 \uc885\ub8cc\uc5d0 \ub530\ub978 \uc218\uae09 \uacf5\ubc31\\n\\n\uc0bc\uc131\uc804\uc790\uc640 SK\ud558\uc774\ub2c9\uc2a4\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785\uc774 \uc787\ub2ec\uc544 \uc885\ub8cc\ub418\uba70 \ub9e4\uc218 \uae30\ubc18\uc774 \uc57d\ud654\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0bc\uc131\uc804\uc790\ub294 15\uc870\uc6d0 \uaddc\ubaa8\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785\uc744 \uc9c0\ub09c 6\uc77c \ub9c8\ucce4\uace0, SK\ud558\uc774\ub2c9\uc2a4\ub294 40\uc870\uc6d0 \uaddc\ubaa8\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785\uc744 \uc9c0\ub09c 21\uc77c \uc644\ub8cc\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\uc2e0\uc99d\uad8c \uc774\uacbd\ubbfc \uc5f0\uad6c\uc6d0\uc740 SK\ud558\uc774\ub2c9\uc2a4\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785 \uc885\ub8cc\ub85c \\"\uc218\uae09 \uc644\ucda9\ub825\uc774 \ucd94\uac00\ub85c \uc57d\ud654\ub410\ub2e4\\"\uace0 \uc9c4\ub2e8\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nSK\ud558\uc774\ub2c9\uc2a4\uc758 \ubbf8\uad6d \uc790\ud68c\uc0ac \uc194\ub9ac\ub2e4\uc784 \uc0c1\uc7a5 \ucd94\uc9c4\uc744 \ub458\ub7ec\uc2fc \uc911\ubcf5\uc0c1\uc7a5 \ub17c\ub780\ub3c4 \ud22c\uc790\uc2ec\ub9ac\uc5d0 \ubd80\ub2f4\uc744 \ub354\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc9c0\uc815\ud559\uc801 \uae34\uc7a5\uacfc \ud1b5\ud654\uc815\ucc45 \uacbd\uacc4\uac10\\n\\n\uc911\ub3d9\uc758 \uc9c0\uc815\ud559\uc801 \uae34\uc7a5\ub3c4 \ud22c\uc790\uc2ec\ub9ac\ub97c \uc555\ubc15\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d\uc774 \uc0ac\uc6b0\ub514\uc544\ub77c\ube44\uc544 \uc8fc\uc7ac \ube44\ud544\uc218 \uc678\uad50 \uc778\ub825\uc5d0 \ucd9c\uad6d\uc744 \uba85\ub839\ud558\uba74\uc11c \uad6d\uc9c0\uc801 \uad70\uc0ac \ucda9\ub3cc\uc5d0 \ub300\ud55c \uacbd\uacc4\uac10\uc774 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\uc740\ud589 \uae08\uc735\ud1b5\ud654\uc704\uc6d0\ud68c\ub294 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 3.00%\ub85c \ub3d9\uacb0\ud588\uc9c0\ub9cc, \ubb3c\uac00 \ubd80\ub2f4\uacfc \ud1b5\ud654\uc815\ucc45\uc744 \ub458\ub7ec\uc2fc \uacbd\uacc4\uac10 \uc18d\uc5d0 \uc99d\uc2dc \ubc18\ub4f1\uc744 \uc774\ub04c \ub9cc\ud55c \uc7ac\ub8cc\uac00 \ub418\uc9c0\ub294 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc9c0\uc218\uac00 \ud06c\uac8c \ub5a8\uc5b4\uc9c4 \ub0a0 \ud655\uc778\ud560 \uac83\ub4e4\\n\\n\uc5b4\uc81c \uc0c1\uc2b9\uc7a5\uc5d0\uc11c \ud655\uc778\ud55c \uc9c0\ud45c\ub4e4\uc740 \ud558\ub77d\uc7a5\uc5d0\uc11c\ub3c4 \ub611\uac19\uc774 \uc720\ud6a8\ud569\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ud574\uc11d\uc758 \ubc29\ud5a5\uc774 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\\n#### \uc218\uae09 \u2014 \ub204\uac00 \ud314\uc558\ub294\uac00\\n\\n\uc624\ub298 \uc720\uac00\uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uac1c\uc778\uc774 5,748\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uace0, \uc678\uad6d\uc778\uc740 619\uc5b5\uc6d0, \uae30\uad00\uc740 5,556\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n(\ub124\uc774\ubc84 \uc99d\uad8c \ud22c\uc790\uc790\ubcc4 \ub9e4\ub9e4\ub3d9\ud5a5 \uc9d1\uacc4, 2026\ub144 10\uc6d4 22\uc77c \uae30\uc900\uc785\ub2c8\ub2e4.)<br/>\\n\uae30\uad00 \uc911\uc5d0\uc11c\ub294 \uae08\uc735\ud22c\uc790(-3,771\uc5b5\uc6d0)\uc640 \ud22c\uc2e0(-3,073\uc5b5\uc6d0)\uc758 \ub9e4\ub3c4\uac00 \ucef8\uace0, \uc5f0\uae30\uae08\uc740 1,161\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5b4\uc81c\uc640 \ubc18\ub300\ub85c \uc624\ub298\uc740 \uae30\uad00\uc758 \ub9e4\ub3c4\uac00 \uc9c0\uc218\ub97c \ub04c\uc5b4\ub0b4\ub838\uace0, \uac1c\uc778\uc774 \ub9e4\ubb3c\uc744 \ubc1b\uc544\ub0b8 \uad6c\ub3c4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub099\ud3ed\uc758 \ubd84\ud3ec \u2014 \uc77c\ubd80 \uc885\ubaa9\uc778\uac00, \uc2dc\uc7a5 \uc804\uccb4\uc778\uac00\\n\\n\uc624\ub298 \uc720\uac00\uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc0c1\uc2b9 \uc885\ubaa9\uc774 174\uac1c\uc5d0 \uadf8\uce5c \ubc18\uba74 \ud558\ub77d \uc885\ubaa9\uc740 709\uac1c\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n([\uc11c\uc6b8\uc2e0\ubb38 \ubcf4\ub3c4](https://www.seoul.co.kr/news/economy/securities/2026/10/22/20261022500246)\ub97c \uae30\uc900\uc73c\ub85c \ud569\ub2c8\ub2e4.)<br/>\\n\uc2dc\uac00\ucd1d\uc561 \uc0c1\uc704 \uc885\ubaa9 \ub300\ubd80\ubd84\uc774 \uc57d\uc138\uc600\uace0, LG\uc5d0\ub108\uc9c0\uc194\ub8e8\uc158(-5.22%), \uc0bc\uc131\ubc14\uc774\uc624\ub85c\uc9c1\uc2a4(-3.95%), \ud604\ub300\ucc28(-2.58%) \ub4f1 \uc5c5\uc885\uc744 \uac00\ub9ac\uc9c0 \uc54a\uace0 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud2b9\uc815 \uc5c5\uc885\uc758 \ubb38\uc81c\uac00 \uc544\ub2c8\ub77c \uc2dc\uc7a5 \uc804\ubc18\uc758 \ud22c\uc790\uc2ec\ub9ac\uac00 \uc704\ucd95\ub41c \ub0a0\uc774\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uac70\ub798\ub300\uae08\\n\\n\uc624\ub298 \ucf54\uc2a4\ud53c \uac70\ub798\ub300\uae08\uc740 13\uc8707002\uc5b5\uc6d0 \uc218\uc900\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uac00 \ud06c\uac8c \ub5a8\uc5b4\uc9c0\uba74\uc11c \uac70\ub798\ub300\uae08\ub3c4 \ud568\uaed8 \ub298\uc5c8\ub2e4\uba74, \ub9e4\ub3c4 \ubb3c\ub7c9\uc774 \uc2e4\uc81c\ub85c \uc3df\uc544\uc838 \ub098\uc654\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\uc744 \uc2dc\ub3c4\ud558\ub294 \uad6c\uac04\uc5d0\uc11c \uac70\ub798\ub300\uae08\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0\ub3c4 \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ud658\uc728\\n\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 1,324.6\uc6d0\uc73c\ub85c 5\uac70\ub798\uc77c \uc5f0\uc18d \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ud558\ub77d\uacfc \ud658\uc728 \ud558\ub77d(\uc6d0\ud654 \uac15\uc138)\uc774 \ub3d9\uc2dc\uc5d0 \ub098\ud0c0\ub09c \uac83\uc740, \uc624\ub298\uc758 \ud558\ub77d\uc774 \uc678\uad6d\uc778 \uc790\uae08 \uc774\ud0c8\ubcf4\ub2e4\ub294 \uad6d\ub0b4 \uc218\uae09\uacfc \uc2ec\ub9ac\uc5d0 \uae30\uc778\ud588\ub2e4\ub294 \ud574\uc11d\uc5d0 \ud798\uc744 \uc2e3\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\n\uc9c0\uc218\uac00 \ud06c\uac8c \ub5a8\uc5b4\uc9c4 \ub0a0\uc77c\uc218\ub85d \ub9c8\uac10 \uc218\uce58 \ud558\ub098\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \uc6d0\uc778\uc744 \ubd84\ud574\ud574 \ubcf4\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc624\ub298\ucc98\ub7fc \ud574\uc678 \uc2dc\uc7a5\uacfc \uad6d\ub0b4 \uc2dc\uc7a5\uc774 \ubc18\ub300\ub85c \uc6c0\uc9c1\uc778 \ub0a0\uc740, \uad6d\ub0b4 \uace0\uc720\uc758 \uc694\uc778\uc774 \ubb34\uc5c7\uc778\uc9c0 \ub274\uc2a4\uc640 \uc218\uae09\uc744 \ub300\uc870\ud574 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc218\uae09 \ud654\uba74\uc5d0\uc11c\ub294 \uae30\uad00 \uc138\ubd80 \uc8fc\uccb4(\uae08\uc735\ud22c\uc790\xb7\ud22c\uc2e0\xb7\uc5f0\uae30\uae08 \ub4f1)\ubcc4\ub85c \ub9e4\ub9e4 \ubc29\ud5a5\uc774 \uc5c7\uac08\ub9ac\ub294\uc9c0\ub3c4 \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\uae09\ub77d\uc758 \uc6d0\uc778\uc774 \ub2e8\ubc1c\uc131 \uc218\uae09 \uacf5\ubc31\uc778\uc9c0, \uc2e4\uc801\xb7\uc815\ucc45 \ub4f1 \ud380\ub354\uba58\ud138 \uc694\uc778\uc778\uc9c0\ub97c \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uc774\ud6c4\uc758 \ud750\ub984\uc744 \ud310\ub2e8\ud558\ub294 \uae30\uc900\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc5b4\uc81c\uc758 \uc0c1\uc2b9\uacfc \uc624\ub298\uc758 \ud558\ub77d\uc740 \uac19\uc740 \uc2dc\uc7a5\uc758 \ub2e4\ub978 \uc5bc\uad74\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ub4f1\ub77d \uc790\uccb4\ubcf4\ub2e4 \uc218\uae09, \ub099\ud3ed\uc758 \ubd84\ud3ec, \uac70\ub798\ub300\uae08, \ud658\uc728\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\ub294 \uc2b5\uad00\uc774 \ubcc0\ub3d9\uc131 \uc7a5\uc138\uc5d0\uc11c \uc2dc\uc7a5\uc758 \ud750\ub984\uc744 \uc77d\ub294 \uae30\ubcf8\uae30\uac00 \ub429\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExanZuZzl0cmFhanF3Z290c3F3YjdrYjJsa2hvODVmejAzMm45aHZiaiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/MEq4za8poCEOfdY5Pr/giphy.gif\\" alt=\\"Market data\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"pension-tax-credit-2026","metadata":{"permalink":"/blog/finance/pension-tax-credit-2026","source":"@site/finance/2026-10-22-pension-tax-credit-2026/index.mdx","title":"\uc5f0\uae08\uc800\ucd95\uacfc IRP \uc138\uc561\uacf5\uc81c \u2014 2026\ub144 \uae30\uc900 \ud55c\ub3c4\uc640 \uacc4\uc0b0\ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-22T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"pension","permalink":"/blog/finance/tags/pension"},{"inline":true,"label":"tax","permalink":"/blog/finance/tags/tax"}],"readingTime":2.73,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"pension-tax-credit-2026","title":"\uc5f0\uae08\uc800\ucd95\uacfc IRP \uc138\uc561\uacf5\uc81c \u2014 2026\ub144 \uae30\uc900 \ud55c\ub3c4\uc640 \uacc4\uc0b0\ubc95","authors":["way"],"tags":["finance","pension","tax"]},"unlisted":false,"prevItem":{"title":"\ucf54\uc2a4\ud53c 3.52% \uae09\ub77d \u2014 \ud558\ub8e8 \ub9cc\uc5d0 \ub4a4\uc9d1\ud78c \uc2dc\uc7a5, \ud558\ub77d\uc7a5\uc5d0\uc11c \ud655\uc778\ud560 \uac83\ub4e4","permalink":"/blog/finance/kospi-plunge-oct22"},"nextItem":{"title":"\ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc758 \uad6c\uc870 \u2014 \uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4, \uc2e4\uc801 \uc2dc\uc98c\uc5d0 \ud655\uc778\ud558\ub294 \uac83\ub4e4","permalink":"/blog/finance/semiconductor-industry-structure"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \uc5f0\ub9d0\uc774 \ub2e4\uac00\uc624\ub294 \uc2dc\uc810\uc5d0 \ub9de\ucdb0, \uc5f0\uae08\uc800\ucd95\uacfc IRP\uc758 \uc138\uc561\uacf5\uc81c \uad6c\uc870\ub97c 2026\ub144 \uae30\uc900\uc73c\ub85c \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\uc808\uc138\ub97c \uad8c\uc720\ud558\ub294 \uae00\uc774 \uc544\ub2c8\ub77c, \uc81c\ub3c4\ub97c \uc774\ud574\ud558\uae30 \uc704\ud55c \uad50\uc721 \ubaa9\uc801\uc758 \ud574\uc124\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uc65c \uc5f0\ub9d0\uc5d0 \uc5f0\uae08 \uc774\uc57c\uae30\uac00 \ub098\uc624\ub294\uac00\\n\\n\uc5f0\uae08\uc800\ucd95\uacfc IRP(\uac1c\uc778\ud615 \ud1f4\uc9c1\uc5f0\uae08)\uc5d0 \ub123\uc740 \ub3c8\uc740 \uc77c\uc815 \ud55c\ub3c4 \uc548\uc5d0\uc11c \uc138\uc561\uacf5\uc81c\ub97c \ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc138\uc561\uacf5\uc81c\ub294 1\uc6d4\ubd80\ud130 12\uc6d4\uae4c\uc9c0 \ub0a9\uc785\ud55c \uae08\uc561\uc744 \uae30\uc900\uc73c\ub85c \uacc4\uc0b0\ub418\ubbc0\ub85c, \uc5f0\ub9d0\uc774 \ub418\uba74 \uc62c\ud574 \ub0a9\uc785\uc561\uc744 \uc810\uac80\ud558\ub294 \uc2dc\uae30\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\ud55c\ub3c4\uc640 \uacf5\uc81c\uc728\uc744 \uc815\ud655\ud788 \uc54c\uc544\uc57c \\"\uc5bc\ub9c8\ub97c \ub354 \ub123\uc5b4\uc57c \ud558\ub294\uc9c0\\"\uac00 \uc544\ub2c8\ub77c \\"\uc5bc\ub9c8\uae4c\uc9c0\uac00 \uc758\ubbf8 \uc788\ub294\uc9c0\\"\ub97c \ud310\ub2e8\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExM3Y4N3MweGZ4djhmZmRkbTg5cjhyNWI3Y3d2bWJnNWp2bnU4d3lsbiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/3oriO2rfuppV6GkC5O/giphy.gif\\" alt=\\"Savings\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc138\uc561\uacf5\uc81c\uc758 \uae30\ubcf8 \uad6c\uc870\\n\\n#### \ud55c\ub3c4 \u2014 600\ub9cc\uc6d0\uacfc 900\ub9cc\uc6d0\\n\\n\uc5f0\uae08\uc800\ucd95\uc758 \uc138\uc561\uacf5\uc81c \ub300\uc0c1 \ub0a9\uc785\ud55c\ub3c4\ub294 \uc5f0 600\ub9cc\uc6d0\uc785\ub2c8\ub2e4.<br/>\\n\uc5ec\uae30\uc5d0 IRP \ub4f1 \ud1f4\uc9c1\uc5f0\uae08\uacc4\uc88c\uc758 \ubcf8\uc778 \ucd94\uac00 \ub0a9\uc785\uc561\uc744 \ud569\uce58\uba74 \uc5f0 900\ub9cc\uc6d0\uae4c\uc9c0 \uc138\uc561\uacf5\uc81c \ub300\uc0c1\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc989, \uc5f0\uae08\uc800\ucd95\uc5d0 600\ub9cc\uc6d0, IRP\uc5d0 300\ub9cc\uc6d0\uc744 \ub123\uc73c\uba74 \ud569\uc0b0 900\ub9cc\uc6d0 \uc804\uc561\uc774 \uacf5\uc81c \ub300\uc0c1\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc5f0\uae08\uc800\ucd95\uc5d0\ub9cc 900\ub9cc\uc6d0\uc744 \ub123\uc73c\uba74 600\ub9cc\uc6d0\uae4c\uc9c0\ub9cc \uacf5\uc81c \ub300\uc0c1\uc774 \ub418\ubbc0\ub85c, \uad6c\uc870\ub97c \uc54c\uace0 \ub098\ub204\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ucc38\uace0\ub85c \uc5f0\uae08\uacc4\uc88c\uc5d0 \ub123\uc744 \uc218 \uc788\ub294 \uae08\uc561 \uc790\uccb4\uc758 \ud55c\ub3c4(\ub0a9\uc785\ud55c\ub3c4)\ub294 \uc5f0 1,800\ub9cc\uc6d0\uc73c\ub85c \ubcc4\ub3c4\uc774\uba70, \uc804\uc561\uc774 \uacf5\uc81c\ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n#### \uacf5\uc81c\uc728 \u2014 16.5%\uc640 13.2%\\n\\n\uc138\uc561\uacf5\uc81c\uc728\uc740 \uc18c\ub4dd \uad6c\uac04\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uadfc\ub85c\uc18c\ub4dd\ub9cc \uc788\ub294 \uacbd\uc6b0 \ucd1d\uae09\uc5ec 5,500\ub9cc\uc6d0 \uc774\ud558\uc774\uba74 16.5%, \ucd08\uacfc\uc774\uba74 13.2%\uc785\ub2c8\ub2e4.<br/>\\n(\uc885\ud569\uc18c\ub4dd\uae08\uc561 \uae30\uc900\uc73c\ub85c\ub294 4,500\ub9cc\uc6d0\uc774 \uae30\uc900\uc120\uc774\uba70, \uc9c0\ubc29\uc18c\ub4dd\uc138\ub97c \ud3ec\ud568\ud55c \uc218\uce58\uc785\ub2c8\ub2e4.)<br/>\\n\uacc4\uc0b0\uc0c1 \ucd5c\ub300 \uc808\uc138\uc561\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \uacf5\uc81c \ub300\uc0c1 \ub0a9\uc785\uc561 | \ucd1d\uae09\uc5ec 5,500\ub9cc\uc6d0 \uc774\ud558 (16.5%) | \ucd1d\uae09\uc5ec 5,500\ub9cc\uc6d0 \ucd08\uacfc (13.2%) |\\n|---|---|---|\\n| 600\ub9cc\uc6d0 | 99\ub9cc\uc6d0 | 79\ub9cc2\ucc9c\uc6d0 |\\n| 900\ub9cc\uc6d0 | 148\ub9cc5\ucc9c\uc6d0 | 118\ub9cc8\ucc9c\uc6d0 |\\n\\n### \uacc4\uc0b0 \uc804\uc5d0 \ud655\uc778\ud560 \uac83\ub4e4\\n\\n#### \uacb0\uc815\uc138\uc561\uc758 \ud55c\ub3c4\\n\\n\uc704 \ud45c\uc758 \uae08\uc561\uc740 \\"\uacc4\uc0b0\uc0c1 \ucd5c\ub300\\"\uc785\ub2c8\ub2e4.<br/>\\n\uc138\uc561\uacf5\uc81c\ub294 \ub0bc \uc138\uae08(\uacb0\uc815\uc138\uc561)\uc774 \uc788\uc5b4\uc57c \uc758\ubbf8\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uacb0\uc815\uc138\uc561\uc774 \uc801\uc73c\uba74 \ud55c\ub3c4\ub9cc\ud07c \ub123\uc5b4\ub3c4 \uacc4\uc0b0\ub41c \uae08\uc561\uc744 \uc804\ubd80 \ub3cc\ub824\ubc1b\uc9c0 \ubabb\ud569\ub2c8\ub2e4.<br/>\\n\uad6d\uc138\uccad \uc5f0\ub9d0\uc815\uc0b0 \ubbf8\ub9ac\ubcf4\uae30\ub85c \uc608\uc0c1 \uc138\uc561\uc744 \uba3c\uc800 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc21c\uc11c\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc911\ub3c4\ud574\uc9c0\uc758 \uc138\uae08\\n\\n\uc138\uc561\uacf5\uc81c\ub97c \ubc1b\uc740 \ub3c8\uc744 \uc5f0\uae08\uc774 \uc544\ub2cc \ubc29\uc2dd\uc73c\ub85c \uc911\ub3c4\uc5d0 \ucc3e\uc73c\uba74, \uacf5\uc81c\ubc1b\uc740 \uc6d0\uae08\uacfc \uc218\uc775\uc5d0 16.5%\uc758 \uae30\ud0c0\uc18c\ub4dd\uc138\uac00 \ubd80\uacfc\ub429\ub2c8\ub2e4.<br/>\\n\uacf5\uc81c\uc728\uc774 13.2%\uc778 \uad6c\uac04\uc5d0 \ud574\ub2f9\ud558\ub294 \ubd84\uc740 \uc624\ud788\ub824 \uc190\ud574\uac00 \ub420 \uc218 \uc788\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n3\ub144 \uc548\uc5d0 \uc4f8 \uac00\ub2a5\uc131\uc774 \uc788\ub294 \ub3c8\uc740 \uc5f0\uae08\uc800\ucd95\ubcf4\ub2e4 \uc608\uae08\uc774\ub098 \ud30c\ud0b9\ud1b5\uc7a5 \ub4f1 \ubcc4\ub3c4 \uc790\uae08\uc73c\ub85c \ubd84\ub9ac\ud558\ub294 \ud3b8\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc218\ub839 \ub2e8\uacc4\uc758 \uae30\uc900\\n\\n\uc5f0\uae08\uc73c\ub85c \ubc1b\uc744 \ub54c\ub294 \uc5f0\uae08\uc18c\ub4dd\uc138\uac00 \uc801\uc6a9\ub418\uba70, \uc5f0\uac04 \uc0ac\uc801\uc5f0\uae08 \uc218\ub839\uc561 1,500\ub9cc\uc6d0\uc774\ub77c\ub294 \uae30\uc900\ub3c4 \ud568\uaed8 \uad00\ub9ac\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ub0a9\uc785 \ub2e8\uacc4\uc758 \uc808\uc138\ub9cc \ubcf4\uace0 \uc218\ub839 \ub2e8\uacc4\uc758 \uc138\uae08\uc744 \ub193\uce58\uba74 \uc804\uccb4 \uadf8\ub9bc\uc774 \uc5b4\uae0b\ub0a9\ub2c8\ub2e4.<br/>\\n\ub9cc\uae30\uac00 \ub41c ISA \uc794\uc561\uc744 \uc5f0\uae08\uacc4\uc88c\ub85c \uc62e\uae30\uba74 \uc62e\uae34 \uae08\uc561\uc758 10%, \ucd5c\ub300 300\ub9cc\uc6d0\uae4c\uc9c0 \uacf5\uc81c \ud55c\ub3c4\uac00 \ucd94\uac00\ub85c \ub298\uc5b4\ub098\ub294 \ud2b9\ub840\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\n\uc5f0\ub9d0\uc815\uc0b0 \uc2dc\uc98c\uc774 \uc624\uae30 \uc804\uc5d0 \uc62c\ud574 \uc5f0\uae08\uc800\ucd95\uacfc IRP\uc5d0 \uc2e4\uc81c\ub85c \ub0a9\uc785\ud55c \uae08\uc561\uc744 \ud569\uc0b0\ud574 \ubd05\ub2c8\ub2e4.<br/>\\n600\ub9cc\uc6d0\uacfc 900\ub9cc\uc6d0\uc774\ub77c\ub294 \ub450 \uac1c\uc758 \ud55c\ub3c4\uc120\uc5d0\uc11c \ud604\uc7ac \uc704\uce58\ub97c \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ubcf8\uc778\uc758 \ucd1d\uae09\uc5ec \uad6c\uac04\uc5d0 \ub9de\ub294 \uacf5\uc81c\uc728\ub85c \uacc4\uc0b0\uc0c1 \uc808\uc138\uc561\uc744 \uad6c\ud574 \ubd05\ub2c8\ub2e4.<br/>\\n\uacb0\uc815\uc138\uc561\uc774 \ucda9\ubd84\ud55c\uc9c0, \uc911\ub3c4\uc5d0 \ucc3e\uc744 \uac00\ub2a5\uc131\uc740 \uc5c6\ub294\uc9c0\ub97c \ud568\uaed8 \uc810\uac80\ud569\ub2c8\ub2e4.<br/>\\n\uc138\uc81c \ud61c\ud0dd\uc740 \ub9e4\ub144 \uc870\uae08\uc529 \ubc14\ub014 \uc218 \uc788\uc73c\ubbc0\ub85c, \ucd5c\uc885 \ud310\ub2e8 \uc804\uc5d0\ub294 \uad6d\uc138\uccad \uc548\ub0b4\ub098 \uae08\uc735\ud68c\uc0ac \uacf5\uc9c0\ub97c \uc6d0\ubb38\uc73c\ub85c \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc5f0\uae08 \uc138\uc561\uacf5\uc81c\ub294 \\"\ub9ce\uc774 \ub123\uc744\uc218\ub85d \uc88b\uc740 \uc81c\ub3c4\\"\uac00 \uc544\ub2c8\ub77c \\"\ud55c\ub3c4\uc640 \uc870\uac74\uc744 \uc54c\uace0 \uc4f0\ub294 \uc81c\ub3c4\\"\uc785\ub2c8\ub2e4.<br/>\\n600\ub9cc\uc6d0\uacfc 900\ub9cc\uc6d0, 16.5%\uc640 13.2%\ub77c\ub294 \uc22b\uc790 \ub124 \uac1c\ub9cc \uae30\uc5b5\ud574\ub3c4 \uc5f0\ub9d0 \uc810\uac80\uc758 \uae30\uc900\uc774 \uc12d\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExM3Y4N3MweGZ4djhmZmRkbTg5cjhyNWI3Y3d2bWJnNWp2bnU4d3lsbiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/KoWFceykJC0NNjucLC/giphy.gif\\" alt=\\"Piggy bank\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"semiconductor-industry-structure","metadata":{"permalink":"/blog/finance/semiconductor-industry-structure","source":"@site/finance/2026-10-22-semiconductor-industry-structure/index.mdx","title":"\ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc758 \uad6c\uc870 \u2014 \uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4, \uc2e4\uc801 \uc2dc\uc98c\uc5d0 \ud655\uc778\ud558\ub294 \uac83\ub4e4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-22T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"sector","permalink":"/blog/finance/tags/sector"},{"inline":true,"label":"semiconductor","permalink":"/blog/finance/tags/semiconductor"}],"readingTime":3.16,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"semiconductor-industry-structure","title":"\ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc758 \uad6c\uc870 \u2014 \uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4, \uc2e4\uc801 \uc2dc\uc98c\uc5d0 \ud655\uc778\ud558\ub294 \uac83\ub4e4","authors":["way"],"tags":["finance","sector","semiconductor"]},"unlisted":false,"prevItem":{"title":"\uc5f0\uae08\uc800\ucd95\uacfc IRP \uc138\uc561\uacf5\uc81c \u2014 2026\ub144 \uae30\uc900 \ud55c\ub3c4\uc640 \uacc4\uc0b0\ubc95","permalink":"/blog/finance/pension-tax-credit-2026"},"nextItem":{"title":"\uc6d0/\ub2ec\ub7ec \ud658\uc728 \uc77d\ub294 \ubc95 \u2014 1,300\uc6d0\ub300 \ud658\uc728\uc774 \uc758\ubbf8\ud558\ub294 \uac83","permalink":"/blog/finance/usd-krw-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \uc624\ub298 \uc2dc\uc7a5\uc758 \ud558\ub77d\uc744 \uc8fc\ub3c4\ud55c \ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc758 \uad6c\uc870\uc640, \uc2e4\uc801 \uc2dc\uc98c\uc5d0 \uc774 \uc5c5\uc885\uc744 \ubcfc \ub54c \ud655\uc778\ud558\ub294 \uc9c0\ud45c\ub4e4\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\xb7\ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\ub294 \uae00\uc774 \uc544\ub2c8\ub77c, \uc0b0\uc5c5\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \uad50\uc721 \ubaa9\uc801\uc758 \ud574\uc124\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uc65c \ubc18\ub3c4\uccb4\uac00 \uc9c0\uc218\ub97c \uc6c0\uc9c1\uc774\ub294\uac00\\n\\n\uad6d\ub0b4 \uc99d\uc2dc\uc5d0\uc11c \ubc18\ub3c4\uccb4\uc758 \ube44\uc911\uc740 \ub9e4\uc6b0 \ud07d\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \ucf54\uc2a4\ud53c\uac00 3.52% \ud558\ub77d\ud55c \ub0a0\uc5d0\ub3c4 \uc0bc\uc131\uc804\uc790(-4.03%)\uc640 SK\ud558\uc774\ub2c9\uc2a4(-5.49%) \ub450 \uc885\ubaa9\uc758 \ud558\ub77d\uc774 \uc9c0\uc218 \ub099\ud3ed\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc744 \uc124\uba85\ud569\ub2c8\ub2e4.<br/>\\n([\uc544\uc8fc\uacbd\uc81c \ubcf4\ub3c4](https://www.ajunews.com/view/20261022154721705)\ub97c \uae30\uc900\uc73c\ub85c \ud569\ub2c8\ub2e4.)<br/>\\n\uc9c0\uc218\ub97c \uc6c0\uc9c1\uc774\ub294 \uc5c5\uc885\uc744 \uc774\ud574\ud558\ub824\uba74, \uadf8 \uc5c5\uc885\uc774 \uc5b4\ub5a4 \uad6c\uc870\ub85c \ub3c8\uc744 \ubc84\ub294\uc9c0\ub97c \uba3c\uc800 \uc54c\uc544\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExY3U4NWZjMDIwN3BldXQ1c3hiM2V3Z2ExZHdhbmt3Z2s3ano5OWFsMSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/R2eoW62p8mcKGWUKSk/giphy.gif\\" alt=\\"Chip\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc758 \ud070 \uadf8\ub9bc\\n\\n#### \uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4\\n\\n\ubc18\ub3c4\uccb4\ub294 \ud06c\uac8c \uba54\ubaa8\ub9ac \ubc18\ub3c4\uccb4\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4(\ube44\uba54\ubaa8\ub9ac)\ub85c \ub098\ub269\ub2c8\ub2e4.<br/>\\n\uba54\ubaa8\ub9ac \ubc18\ub3c4\uccb4\ub294 \ub370\uc774\ud130\ub97c \uc800\uc7a5\ud558\ub294 \uce69\uc73c\ub85c, D\ub7a8\uacfc \ub0b8\ub4dc\ud50c\ub798\uc2dc\uac00 \ub300\ud45c\uc801\uc785\ub2c8\ub2e4.<br/>\\n\uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4\ub294 \uc5f0\uc0b0\xb7\uc81c\uc5b4\ub97c \ub2f4\ub2f9\ud558\ub294 \uce69\uc73c\ub85c, CPU, GPU, \uc560\ud50c\ub9ac\ucf00\uc774\uc158 \ud504\ub85c\uc138\uc11c \ub4f1\uc774 \uc5ec\uae30\uc5d0 \uc18d\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d \uae30\uc5c5\uc774 \uac15\ud55c \ubd84\uc57c\ub294 \uba54\ubaa8\ub9ac \ubc18\ub3c4\uccb4\uc774\uba70, \uc138\uacc4 \uc2dc\uc7a5 \uc810\uc720\uc728 \uae30\uc900\uc73c\ub85c D\ub7a8\uacfc \ub0b8\ub4dc \ubaa8\ub450 \uc0c1\uc704\uad8c\uc744 \ucc28\uc9c0\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd5c\uadfc\uc5d0\ub294 AI \uc11c\ubc84\uc6a9 \uace0\ub300\uc5ed\ud3ed \uba54\ubaa8\ub9ac(HBM)\ucc98\ub7fc \uba54\ubaa8\ub9ac \uc548\uc5d0\uc11c\ub3c4 \uace0\ubd80\uac00 \uc81c\ud488\uc758 \ube44\uc911\uc774 \ucee4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ubc38\ub958\uccb4\uc778 \u2014 \uc124\uacc4, \uc0dd\uc0b0, \uc7a5\ube44, \uc18c\uc7ac\\n\\n\ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc740 \uc124\uacc4, \uc0dd\uc0b0, \uc7a5\ube44, \uc18c\uc7ac\ub85c \uc774\uc5b4\uc9c0\ub294 \uae34 \ubc38\ub958\uccb4\uc778\uc744 \uac00\uc9d1\ub2c8\ub2e4.<br/>\\n\uc124\uacc4\ub9cc \ud558\ub294 \ud68c\uc0ac\ub97c \ud339\ub9ac\uc2a4, \uc0dd\uc0b0\ub9cc \uc704\ud0c1\ubc1b\uc544 \ud558\ub294 \ud68c\uc0ac\ub97c \ud30c\uc6b4\ub4dc\ub9ac\ub77c\uace0 \ud569\ub2c8\ub2e4.<br/>\\n\uc124\uacc4\ubd80\ud130 \uc0dd\uc0b0\uae4c\uc9c0 \ubaa8\ub450 \ud558\ub294 \ud68c\uc0ac\ub294 \uc885\ud569\ubc18\ub3c4\uccb4\uae30\uc5c5(IDM)\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4.<br/>\\n\uc5ec\uae30\uc5d0 \ub178\uad11\xb7\uc2dd\uac01 \uc7a5\ube44\ub97c \ub9cc\ub4dc\ub294 \uc7a5\ube44 \uae30\uc5c5\uacfc, \uc6e8\uc774\ud37c\xb7\ud2b9\uc218\uac00\uc2a4\ub97c \uacf5\uae09\ud558\ub294 \uc18c\uc7ac \uae30\uc5c5\uc774 \uc0dd\ud0dc\uacc4\ub97c \uc774\ub8f9\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4\uc5d0\uc11c\ub294 \uc18c\ubd80\uc7a5(\uc18c\uc7ac\xb7\ubd80\ud488\xb7\uc7a5\ube44) \uae30\uc5c5\ub4e4\uc774 \ucf54\uc2a4\ub2e5\uc744 \uc911\uc2ec\uc73c\ub85c \ud3ec\uc9c4\ud574 \uc788\uc5b4, \uba54\ubaa8\ub9ac \uc5c5\ud669\uc774 \uc6c0\uc9c1\uc774\uba74 \ud568\uaed8 \uc601\ud5a5\uc744 \ubc1b\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc0ac\uc774\ud074 \uc0b0\uc5c5\uc758 \ud2b9\uc131\\n\\n\ubc18\ub3c4\uccb4\ub294 \ub300\ud45c\uc801\uc778 \uc0ac\uc774\ud074 \uc0b0\uc5c5\uc785\ub2c8\ub2e4.<br/>\\n\uc218\uc694\uac00 \ub298\uba74 \uac00\uaca9\uc774 \uc624\ub974\uace0(\uc5c5\uc0ac\uc774\ud074), \uacf5\uae09\uc774 \uacfc\uc789\ub418\uba74 \uac00\uaca9\uc774 \ub5a8\uc5b4\uc9c0\ub294(\ub2e4\uc6b4\uc0ac\uc774\ud074) \ud328\ud134\uc744 \ubc18\ubcf5\ud569\ub2c8\ub2e4.<br/>\\n\uac00\uaca9\uc744 \uc6c0\uc9c1\uc774\ub294 \ud575\uc2ec \ubcc0\uc218\ub294 \uc7ac\uace0\uc640 \uc218\uc694, \uadf8\ub9ac\uace0 \uacf5\uae09 \uc5c5\uccb4\ub4e4\uc758 \uc124\ube44\ud22c\uc790(CAPEX)\uc785\ub2c8\ub2e4.<br/>\\n\uc5c5\uc0ac\uc774\ud074\uc5d0\uc11c\ub294 \uc99d\uc124 \ud22c\uc790\uac00 \ub298\uace0, \ub2e4\uc6b4\uc0ac\uc774\ud074\uc5d0\uc11c\ub294 \uac10\uc0b0\uacfc \ud22c\uc790 \ucd95\uc18c\uac00 \ub098\ud0c0\ub0a9\ub2c8\ub2e4.<br/>\\n\uc774\ub7f0 \uc0ac\uc774\ud074 \ub54c\ubb38\uc5d0 \ubc18\ub3c4\uccb4 \uae30\uc5c5\uc758 \uc2e4\uc801\uc740 \ubd84\uae30\ub9c8\ub2e4 \ud06c\uac8c \ucd9c\ub801\uc774\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\uc801 \uc2dc\uc98c\uc5d0 \ud655\uc778\ud558\ub294 \uac83\ub4e4\\n\\n#### \uc7ac\uace0\uc640 \uac00\uaca9(ASP)\\n\\n\uba54\ubaa8\ub9ac \uc2e4\uc801\uc744 \ubcfc \ub54c \uac00\uc7a5 \uba3c\uc800 \ud655\uc778\ud558\ub294 \uac83\uc740 \uc7ac\uace0 \uc218\uc900\uacfc \ud3c9\uade0\ud310\ub9e4\ub2e8\uac00(ASP)\uc785\ub2c8\ub2e4.<br/>\\n\uc7ac\uace0\uac00 \uc904\uace0 ASP\uac00 \uc624\ub974\uba74 \uc5c5\ud669 \uac1c\uc120\uc758 \uc2e0\ud638\ub85c \ud574\uc11d\ud558\uace0, \ubc18\ub300\uba74 \uc218\uc694 \ub454\ud654\ub97c \uc758\uc2ec\ud569\ub2c8\ub2e4.<br/>\\n\ubd84\uae30 \uc2e4\uc801 \ubc1c\ud45c \ub54c \uacf5\uac1c\ub418\ub294 \uc7ac\uace0\uc790\uc0b0\uc758 \uc99d\uac10\uc740 \ub2e4\uc74c \ubd84\uae30 \uac00\uaca9 \ubc29\ud5a5\uc744 \uac00\ub2a0\ud558\ub294 \ub2e8\uc11c\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### \uc124\ube44\ud22c\uc790(CAPEX) \uac00\uc774\ub358\uc2a4\\n\\n\uae30\uc5c5\uc774 \uc81c\uc2dc\ud558\ub294 \ub0b4\ub144 \uc124\ube44\ud22c\uc790 \uacc4\ud68d\ub3c4 \uc911\uc694\ud55c \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\nCAPEX\uac00 \ub298\uba74 \uacf5\uae09 \uc99d\uac00\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5b4 \uac00\uaca9\uc5d0 \ubd80\ub2f4\uc774 \ub418\uace0, \uc904\uba74 \uacf5\uae09 \uc870\uc808\ub85c \ud574\uc11d\ub429\ub2c8\ub2e4.<br/>\\n\uc5b4\uc81c \ubbf8\uad6d \uc2dc\uc7a5\uc5d0\uc11c \uba54\ud0c0\uac00 \ud638\uc2e4\uc801\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \ub0b4\ub144 \uc124\ube44\ud22c\uc790 \uac00\uc774\ub358\uc2a4\ub97c \uc81c\uc2dc\ud558\uc9c0 \uc54a\uc544 \ud22c\uc790\uc2ec\ub9ac\uac00 \uc704\ucd95\ub41c \uac83\ub3c4 \uac19\uc740 \ub9e5\ub77d\uc785\ub2c8\ub2e4.<br/>\\n\ube45\ud14c\ud06c\uc758 CAPEX\ub294 AI \uc11c\ubc84 \uc218\uc694, \uc989 \uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4 \uc218\uc694\ub85c \uc9c1\uacb0\ub418\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc790\ud68c\uc0ac \uc774\uc288\uc640 \uc8fc\uc8fc \uac00\uce58\\n\\n\uc624\ub298 SK\ud558\uc774\ub2c9\uc2a4\uc5d0\ub294 \ubbf8\uad6d \uc790\ud68c\uc0ac \uc194\ub9ac\ub2e4\uc784\uc758 \uc0c1\uc7a5 \ucd94\uc9c4\uc744 \ub458\ub7ec\uc2fc \uc911\ubcf5\uc0c1\uc7a5 \ub17c\ub780\uc774 \ubd80\ub2f4\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\ud68c\uc0ac \uc0c1\uc7a5\uc774 \uc65c \ubaa8\ud68c\uc0ac\uc5d0 \ubd80\ub2f4\uc774 \ub418\ub294\uc9c0 \uc774\ud574\ud558\ub824\uba74 \uc8fc\uc8fc \uac00\uce58\uc758 \uad00\uc810\uc5d0\uc11c \ubd10\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc790\ud68c\uc0ac\uc758 \uac00\uce58\uac00 \ubcc4\ub3c4\ub85c \uc0c1\uc7a5\ub418\uba70 \uc2dc\uc7a5\uc5d0\uc11c \uc7ac\ud3c9\uac00\ub418\uba74, \uae30\uc874 \ubaa8\ud68c\uc0ac \uc8fc\uc8fc\uac00 \ubcf4\uc720\ud55c \uc9c0\ubd84 \uac00\uce58\uc5d0 \ub300\ud55c \ud560\uc778 \uc6b0\ub824\uac00 \uc0dd\uae30\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub7f0 \uc774\uc288\uac00 \ub098\uc62c \ub54c\ub294 \uacf5\uc2dc\ub41c \uc0c1\uc7a5 \uad6c\uc870\uc640 \uc9c0\ubd84 \uad00\uacc4\ub97c \uc6d0\ubb38\uc73c\ub85c \ud655\uc778\ud558\ub294 \uac83\uc774 \uae30\ubcf8\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\n\ubc18\ub3c4\uccb4 \ub274\uc2a4\ub97c \ubcfc \ub54c\ub294 \ud5e4\ub4dc\ub77c\uc778\ubcf4\ub2e4 \uc218\uce58\uc758 \ucd9c\ucc98\ub97c \uba3c\uc800 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\nASP, \uc7ac\uace0, \uac00\ub3d9\ub960 \uac19\uc740 \uc9c0\ud45c\ub294 \ubd84\uae30 \ubcf4\uace0\uc11c\uc640 \uc2e4\uc801 \ubc1c\ud45c \uc790\ub8cc\uc5d0 \uc6d0\ubb38\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\nCAPEX \uac00\uc774\ub358\uc2a4\ub294 \uae30\uc5c5 IR \uc790\ub8cc\ub098 \ucee8\ud37c\ub7f0\uc2a4\ucf5c \uae30\ub85d\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\ud68c\uc0ac \uc0c1\uc7a5 \uac19\uc740 \uc9c0\ubc30\uad6c\uc870 \uc774\uc288\ub294 \uc804\uc790\uacf5\uc2dc(DART)\uc758 \uacf5\uc2dc \uc6d0\ubb38\uc744 \uc77d\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc5c5\uc885 \uc804\uccb4\uc758 \ud750\ub984\uc744 \ubcfc \ub54c\ub294 \uac1c\ubcc4 \uae30\uc5c5 \ub274\uc2a4\uc640 \ud568\uaed8 \uba54\ubaa8\ub9ac \uac00\uaca9 \ub3d9\ud5a5, \ube45\ud14c\ud06c\uc758 \uc124\ube44\ud22c\uc790 \uacc4\ud68d\uc744 \uacb9\uccd0\uc11c \ubd05\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ubc18\ub3c4\uccb4\ub294 \uad6c\uc870\ub97c \uc54c\uba74 \ub274\uc2a4\uac00 \uc77d\ud788\uace0, \uad6c\uc870\ub97c \ubaa8\ub974\uba74 \ub4f1\ub77d\ub9cc \ubcf4\uc774\ub294 \uc5c5\uc885\uc785\ub2c8\ub2e4.<br/>\\n\uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4\uc758 \uad6c\ubd84, \ubc38\ub958\uccb4\uc778, \uc0ac\uc774\ud074\uc758 \uad00\uc810\uc744 \uac16\ucdb0 \ub450\uba74 \uc2e4\uc801 \uc2dc\uc98c\uc758 \uc22b\uc790\ub4e4\uc744 \ucc28\ubd84\ud788 \ud574\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExY3U4NWZjMDIwN3BldXQ1c3hiM2V3Z2ExZHdhbmt3Z2s3ano5OWFsMSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/ihM636Z71DgV3ZKZiP/giphy.gif\\" alt=\\"Technology\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"usd-krw-guide","metadata":{"permalink":"/blog/finance/usd-krw-guide","source":"@site/finance/2026-10-22-usd-krw-guide/index.mdx","title":"\uc6d0/\ub2ec\ub7ec \ud658\uc728 \uc77d\ub294 \ubc95 \u2014 1,300\uc6d0\ub300 \ud658\uc728\uc774 \uc758\ubbf8\ud558\ub294 \uac83","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-22T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"fx","permalink":"/blog/finance/tags/fx"},{"inline":true,"label":"exchange-rate","permalink":"/blog/finance/tags/exchange-rate"}],"readingTime":3.03,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"usd-krw-guide","title":"\uc6d0/\ub2ec\ub7ec \ud658\uc728 \uc77d\ub294 \ubc95 \u2014 1,300\uc6d0\ub300 \ud658\uc728\uc774 \uc758\ubbf8\ud558\ub294 \uac83","authors":["way"],"tags":["finance","fx","exchange-rate"]},"unlisted":false,"prevItem":{"title":"\ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc758 \uad6c\uc870 \u2014 \uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4, \uc2e4\uc801 \uc2dc\uc98c\uc5d0 \ud655\uc778\ud558\ub294 \uac83\ub4e4","permalink":"/blog/finance/semiconductor-industry-structure"},"nextItem":{"title":"\ubd84\uc0b0\ud22c\uc790\uc640 \ub9ac\ubc38\ub7f0\uc2f1 \u2014 \uc815\ud574\ub454 \ube44\uc911\uc744 \uc9c0\ud0a4\ub294 \ubc29\ubc95","permalink":"/blog/finance/diversification-rebalancing"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 5\uac70\ub798\uc77c \uc5f0\uc18d \ud558\ub77d\ud55c \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc758 \uc6c0\uc9c1\uc784\uc744 \uacc4\uae30\ub85c, \ud658\uc728\uc744 \uc77d\ub294 \uae30\ubcf8\uc801\uc778 \ubc29\ubc95\uc744 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uc624\ub298\uc758 \ud658\uc728\\n\\n2026\ub144 10\uc6d4 22\uc77c, \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 1,324.6\uc6d0\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 1.4\uc6d0, 0.11% \ud558\ub77d\ud55c \uc218\uce58\ub85c, 5\uac70\ub798\uc77c \uc5f0\uc18d \ud558\ub77d\uc138\ub97c \uc774\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n(KIS MTS \uc2dc\uc7a5 \ub370\uc774\ud130 \uae30\uc900\uc785\ub2c8\ub2e4.)<br/>\\n\ud658\uc728\uc740 \uc8fc\uc2dd\ub9cc\ud07c \uc790\uc8fc \uc5b8\uae09\ub418\uc9c0\ub9cc, \uc22b\uc790\uc758 \ubc29\ud5a5\uc744 \ubc18\ub300\ub85c \uc77d\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc744 \uacc4\uae30\ub85c \ud658\uc728 \ud45c\uc2dc\ubc95\uacfc \ud574\uc11d\uc758 \uae30\ubcf8\uc744 \uc815\ub9ac\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExd3l1ZjhyMnd4Nmd4eTF0OGhycndudWNjajM4bWJlcnYydGpib2M3ciZlcD12MV9naWZzX3NlYXJjaCZjdD1n/h0MTqLyvgG0Ss/giphy.gif\\" alt=\\"Dollar\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ud658\uc728 \uc22b\uc790\uc758 \uc77d\ub294 \ubc95\\n\\n#### \uc6d0/\ub2ec\ub7ec 1,324.6\uc6d0\uc758 \ub73b\\n\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728 1,324.6\uc6d0\uc740 1\ub2ec\ub7ec\ub97c \uc0ac\ub294 \ub370 1,324.6\uc6d0\uc774 \ud544\uc694\ud558\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\uc989, \ub2ec\ub7ec\uc758 \uc6d0\ud654 \uac00\uaca9\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc22b\uc790\uac00 \uc624\ub974\uba74 \ub2ec\ub7ec\uac00 \ube44\uc2f8\uc9c4 \uac83\uc774\uace0, \uc6d0\ud654\uc758 \uac00\uce58\ub294 \ub5a8\uc5b4\uc9c4 \uac83\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc22b\uc790\uac00 \ub0b4\ub9ac\uba74 \ub2ec\ub7ec\uac00 \uc2f8\uc9c4 \uac83\uc774\uace0, \uc6d0\ud654\uc758 \uac00\uce58\ub294 \uc62c\ub77c\uac04 \uac83\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\ucc98\ub7fc \ud658\uc728\uc774 \ud558\ub77d\ud588\ub2e4\ub294 \uac83\uc740 \uc6d0\ud654\uac00 \uac15\uc138\ub97c \ubcf4\uc600\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ud658\uc728 \uc0c1\uc2b9\uacfc \ud558\ub77d\uc758 \ud45c\ud604\\n\\n\ud658\uc728\uc774 \uc624\ub97c \ub54c\ub294 \\"\ud658\uc728 \uc0c1\uc2b9\\" \ub610\ub294 \\"\uc6d0\ud654 \uc57d\uc138(\uc6d0\ud654 \uac00\uce58 \ud558\ub77d)\\"\ub77c\uace0 \ud45c\ud604\ud569\ub2c8\ub2e4.<br/>\\n\ud658\uc728\uc774 \ub0b4\ub9b4 \ub54c\ub294 \\"\ud658\uc728 \ud558\ub77d\\" \ub610\ub294 \\"\uc6d0\ud654 \uac15\uc138(\uc6d0\ud654 \uac00\uce58 \uc0c1\uc2b9)\\"\ub77c\uace0 \ud45c\ud604\ud569\ub2c8\ub2e4.<br/>\\n\ub274\uc2a4\uc5d0\uc11c \\"\ud658\uc728\uc774 \uc62c\ub790\ub2e4\\"\uc640 \\"\uc6d0\ud654\uac00 \uac15\uc138\ub2e4\\"\ub294 \ubc18\ub300 \ubc29\ud5a5\uc744 \uac00\ub9ac\ud0a4\ubbc0\ub85c, \uc8fc\uc5b4\uac00 \ubb34\uc5c7\uc778\uc9c0 \ud655\uc778\ud558\uace0 \uc77d\uc5b4\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n### \ud658\uc728\uc744 \uc6c0\uc9c1\uc774\ub294 \uc694\uc778\ub4e4\\n\\n#### \uae08\ub9ac \ucc28\uc774\\n\\n\ub450 \ub098\ub77c\uc758 \uae08\ub9ac \ucc28\uc774\uac00 \ud658\uc728\uc5d0 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uae08\ub9ac\uac00 \ud55c\uad6d\ubcf4\ub2e4 \ub192\uc73c\uba74 \ub2ec\ub7ec \uc790\uc0b0\uc758 \uc774\uc790 \ub9e4\ub825\uc774 \ucee4\uc838 \ub2ec\ub7ec \uc218\uc694\uac00 \ub298\uc5b4\ub0a9\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \ud55c\uad6d\uc740\ud589\uc774 \uae30\uc900\uae08\ub9ac\ub97c 3.00%\ub85c \ub3d9\uacb0\ud55c \uac00\uc6b4\ub370, \ubbf8\uad6d\uc758 \uae08\ub9ac \ubc29\ud5a5\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \ubc14\ub00c\uba74 \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc774 \uc6c0\uc9c1\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uacb0\uc815\ubb38\uc744 \ubcfc \ub54c\ub294 \uad6d\ub0b4 \uae08\ub9ac\ubfd0 \uc544\ub2c8\ub77c \ubbf8\uad6d \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\uc758 \uc815\ucc45 \ubc29\ud5a5\ub3c4 \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubb34\uc5ed\uc218\uc9c0\uc640 \uc678\uad6d\uc778 \uc790\uae08\\n\\n\uc218\ucd9c\uc774 \ub298\uba74 \ub2ec\ub7ec\uac00 \uad6d\ub0b4\ub85c \ub4e4\uc5b4\uc640 \uc6d0\ud654 \uac15\uc138 \uc694\uc778\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc218\uc785\uc774 \ub298\uac70\ub098 \ud574\uc678\ud22c\uc790\uac00 \ub298\uba74 \ub2ec\ub7ec \uc218\uc694\uac00 \ub298\uc5b4 \uc6d0\ud654 \uc57d\uc138 \uc694\uc778\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc8fc\uc2dd\uc2dc\uc7a5\uc758 \uc678\uad6d\uc778 \ub9e4\ub9e4\ub3c4 \ud658\uc728\uacfc \uc5f0\uacb0\ub429\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc774 \uad6d\ub0b4 \uc8fc\uc2dd\uc744 \uc0ac\ub824\uba74 \uc6d0\ud654\ub97c \uc0ac\uc57c \ud558\ubbc0\ub85c, \uc678\uad6d\uc778 \uc21c\ub9e4\uc218\ub294 \uc6d0\ud654 \uac15\uc138\uc640 \ud568\uaed8 \ub098\ud0c0\ub098\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uc9c0\uc218\uac00 3.52% \ud558\ub77d\ud588\ub294\ub370\ub3c4 \ud658\uc728\uc774 \ud558\ub77d(\uc6d0\ud654 \uac15\uc138)\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc774 \ucf54\uc2a4\ud53c\uc5d0\uc11c 619\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud55c \ub0a0\uc774\uc5c8\uc73c\ubbc0\ub85c, \uc624\ub298\uc758 \uc6d0\ud654 \uac15\uc138\ub294 \uc678\uad6d\uc778 \uc790\uae08 \uc720\uc785\ubcf4\ub2e4\ub294 \ub2e4\ub978 \uc694\uc778\uc5d0 \uae30\uc778\ud55c \uac83\uc73c\ub85c \ud574\uc11d\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ub2ec\ub7ec \uc790\uccb4\uc758 \uc6c0\uc9c1\uc784\\n\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 \ub2ec\ub7ec \uc790\uccb4\uc758 \uc6c0\uc9c1\uc784\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubc1b\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec \uc778\ub371\uc2a4\uac00 \uc624\ub974\uba74 \ub2ec\ub7ec\uac00 \uc8fc\uc694 \ud1b5\ud654 \ub300\ube44 \uac15\uc138\ub97c \ubcf4\uc774\ub294 \uac83\uc774\ubbc0\ub85c, \uc6d0/\ub2ec\ub7ec \ud658\uc728\ub3c4 \uc624\ub974\uae30 \uc27d\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0\ud654\uc758 \uac15\uc138\uc778\uc9c0 \ub2ec\ub7ec\uc758 \uc57d\uc138\uc778\uc9c0\ub97c \uad6c\ubd84\ud558\ub824\uba74, \uc5d4\ud654\xb7\uc720\ub85c\ud654 \ub300\ube44 \ub2ec\ub7ec\uc758 \uc6c0\uc9c1\uc784\ub3c4 \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\\n### \uc6d0\ud654 \uac15\uc138\uc640 \uc57d\uc138\uc758 \uc591\uba74\uc131\\n\\n#### \uc6d0\ud654 \uac15\uc138\uac00 \ubc18\uac00\uc6b4 \uacbd\uc6b0\uc640 \ubd80\ub2f4\uc2a4\ub7ec\uc6b4 \uacbd\uc6b0\\n\\n\uc6d0\ud654 \uac15\uc138\ub294 \uc218\uc785 \ubb3c\uac00\ub97c \ub0ae\ucdb0 \ubb3c\uac00 \uc548\uc815\uc5d0 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ud574\uc678\uc5ec\ud589\uc774\ub098 \ud574\uc678\uc9c1\uad6c, \uc678\ud654 \uc790\uc0b0 \ub9e4\uc218 \uc785\uc7a5\uc5d0\uc11c\ub294 \uc720\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uc218\ucd9c \uae30\uc5c5 \uc785\uc7a5\uc5d0\uc11c\ub294 \uac00\uaca9 \uacbd\uc7c1\ub825\uc774 \ub5a8\uc5b4\uc838 \ubd80\ub2f4\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ud658\uc728 \uc6c0\uc9c1\uc784\ub3c4 \uc785\uc7a5\uc5d0 \ub530\ub77c \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c0\ubbc0\ub85c, \ubc29\ud5a5 \ud558\ub098\ub9cc\uc73c\ub85c \uc88b\uace0 \ub098\uc068\uc744 \ub2e8\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc99d\uc2dc\uc640\uc758 \uad00\uacc4\\n\\n\uc77c\ubc18\uc801\uc73c\ub85c \uc6d0\ud654 \uac15\uc138\ub294 \uc678\uad6d\uc778 \uc790\uae08 \uc720\uc785\uacfc \ub9de\ubb3c\ub9ac\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc544 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \uc6b0\ud638\uc801\uc73c\ub85c \ud574\uc11d\ub418\uace4 \ud569\ub2c8\ub2e4.<br/>\\n\ud558\uc9c0\ub9cc \uc624\ub298\ucc98\ub7fc \uc9c0\uc218 \ud558\ub77d\uacfc \uc6d0\ud654 \uac15\uc138\uac00 \ub3d9\uc2dc\uc5d0 \ub098\ud0c0\ub098\uba74, \uc218\uae09\uc758 \uc8fc\uccb4\uac00 \ub2e4\ub974\ub2e4\ub294 \uc2e0\ud638\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud658\uc728\uacfc \uc9c0\uc218\ub97c \ub530\ub85c \ubcf4\uc9c0 \uc54a\uace0 \ud568\uaed8 \ubcf4\ub294 \uc2b5\uad00\uc774 \ud544\uc694\ud55c \uc774\uc720\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\n\ud658\uc728\uc744 \ubcfc \ub54c\ub294 \uc885\uac00 \uc22b\uc790 \ud558\ub098\ubcf4\ub2e4 \ubc29\ud5a5\uacfc \uc18d\ub3c4\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n5\uac70\ub798\uc77c \uc5f0\uc18d \ud558\ub77d\ucc98\ub7fc \uac19\uc740 \ubc29\ud5a5\uc774 \uc774\uc5b4\uc9c0\uba74, \uadf8 \ubc30\uacbd\uc774 \ubb34\uc5c7\uc778\uc9c0 \uae08\ub9ac\xb7\ubb34\uc5ed\xb7\ub2ec\ub7ec \uc778\ub371\uc2a4\uc5d0\uc11c \uc6d0\uc778\uc744 \ucc3e\uc2b5\ub2c8\ub2e4.<br/>\\nMTS\uc758 \ud658\uc728 \ud654\uba74\uc5d0\uc11c\ub294 \uc804\uc77c \ub300\ube44 \ub4f1\ub77d\uacfc \ud568\uaed8 \uc7a5\uc911 \uace0\uc810\xb7\uc800\uc810\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc218\ucd9c\uc785 \uae30\uc5c5\uc5d0 \ud22c\uc790\ud55c\ub2e4\uba74 \uc2e4\uc801 \ubc1c\ud45c \ub54c \ud658\uc728 \ubcc0\ub3d9\uc774 \ub9e4\ucd9c\uacfc \uc774\uc775\uc5d0 \ubbf8\uce5c \uc601\ud5a5\uc744 \uc124\uba85\ud558\ub294 \ubd80\ubd84\uc744 \ucc3e\uc544\ubd05\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ud658\uc728\uc740 \uc22b\uc790\uc758 \ubc29\ud5a5\ub9cc \uc815\ud655\ud788 \uc77d\uc5b4\ub3c4 \ub274\uc2a4\uc758 \uc808\ubc18\uc740 \uc774\ud574\ub429\ub2c8\ub2e4.<br/>\\n\\"\ub204\uad6c\uc758 \uac00\uaca9\uc774 \uc62c\ub790\ub294\uac00\\"\ub97c \uba3c\uc800 \ubb3b\ub294 \uc2b5\uad00\uc774 \ud658\uc728\uc744 \uc77d\ub294 \uccab\uac78\uc74c\uc785\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media1.giphy.com/media/v1.Y2lkPTc5MGI3NjExd3l1ZjhyMnd4Nmd4eTF0OGhycndudWNjajM4bWJlcnYydGpib2M3ciZlcD12MV9naWZzX3NlYXJjaCZjdD1n/11IXPaNTDdw2Eo/giphy.gif\\" alt=\\"Currency\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"diversification-rebalancing","metadata":{"permalink":"/blog/finance/diversification-rebalancing","source":"@site/finance/2026-10-21-diversification-rebalancing/index.mdx","title":"\ubd84\uc0b0\ud22c\uc790\uc640 \ub9ac\ubc38\ub7f0\uc2f1 \u2014 \uc815\ud574\ub454 \ube44\uc911\uc744 \uc9c0\ud0a4\ub294 \ubc29\ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-21T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"portfolio","permalink":"/blog/finance/tags/portfolio"},{"inline":true,"label":"basics","permalink":"/blog/finance/tags/basics"}],"readingTime":2.62,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"diversification-rebalancing","title":"\ubd84\uc0b0\ud22c\uc790\uc640 \ub9ac\ubc38\ub7f0\uc2f1 \u2014 \uc815\ud574\ub454 \ube44\uc911\uc744 \uc9c0\ud0a4\ub294 \ubc29\ubc95","authors":["way"],"tags":["finance","portfolio","basics"]},"unlisted":false,"prevItem":{"title":"\uc6d0/\ub2ec\ub7ec \ud658\uc728 \uc77d\ub294 \ubc95 \u2014 1,300\uc6d0\ub300 \ud658\uc728\uc774 \uc758\ubbf8\ud558\ub294 \uac83","permalink":"/blog/finance/usd-krw-guide"},"nextItem":{"title":"ETF\ub780 \ubb34\uc5c7\uc778\uac00 \u2014 \uc8fc\uc2dd\ucc98\ub7fc \uc0ac\uace0\ud30c\ub294 \ud380\ub4dc","permalink":"/blog/finance/etf-basics"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \ud22c\uc790\uc758 \uac00\uc7a5 \uae30\ubcf8 \uc6d0\uce59\uc73c\ub85c \uaf3d\ud788\ub294 \ubd84\uc0b0\ud22c\uc790\uc640 \ub9ac\ubc38\ub7f0\uc2f1\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\ud22c\uc790\ub97c \uc2dc\uc791\ud558\uba74 \uc5b4\ub5a4 \uc885\ubaa9\uc744 \uace0\ub97c\uc9c0\uc5d0 \uba3c\uc800 \uad00\uc2ec\uc774 \uac00\uae30 \ub9c8\ub828\uc785\ub2c8\ub2e4.<br/>\\n\ud558\uc9c0\ub9cc \uc7a5\uae30\uc801\uc778 \uc131\uacfc\ub294 \uc885\ubaa9 \uc120\ud0dd\ub9cc\ud07c\uc774\ub098 \uc790\uc0b0\uc744 \uc5b4\ub5bb\uac8c \ub098\ub204\uc5b4 \ub2f4\uace0, \uadf8 \ube44\uc911\uc744 \uc5b4\ub5bb\uac8c \uc720\uc9c0\ud558\ub290\ub0d0\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubc1b\uc2b5\ub2c8\ub2e4.<br/>\\n\ubd84\uc0b0\ud22c\uc790\ub294 \ube44\uc911\uc744 \uc124\uacc4\ud558\ub294 \ubc29\ubc95\uc774\uace0, \ub9ac\ubc38\ub7f0\uc2f1\uc740 \uadf8 \ube44\uc911\uc744 \uc2dc\uac04\uc774 \uc9c0\ub098\ub3c4 \uc720\uc9c0\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.<br/>\\n\ub450 \uac00\uc9c0\ub97c \ucc28\ub840\ub85c \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExY2l4eWJoZXp6enNmdnJyeGlibzdjNzJiaGhnaTltMzl0aHVnZ2dpdyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/PxZqQHKP3VFbkZ0EDI/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ubd84\uc0b0\ud22c\uc790\ub780\\n\\n#### \uc790\uc0b0\uad70\uc73c\ub85c \ub098\ub204\ub294 \uac83\ubd80\ud130 \uc2dc\uc791\ud569\ub2c8\ub2e4\\n\\n\ubd84\uc0b0\ud22c\uc790\ub294 \uc5ec\ub7ec \uc885\ubaa9\uc5d0 \ub098\ub204\uc5b4 \ub2f4\ub294 \uac83\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc8fc\uc2dd, \ucc44\uad8c, \ud604\uae08\uc131 \uc790\uc0b0\ucc98\ub7fc \uc131\uaca9\uc774 \ub2e4\ub978 \uc790\uc0b0\uad70\uc5d0 \ub098\ub204\ub294 \uac83\uc774 \ucd9c\ubc1c\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc8fc\uc2dd \uc548\uc5d0\uc11c\ub3c4 \uad6d\ub0b4\uc640 \ud574\uc678, \uc2dc\uac00\ucd1d\uc561 \uaddc\ubaa8\uac00 \ub2e4\ub978 \uc790\uc0b0\uc744 \uc11e\uc73c\uba74 \ud2b9\uc815 \uc2dc\uc7a5\uc774 \ud754\ub4e4\ub9b4 \ub54c \ubc1b\ub294 \ucda9\uaca9\uc744 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc0c1\uad00\uad00\uacc4\uac00 \ud575\uc2ec\uc785\ub2c8\ub2e4\\n\\n\uc0c1\uad00\uad00\uacc4\ub294 \ub450 \uc790\uc0b0\uc774 \uc5bc\ub9c8\ub098 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.<br/>\\n\ud568\uaed8 \uc624\ub974\uace0 \ud568\uaed8 \ub0b4\ub9ac\ub294 \uc790\uc0b0\ub9cc \ubaa8\uc544\ub450\uba74 \uac1c\uc218\ub294 \ub9ce\uc544\ub3c4 \ubd84\uc0b0 \ud6a8\uacfc\ub294 \uc791\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc6c0\uc9c1\uc784\uc774 \uc11c\ub85c \ub2e4\ub978 \uc790\uc0b0\uc744 \uc870\ud569\ud558\uba74, \ud55c\ucabd\uc774 \ud754\ub4e4\ub9b4 \ub54c \uc804\uccb4 \ud3ec\ud2b8\ud3f4\ub9ac\uc624\uc758 \ucd9c\ub801\uc784\uc774 \uc904\uc5b4\ub4dc\ub294 \ud6a8\uacfc\ub97c \uae30\ub300\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n```text\\n\uc608\uc2dc) \uc8fc\uac00\uac00 \ud558\ub77d\ud558\ub294 \uad6d\uba74\uc5d0\uc11c\ub3c4 \ucc44\uad8c \uac00\uaca9\uc774 \uc548\uc815\uc801\uc774\ub77c\uba74\\n     \uc804\uccb4 \uc790\uc0b0\uc758 \ud558\ub77d \ud3ed\uc740 \uc8fc\uc2dd\ub9cc \ubcf4\uc720\ud588\uc744 \ub54c\ubcf4\ub2e4 \uc791\uc544\uc9d1\ub2c8\ub2e4.\\n```\\n\\n\ubd84\uc0b0\uc758 \ubaa9\uc801\uc740 \uc218\uc775\uc744 \uadf9\ub300\ud654\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc608\uc0c1\ud558\uc9c0 \ubabb\ud55c \uc0c1\ud669\uc5d0\uc11c \ubc1b\ub294 \ucda9\uaca9\uc744 \uc904\uc774\ub294 \ub370 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9ac\ubc38\ub7f0\uc2f1\uc774\ub780\\n\\n#### \ud2c0\uc5b4\uc9c4 \ube44\uc911\uc744 \uc6d0\ub798\ub300\ub85c \ub418\ub3cc\ub9bd\ub2c8\ub2e4\\n\\n\uc2dc\uac04\uc774 \uc9c0\ub098\uba74 \uc624\ub978 \uc790\uc0b0\uc758 \ube44\uc911\uc740 \ucee4\uc9c0\uace0, \ub0b4\ub9b0 \uc790\uc0b0\uc758 \ube44\uc911\uc740 \uc791\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\ub9ac\ubc38\ub7f0\uc2f1\uc740 \uc774\ub807\uac8c \ud2c0\uc5b4\uc9c4 \ube44\uc911\uc744 \ucc98\uc74c \uc815\ud55c \ubaa9\ud45c \ube44\uc911\uc73c\ub85c \ub418\ub3cc\ub9ac\ub294 \uc791\uc5c5\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub978 \uc790\uc0b0\uc744 \uc77c\ubd80 \ud314\uace0 \ub0b4\ub9b0 \uc790\uc0b0\uc744 \uc0ac\ub294 \ud615\ud0dc\uac00 \ub418\ubbc0\ub85c, \uacb0\uacfc\uc801\uc73c\ub85c \ube44\uc2f8\uc9c4 \uac83\uc744 \uc904\uc774\uace0 \uc2f8\uc9c4 \uac83\uc744 \ub298\ub9ac\ub294 \uc6d0\uce59\uc774 \uc790\ub3d9\uc73c\ub85c \uc801\uc6a9\ub429\ub2c8\ub2e4.<br/>\\n\\n```text\\n\uc608\uc2dc) \ubaa9\ud45c \ube44\uc911\uc774 \uc8fc\uc2dd 60 : \ucc44\uad8c 40\uc778\ub370\\n     \uc8fc\uc2dd \uc0c1\uc2b9\uc73c\ub85c 70 : 30\uc774 \ub418\uc5c8\ub2e4\uba74\\n     \uc8fc\uc2dd\uc758 10\ub9cc\ud07c\uc744 \ud314\uc544 \ucc44\uad8c\uc744 \uc0ac\uc11c 60 : 40\uc73c\ub85c \ub418\ub3cc\ub9bd\ub2c8\ub2e4.\\n```\\n\\n#### \uc8fc\uae30\ub97c \uc815\ud558\ub294 \ub450 \uac00\uc9c0 \ubc29\ubc95\\n\\n\ub0a0\uc9dc \uae30\uc900\uc73c\ub85c \uc815\ud558\ub294 \ubc29\ubc95\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubd84\uae30\ub098 \ubc18\uae30\ucc98\ub7fc \uc815\ud574\uc9c4 \uc2dc\uc810\uc5d0 \ube44\uc911\uc744 \uc810\uac80\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c, \uaddc\uce59\uc774 \ub2e8\uc21c\ud574 \uafb8\uc900\ud788 \uc2e4\ucc9c\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4.<br/>\\n\ube44\uc911 \uae30\uc900\uc73c\ub85c \uc815\ud558\ub294 \ubc29\ubc95\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubaa9\ud45c\uc5d0\uc11c \uc77c\uc815 \ud3ed \uc774\uc0c1 \ubc97\uc5b4\ub0ac\uc744 \ub54c\ub9cc \uc870\uc815\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c, \uc7a6\uc740 \uac70\ub798\ub97c \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5b4\ub290 \ucabd\uc744 \ud0dd\ud558\ub4e0 \ub9e4\ub9e4\uc5d0\ub294 \uc218\uc218\ub8cc\uc640 \uc138\uae08 \uac19\uc740 \ube44\uc6a9\uc774 \ub530\ub97c \uc218 \uc788\uc73c\ubbc0\ub85c, \ub108\ubb34 \uc7a6\uc740 \uc870\uc815\uc740 \uc624\ud788\ub824 \uc190\ud574\uac00 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ucd08\ubcf4\uc790\uac00 \ud754\ud788 \ud558\ub294 \uc2e4\uc218\\n\\n\uc885\ubaa9 \uc218\ub9cc \ub298\ub9ac\uace0 \ubd84\uc0b0\ud588\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \uacbd\uc6b0\uc785\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uc131\uaca9\uc758 \uc790\uc0b0\ub9cc \ub9ce\uc544\uc9c0\uba74 \ubd84\uc0b0 \ud6a8\uacfc\ub294 \uc81c\ud55c\uc801\uc77c \uc218\ubc16\uc5d0 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub978 \uc790\uc0b0\ub9cc \uacc4\uc18d \uc0ac\uc11c \ube44\uc911\uc774 \ud55c\ucabd\uc73c\ub85c \uc3e0\ub9ac\ub294 \uacbd\uc6b0\ub3c4 \ud754\ud569\ub2c8\ub2e4.<br/>\\n\ub9ac\ubc38\ub7f0\uc2f1 \uc5c6\uc774 \uadf8\ub300\ub85c \ub450\uba74 \ucc98\uc74c \uc758\ub3c4\uc640 \uc804\ud600 \ub2e4\ub978 \ud3ec\ud2b8\ud3f4\ub9ac\uc624\uac00 \ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc774 \ud754\ub4e4\ub9b4 \ub54c\ub9c8\ub2e4 \ube44\uc911\uc744 \ubc14\uafb8\ub294 \uac83\ub3c4 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ub9ac\ubc38\ub7f0\uc2f1\uc740 \uc2dc\uc7a5\uc744 \ub9de\ud788\uae30 \uc704\ud55c \ub3c4\uad6c\uac00 \uc544\ub2c8\ub77c, \uc815\ud574\ub454 \uc6d0\uce59\uc744 \uc9c0\ud0a4\uae30 \uc704\ud55c \ub3c4\uad6c\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\ubaa9\ud45c \ube44\uc911\uc740 \uc790\uc2e0\uc758 \ud22c\uc790 \uae30\uac04\uacfc \uac10\ub2f9\ud560 \uc218 \uc788\ub294 \ud558\ub77d \ud3ed\uc744 \uba3c\uc800 \uc815\ud55c \ub4a4\uc5d0 \uc815\ud558\ub294 \uac83\uc774 \uc21c\uc11c\uc785\ub2c8\ub2e4.<br/>\\n\uc801\ub9bd\uc2dd\uc73c\ub85c \uafb8\uc900\ud788 \ud22c\uc790\ud558\uace0 \uc788\ub2e4\uba74, \uc0c8\ub85c \ub123\ub294 \ub3c8\uc73c\ub85c \ubd80\uc871\ud574\uc9c4 \uc790\uc0b0\uad70\uc744 \ucc44\uc6b0\ub294 \ubc29\uc2dd\uc73c\ub85c\ub3c4 \ube44\uc911\uc744 \ub9de\ucd9c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub807\uac8c \ud558\uba74 \ud30c\ub294 \uac70\ub798\ub97c \uc904\uc774\uba74\uc11c \ubaa9\ud45c \ube44\uc911\uc5d0 \uac00\uae4c\uc6cc\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ubd84\uc0b0\ud22c\uc790\uac00 \uc704\ud5d8\uc744 \ub098\ub204\ub294 \uc124\uacc4\ub77c\uba74, \ub9ac\ubc38\ub7f0\uc2f1\uc740 \uadf8 \uc124\uacc4\uac00 \uc2dc\uac04\uc774 \uc9c0\ub098\ub3c4 \uc720\uc9c0\ub418\ub3c4\ub85d \ud558\ub294 \uad00\ub9ac \ubc29\ubc95\uc785\ub2c8\ub2e4.<br/>\\n\uc885\ubaa9\uc744 \uace0\ub974\ub294 \uc77c\ub9cc\ud07c, \ube44\uc911\uc744 \uc815\ud558\uace0 \uc9c0\ud0a4\ub294 \uc77c\uc744 \ud22c\uc790 \uacfc\uc815\uc758 \uc77c\ubd80\ub85c \ub450\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZzljbTkxanZmajYwZXF6ZWtvbmtlbGhvNjBtdW80NnliYm84dmxsNCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/5bcVz12UJLRvyLlx21/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"etf-basics","metadata":{"permalink":"/blog/finance/etf-basics","source":"@site/finance/2026-10-21-etf-basics/index.mdx","title":"ETF\ub780 \ubb34\uc5c7\uc778\uac00 \u2014 \uc8fc\uc2dd\ucc98\ub7fc \uc0ac\uace0\ud30c\ub294 \ud380\ub4dc","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-21T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"etf","permalink":"/blog/finance/tags/etf"},{"inline":true,"label":"basics","permalink":"/blog/finance/tags/basics"}],"readingTime":3.07,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"etf-basics","title":"ETF\ub780 \ubb34\uc5c7\uc778\uac00 \u2014 \uc8fc\uc2dd\ucc98\ub7fc \uc0ac\uace0\ud30c\ub294 \ud380\ub4dc","authors":["way"],"tags":["finance","etf","basics"]},"unlisted":false,"prevItem":{"title":"\ubd84\uc0b0\ud22c\uc790\uc640 \ub9ac\ubc38\ub7f0\uc2f1 \u2014 \uc815\ud574\ub454 \ube44\uc911\uc744 \uc9c0\ud0a4\ub294 \ubc29\ubc95","permalink":"/blog/finance/diversification-rebalancing"},"nextItem":{"title":"\uae08\ub9ac\uc640 \uc8fc\uac00\uc758 \uad00\uacc4 \u2014 \uae30\uc900\uae08\ub9ac\uac00 \uc6c0\uc9c1\uc774\uba74 \uc8fc\uac00\ub294 \uc65c \uc6c0\uc9c1\uc77c\uae4c","permalink":"/blog/finance/interest-rate-and-stocks"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \ud380\ub4dc\uc640 \uc8fc\uc2dd\uc758 \uc911\uac04 \ud615\ud0dc\ub85c \ubd88\ub9ac\ub294 ETF\uac00 \ubb34\uc5c7\uc778\uc9c0, \uc5b4\ub5a4 \uc810\uc744 \ud655\uc778\ud558\uace0 \uace8\ub77c\uc57c \ud558\ub294\uc9c0\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\uac1c\ubcc4 \uc885\ubaa9\uc744 \uace0\ub974\ub294 \uac83\uc774 \ubd80\ub2f4\uc2a4\ub7fd\uc9c0\ub9cc \uc608\uae08\ub9cc\uc73c\ub85c\ub294 \uc544\uc26c\uc6b4 \ubd84\ub4e4\uc774 \ucc98\uc74c \uc811\ud558\ub294 \uc0c1\ud488\uc774 ETF\uc778 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\nETF\ub294 \uc774\ub984 \uadf8\ub300\ub85c \uac70\ub798\uc18c\uc5d0 \uc0c1\uc7a5\ub41c \ud380\ub4dc(Exchange Traded Fund)\uc785\ub2c8\ub2e4.<br/>\\n\uc5ec\ub7ec \uc885\ubaa9\uc744 \ud55c \ubc14\uad6c\ub2c8\uc5d0 \ub2f4\uc544 \uc6b4\uc6a9\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c\ub294 \ud380\ub4dc\uc640 \uac19\uace0, \uadf8 \ubc14\uad6c\ub2c8\ub97c \uc8fc\uc2dd\ucc98\ub7fc \uc2e4\uc2dc\uac04\uc73c\ub85c \uc0ac\uace0\ud314 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c\ub294 \uc8fc\uc2dd\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uc870 \ub355\ubd84\uc5d0 \ud558\ub098\uc758 \uc0c1\ud488\uc744 \uc0ac\ub294 \uac83\ub9cc\uc73c\ub85c \uc5ec\ub7ec \uc885\ubaa9\uc5d0 \ub098\ub204\uc5b4 \ud22c\uc790\ud558\ub294 \ud6a8\uacfc\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExODg5anViMzF1aG5vcHo3MG4zcjYxaWFyMmszNTlqNDBrcW8xb2s4dyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/7oIn6Khh0sF3r4qQdW/giphy.gif\\" alt=\\"Investment\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### ETF\uc758 \uae30\ubcf8 \uad6c\uc870\\n\\n#### \uc9c0\uc218 \ucd94\uc885\\n- \ub300\ubd80\ubd84\uc758 ETF\ub294 \ud2b9\uc815 \uc9c0\uc218\uc758 \uc6c0\uc9c1\uc784\uc744 \ub530\ub77c\uac00\ub3c4\ub85d \uc124\uacc4\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.\\n- \uc608\ub97c \ub4e4\uc5b4 \ucf54\uc2a4\ud53c200 \uc9c0\uc218\ub97c \ucd94\uc885\ud558\ub294 ETF\ub294 \uc9c0\uc218\ub97c \uad6c\uc131\ud558\ub294 \ub300\ud615\uc8fc\ub4e4\uc744 \ube44\uc2b7\ud55c \ube44\uc911\uc73c\ub85c \ub2f4\uc2b5\ub2c8\ub2e4.\\n- \uc9c0\uc218\uac00 \uc624\ub974\uba74 ETF \uac00\uaca9\ub3c4 \ube44\uc2b7\ud55c \ube44\uc728\ub85c \uc624\ub974\ub294 \uac83\uc744 \ubaa9\ud45c\ub85c \uc6b4\uc6a9\ub429\ub2c8\ub2e4.\\n- \uc6b4\uc6a9\uc0ac\uac00 \uc885\ubaa9\uc744 \uc9c1\uc811 \uace0\ub974\ub294 \uc561\ud2f0\ube0c ETF\ub3c4 \uc788\uc9c0\ub9cc, \uc9c0\uc218 \ucd94\uc885\ud615\uc774 \uae30\ubcf8 \ud615\ud0dc\uc785\ub2c8\ub2e4.\\n\\n#### \uc8fc\uc2dd\uacfc\uc758 \ucc28\uc774\\n- \uc8fc\uc2dd\uc740 \ud55c \uae30\uc5c5\uc758 \uc9c0\ubd84\uc744 \uc0ac\ub294 \uac83\uc774\uace0, ETF\ub294 \uc5ec\ub7ec \uc790\uc0b0\uc744 \ub2f4\uc740 \ubc14\uad6c\ub2c8\uc758 \uc9c0\ubd84\uc744 \uc0ac\ub294 \uac83\uc785\ub2c8\ub2e4.\\n- \uc8fc\uc2dd\ucc98\ub7fc \uc7a5\uc911\uc5d0 \uc2e4\uc2dc\uac04\uc73c\ub85c \ub9e4\ub9e4\ud560 \uc218 \uc788\uace0, \ud638\uac00\ub97c \ubcf4\uba74\uc11c \uac00\uaca9\uc744 \uc9c0\uc815\ud574 \uc8fc\ubb38\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \uc77c\ubc18 \ud380\ub4dc\ucc98\ub7fc \ud658\ub9e4\uc5d0 \uba70\uce60\uc774 \uac78\ub9ac\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774 \ud070 \ucc28\uc774\uc785\ub2c8\ub2e4.\\n\\n#### \ud380\ub4dc\uc640\uc758 \ucc28\uc774\\n- \uc77c\ubc18 \ud380\ub4dc\ub294 \ud558\ub8e8\uc5d0 \ud55c \ubc88 \uc815\ud574\uc9c0\ub294 \uae30\uc900\uac00\uaca9\uc73c\ub85c \uac70\ub798\ub418\uc9c0\ub9cc, ETF\ub294 \uc7a5\uc911 \uac00\uaca9\uc774 \uacc4\uc18d \ubc14\ub01d\ub2c8\ub2e4.\\n- \uc77c\ubc18 \ud380\ub4dc\uc5d0 \ubd80\uacfc\ub418\ub294 \ud310\ub9e4 \uc218\uc218\ub8cc\uac00 \uc5c6\ub294 \uacbd\uc6b0\uac00 \ub9ce\uace0, MTS\uc5d0\uc11c \uc8fc\uc2dd\uacfc \uac19\uc740 \ud654\uba74\uc73c\ub85c \uac70\ub798\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \uc0ac\uae30 \uc804\uc5d0 \ud655\uc778\ud574\uc57c \ud560 \uac83\ub4e4\\n\\n#### \ubcf4\uc218(TER)\\n- ETF\ub97c \ubcf4\uc720\ud558\ub294 \ub3d9\uc548 \uc6b4\uc6a9 \ube44\uc6a9\uc73c\ub85c \ucc28\uac10\ub418\ub294 \ube44\uc728\uc744 \ucd1d\ubcf4\uc218(TER)\ub77c\uace0 \ud569\ub2c8\ub2e4.\\n- \ubcf4\uc218\ub294 \uc218\uc775\ub960\uc5d0\uc11c \ub9e4\uc77c \uc870\uae08\uc529 \ubc18\uc601\ub418\uc5b4 \ube60\uc9c0\uae30 \ub54c\ubb38\uc5d0, \uac19\uc740 \uc9c0\uc218\ub97c \ucd94\uc885\ud558\ub294 \uc0c1\ud488\ub07c\ub9ac\ub294 \ubcf4\uc218\uac00 \ub0ae\uc744\uc218\ub85d \uc7a5\uae30 \uc131\uacfc\uc5d0 \uc720\ub9ac\ud569\ub2c8\ub2e4.\\n- \uc0c1\ud488 \uc774\ub984\uc774 \ube44\uc2b7\ud574\ub3c4 \uc6b4\uc6a9\uc0ac\ub9c8\ub2e4 \ubcf4\uc218\uac00 \ub2e4\ub97c \uc218 \uc788\uc5b4 \ube44\uad50\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n#### \uad34\ub9ac\uc728\\n- ETF\uc758 \uc2dc\uc7a5\uac00\uaca9\uacfc \uc2e4\uc81c \ubc14\uad6c\ub2c8\uc758 \uac00\uce58(\uc21c\uc790\uc0b0\uac00\uce58, NAV)\uac00 \ubc8c\uc5b4\uc9c4 \uc815\ub3c4\ub97c \uad34\ub9ac\uc728\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.\\n- \uac70\ub798\uac00 \ud65c\ubc1c\ud558\uc9c0 \uc54a\uc740 \uc0c1\ud488\uc740 \uc2dc\uc7a5\uac00\uaca9\uc774 \uc790\uc0b0 \uac00\uce58\ubcf4\ub2e4 \ube44\uc2f8\uac70\ub098 \uc2f8\uac8c \ud615\uc131\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \ub9e4\uc218\ud558\uae30 \uc804\uc5d0 \uad34\ub9ac\uc728\uc774 \uc9c0\ub098\uce58\uac8c \ud06c\uc9c0 \uc54a\uc740\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\\n- \uc7a5\uc911\uc5d0\ub294 \ucd94\uc815 \uc21c\uc790\uc0b0\uac00\uce58\uc778 iNAV\ub97c \ud1b5\ud574 \ub300\ub7b5\uc801\uc778 \uac00\uce58\ub97c \ucc38\uace0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n#### \ubd84\ubc30\uae08\\n- ETF\uac00 \ub2f4\uace0 \uc788\ub294 \uc8fc\uc2dd\uc758 \ubc30\ub2f9\uc774\ub098 \ucc44\uad8c\uc758 \uc774\uc790\ub97c \ubaa8\uc544 \ud22c\uc790\uc790\uc5d0\uac8c \ub098\ub220\uc8fc\ub294 \ub3c8\uc744 \ubd84\ubc30\uae08\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.\\n- \uc9c0\uae09 \uc5ec\ubd80\uc640 \uc8fc\uae30\ub294 \uc0c1\ud488\ub9c8\ub2e4 \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0, \ubd84\ubc30\uae08\uc744 \uae30\ub300\ud558\uace0 \ub9e4\uc218\ud55c\ub2e4\uba74 \uc9c0\uae09 \uc815\ucc45\uc744 \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.\\n- \ubd84\ubc30\uae08\uc744 \uc9c0\uae09\ud558\uba74 \uadf8\ub9cc\ud07c ETF\uc758 \uc790\uc0b0\uc774 \uc904\uc5b4 \uac00\uaca9\uc774 \uc870\uc815\ub41c\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \uc774\ud574\ud574 \ub450\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\\n\\n#### \uac70\ub798\ub7c9\uacfc \uc6b4\uc6a9 \uaddc\ubaa8\\n- \uac70\ub798\ub7c9\uc774 \uc801\uc740 \uc0c1\ud488\uc740 \uc6d0\ud558\ub294 \uac00\uaca9\uc5d0 \uc0ac\uace0\ud314\uae30 \uc5b4\ub835\uace0, \ub9e4\uc218\xb7\ub9e4\ub3c4 \ud638\uac00\uc758 \uac04\uaca9\uc774 \ubc8c\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \uc6b4\uc6a9 \uaddc\ubaa8\uac00 \ub108\ubb34 \uc791\uc740 \uc0c1\ud488\uc740 \uc0c1\uc7a5\ud3d0\uc9c0\uac00 \ub420 \uac00\ub2a5\uc131\ub3c4 \uc788\uc5b4 \uaddc\ubaa8\ub97c \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.\\n\\n### ETF\uc758 \uc720\ud615\\n\\n#### \uc2dc\uc7a5\ub300\ud45c\uc9c0\uc218\ud615\\n- \ucf54\uc2a4\ud53c200\ucc98\ub7fc \ud55c \ub098\ub77c \uc2dc\uc7a5 \uc804\uccb4\ub97c \ub300\ud45c\ud558\ub294 \uc9c0\uc218\ub97c \ucd94\uc885\ud558\ub294 \uac00\uc7a5 \uae30\ubcf8\uc801\uc778 \uc720\ud615\uc785\ub2c8\ub2e4.\\n- \ud574\uc678 \uc2dc\uc7a5\uc744 \ub300\uc0c1\uc73c\ub85c S&P500, \ub098\uc2a4\ub2e5100 \uac19\uc740 \uc9c0\uc218\ub97c \ucd94\uc885\ud558\ub294 \uc0c1\ud488\ub3c4 \uc5ec\uae30\uc5d0 \uc18d\ud569\ub2c8\ub2e4.\\n\\n#### \uc139\ud130\xb7\ud14c\ub9c8\ud615\\n- \ubc18\ub3c4\uccb4, 2\ucc28\uc804\uc9c0\ucc98\ub7fc \ud2b9\uc815 \uc0b0\uc5c5\uc774\ub098 \uc8fc\uc81c\ub97c \ubaa8\uc544 \ub2f4\uc740 \uc720\ud615\uc785\ub2c8\ub2e4.\\n- \uc2dc\uc7a5 \uc804\uccb4\uac00 \uc544\ub2cc \uc77c\ubd80 \uc601\uc5ed\uc5d0 \uc9d1\uc911\ud558\uae30 \ub54c\ubb38\uc5d0 \ubcc0\ub3d9\uc131\uc774 \ub354 \ud074 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n#### \ucc44\uad8c\ud615\\n- \uad6d\ucc44\ub098 \ud68c\uc0ac\ucc44 \uac19\uc740 \ucc44\uad8c\uc744 \ub2f4\ub294 \uc720\ud615\uc785\ub2c8\ub2e4.\\n- \uc8fc\uc2dd\ud615\uc5d0 \ube44\ud574 \uac00\uaca9 \ubcc0\ub3d9\uc774 \uc791\uc740 \ud3b8\uc774\ub77c \uc790\uae08\uc744 \uc548\uc815\uc801\uc73c\ub85c \ub450\ub294 \uc6a9\ub3c4\ub85c \uc4f0\uc785\ub2c8\ub2e4.\\n\\n#### \uc6d0\uc790\uc7ac\xb7\ub300\uccb4\uc790\uc0b0\ud615\\n- \uae08\uacfc \uac19\uc740 \uc6d0\uc790\uc7ac\ub098 \ub9ac\uce20 \ub4f1\uc744 \ub2f4\ub294 \uc720\ud615\uc785\ub2c8\ub2e4.\\n- \uc8fc\uc2dd\uacfc \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc774\ub294 \uc790\uc0b0\uc744 \uc11e\uc5b4 \ud3ec\ud2b8\ud3f4\ub9ac\uc624\uc758 \ubcc0\ub3d9\uc744 \ub098\ub204\ub294 \ub370 \ud65c\uc6a9\ub429\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\nMTS\uc758 ETF \uac80\uc0c9\uc5d0\uc11c\ub294 \uc9c0\uc218 \uc774\ub984\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \ucd1d\ubcf4\uc218, \uad34\ub9ac\uc728, \uac70\ub798\ub7c9\uc744 \ud568\uaed8 \uc815\ub82c\ud574 \ubcf4\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uc9c0\uc218\ub97c \ucd94\uc885\ud558\ub294 \uc0c1\ud488\uc774 \uc5ec\ub7ec \uac1c\ub77c\uba74 \ubcf4\uc218\uc640 \uac70\ub798\ub7c9, \uc6b4\uc6a9 \uaddc\ubaa8\ub97c \ube44\uad50\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc120\ud0dd\uc758 \uae30\uc900\uc774 \uba85\ud655\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\ucc98\uc74c\uc5d0\ub294 \uc2dc\uc7a5\ub300\ud45c\uc9c0\uc218\ud615\ucc98\ub7fc \uad6c\uc870\uac00 \ub2e8\uc21c\ud55c \uc0c1\ud488\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uba74\uc11c, \uad34\ub9ac\uc728\uacfc iNAV\ub97c \ud655\uc778\ud558\ub294 \ud750\ub984\uc5d0 \uc775\uc219\ud574\uc9c0\ub294 \uac83\uc744 \uad8c\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\nETF\ub294 \ud380\ub4dc\uc758 \ubd84\uc0b0 \ud22c\uc790\ub97c \uc8fc\uc2dd\uc758 \uac70\ub798 \ud3b8\uc758\uc131\uc73c\ub85c \uc62e\uaca8 \uc628 \uc0c1\ud488\uc785\ub2c8\ub2e4.<br/>\\n\uad6c\uc870\ub97c \uc774\ud574\ud558\uace0 \ubcf4\uc218\uc640 \uad34\ub9ac\uc728\ub9cc \ud655\uc778\ud574\ub3c4, \uc0c1\ud488\uc744 \uace0\ub97c \ub54c \ud754\ub4e4\ub9ac\ub294 \uc77c\uc774 \ud6e8\uc52c \uc904\uc5b4\ub4ed\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZjRnd3J3azg3M3dobWZoem45azJzZXZ6bGFjNzJ2bDJvc3JsZGc0MCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/2SxYjYV9vP9NDSc2r4/giphy.gif\\" alt=\\"Piggy bank\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"interest-rate-and-stocks","metadata":{"permalink":"/blog/finance/interest-rate-and-stocks","source":"@site/finance/2026-10-21-interest-rate-and-stocks/index.mdx","title":"\uae08\ub9ac\uc640 \uc8fc\uac00\uc758 \uad00\uacc4 \u2014 \uae30\uc900\uae08\ub9ac\uac00 \uc6c0\uc9c1\uc774\uba74 \uc8fc\uac00\ub294 \uc65c \uc6c0\uc9c1\uc77c\uae4c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-21T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"interest-rate","permalink":"/blog/finance/tags/interest-rate"},{"inline":true,"label":"basics","permalink":"/blog/finance/tags/basics"}],"readingTime":2.47,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"interest-rate-and-stocks","title":"\uae08\ub9ac\uc640 \uc8fc\uac00\uc758 \uad00\uacc4 \u2014 \uae30\uc900\uae08\ub9ac\uac00 \uc6c0\uc9c1\uc774\uba74 \uc8fc\uac00\ub294 \uc65c \uc6c0\uc9c1\uc77c\uae4c","authors":["way"],"tags":["finance","interest-rate","basics"]},"unlisted":false,"prevItem":{"title":"ETF\ub780 \ubb34\uc5c7\uc778\uac00 \u2014 \uc8fc\uc2dd\ucc98\ub7fc \uc0ac\uace0\ud30c\ub294 \ud380\ub4dc","permalink":"/blog/finance/etf-basics"},"nextItem":{"title":"\ucf54\uc2a4\ud53c 5,700\uc120 \ub3cc\ud30c \u2014 \uc9c0\uc218\uac00 \uc624\ub97c \ub54c \ud655\uc778\ud574\uc57c \ud560 \uac83\ub4e4","permalink":"/blog/finance/kospi-5700-rally"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \uae30\uc900\uae08\ub9ac\uac00 \uc624\ub974\ub0b4\ub9b4 \ub54c \uc8fc\uac00\uc640 \ucc44\uad8c\uac00\uaca9\uc774 \uc65c \uc6c0\uc9c1\uc774\ub294\uc9c0, \uadf8 \uc6d0\ub9ac\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\ub274\uc2a4\uc5d0\uc11c\ub294 \uc911\uc559\uc740\ud589\uc774 \uae30\uc900\uae08\ub9ac\ub97c \uc62c\ub9ac\uba74 \uc8fc\uac00\uac00 \ud754\ub4e4\ub9ac\uace0, \ub0b4\ub9ac\uba74 \ubc18\ub4f1\ud55c\ub2e4\ub294 \uc774\uc57c\uae30\ub97c \uc790\uc8fc \uc811\ud569\ub2c8\ub2e4.<br/>\\n\uadf8\ub7f0\ub370 \uae08\ub9ac\ub294 \ub300\ucd9c \uc774\uc790\uc5d0 \ubd99\ub294 \uc22b\uc790\uc774\uace0, \uc8fc\uac00\ub294 \uae30\uc5c5\uc758 \uac00\uce58\ub97c \ub098\ud0c0\ub0b4\ub294 \uc22b\uc790\uc778\ub370 \ub458 \uc0ac\uc774\uc5d0 \uc5b4\ub5a4 \uc5f0\uacb0\uace0\ub9ac\uac00 \uc788\ub294 \uac83\uc77c\uae4c\uc694.<br/>\\n\uc774 \uc5f0\uacb0\uace0\ub9ac\ub97c \uc774\ud574\ud558\ub824\uba74 \uba3c\uc800 \uae30\uc900\uae08\ub9ac\uac00 \ubb34\uc5c7\uc778\uc9c0, \uadf8\ub9ac\uace0 \ud560\uc778\uc728\uc774\ub77c\ub294 \uac1c\ub150\uc744 \uc54c\uc544\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uae30\uc900\uae08\ub9ac\\n- \uc911\uc559\uc740\ud589\uc774 \uc2dc\uc911 \uc740\ud589\uacfc\uc758 \uac70\ub798\uc5d0 \uc801\uc6a9\ud558\ub294 \uc815\ucc45 \uae08\ub9ac\uc785\ub2c8\ub2e4.\\n- \uc774 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \uc608\uae08\xb7\ub300\ucd9c \uae08\ub9ac\uac00 \ub530\ub77c \uc6c0\uc9c1\uc774\uba70, \ub3c8\uc758 \uac00\uaca9\uc774 \uc804\ubc18\uc801\uc73c\ub85c \ube44\uc2f8\uc9d1\ub2c8\ub2e4.\\n- \ubc18\ub300\ub85c \ub0b4\ub9ac\uba74 \ub3c8\uc744 \ube4c\ub9ac\ub294 \ube44\uc6a9\uc774 \uc904\uc5b4\ub4e4\uc5b4 \uc2dc\uc911\uc5d0 \uc790\uae08\uc774 \ud480\ub9ac\uae30 \uc26c\uc6cc\uc9d1\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExeTJzZzkwdnFoOHp2OWd2OGV1eXFyOG5jejJiM2dhNzJoZWh1eGtrbiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/IvYx0wz4V9ivnvpVGV/giphy.gif\\" alt=\\"Interest rate\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uae08\ub9ac\uac00 \uc8fc\uac00\uc5d0 \ub2ff\ub294 \uae38\\n\\n#### \ud560\uc778\uc728\uacfc \ud604\uc7ac\uac00\uce58\\n- \uc8fc\uc2dd\uc758 \uac00\uaca9\uc740 \uadf8 \uae30\uc5c5\uc774 \uc55e\uc73c\ub85c \ubc8c\uc5b4\ub4e4\uc77c \uc774\uc775\uc744 \ud604\uc7ac\uc758 \uac00\uce58\ub85c \ud658\uc0b0\ud55c \uac12\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.\\n- \ubbf8\ub798\uc758 \ub3c8\uc744 \ud604\uc7ac \uac00\uce58\ub85c \ubc14\uafc0 \ub54c \uc801\uc6a9\ud558\ub294 \ube44\uc728\uc774 \ud560\uc778\uc728\uc774\uba70, \ud560\uc778\uc728\uc740 \uae08\ub9ac\ub97c \ub530\ub77c \uc6c0\uc9c1\uc785\ub2c8\ub2e4.\\n- \uc608\ub97c \ub4e4\uc5b4 1\ub144 \ub4a4\uc5d0 \ubc1b\uc744 110\ub9cc \uc6d0\uc740 \ud560\uc778\uc728\uc774 10%\uc774\uba74 \uc624\ub298\uc758 100\ub9cc \uc6d0\uacfc \uac19\uc740 \uac00\uce58\uc785\ub2c8\ub2e4.\\n- \uac19\uc740 \ub3c8\uc774\ub77c\ub3c4 \ud560\uc778\uc728\uc774 5%\ub85c \ub0ae\uc544\uc9c0\uba74 \ud604\uc7ac\uac00\uce58\ub294 \uc57d 104.8\ub9cc \uc6d0\uc73c\ub85c \ucee4\uc9d1\ub2c8\ub2e4.\\n- \uc989, \uae08\ub9ac\uac00 \ub0b4\ub9ac\uba74 \ubbf8\ub798 \uc774\uc775\uc758 \ud604\uc7ac\uac00\uce58\uac00 \ucee4\uc838 \uc8fc\uac00\uc5d0 \uc6b0\ud638\uc801\uc73c\ub85c \uc791\uc6a9\ud558\uace0, \uae08\ub9ac\uac00 \uc624\ub974\uba74 \uadf8 \ubc18\ub300\uac00 \ub429\ub2c8\ub2e4.\\n\\n#### \ucc44\uad8c\uac00\uaca9\uacfc\uc758 \uc5ed\uad00\uacc4\\n- \ucc44\uad8c\uc740 \uc815\ud574\uc9c4 \uc774\uc790(\ud45c\uba74\uae08\ub9ac)\ub97c \uc9c0\uae09\ud558\uae30\ub85c \uc57d\uc18d\ud55c \uc99d\uad8c\uc785\ub2c8\ub2e4.\\n- \uc2dc\uc7a5 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \uc0c8\ub85c \ubc1c\ud589\ub418\ub294 \ucc44\uad8c\uc774 \ub354 \ub192\uc740 \uc774\uc790\ub97c \uc8fc\uae30 \ub54c\ubb38\uc5d0, \uc774\uc790\uac00 \ub0ae\uc740 \uae30\uc874 \ucc44\uad8c\uc758 \ub9e4\ub825\uc740 \ub5a8\uc5b4\uc9c0\uace0 \uac00\uaca9\uc740 \ud558\ub77d\ud569\ub2c8\ub2e4.\\n- \ubc18\ub300\ub85c \uc2dc\uc7a5 \uae08\ub9ac\uac00 \ub0b4\ub9ac\uba74 \uae30\uc874 \ucc44\uad8c\uc758 \uc0c1\ub300\uc801 \ub9e4\ub825\uc774 \ucee4\uc838 \uac00\uaca9\uc774 \uc624\ub985\ub2c8\ub2e4.\\n- \uadf8\ub798\uc11c \ucc44\uad8c\uac00\uaca9\uacfc \uae08\ub9ac\ub294 \ubc18\ub300\ub85c \uc6c0\uc9c1\uc778\ub2e4\uace0 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n#### \uae30\uc5c5\uc758 \ube44\uc6a9\uacfc \uc2e4\uc801\\n- \uae08\ub9ac\uac00 \uc624\ub974\uba74 \uae30\uc5c5\uc774 \ub3c8\uc744 \ube4c\ub9ac\ub294 \ube44\uc6a9\uc774 \ub298\uc5b4 \uc774\uc775\uc774 \uc904\uc5b4\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \ube5a\uc774 \ub9ce\uc740 \uae30\uc5c5\uc77c\uc218\ub85d \uc774\uc790 \ubd80\ub2f4\uc758 \uc601\ud5a5\uc744 \ud06c\uac8c \ubc1b\uc2b5\ub2c8\ub2e4.\\n- \uae08\ub9ac\uac00 \ub0b4\ub9ac\uba74 \uc774\uc790 \ubd80\ub2f4\uc774 \uc904\uace0, \uc18c\ube44\uc640 \ud22c\uc790\ub3c4 \ub298\uc5b4\ub098\uae30 \uc26c\uc6cc \uae30\uc5c5 \uc2e4\uc801\uc5d0 \uc6b0\ud638\uc801\uc778 \ud658\uacbd\uc774 \ub429\ub2c8\ub2e4.\\n\\n### \uc131\uc7a5\uc8fc\uc640 \uac00\uce58\uc8fc\uac00 \ub2e4\ub974\uac8c \ubc1b\ub294 \uc601\ud5a5\\n\\n#### \uc131\uc7a5\uc8fc\\n- \uc9c0\uae08\uc758 \uc774\uc775\ubcf4\ub2e4 \uba3c \ubbf8\ub798\uc758 \ud070 \uc774\uc775\uc744 \uae30\ub300\ud558\uace0 \uac00\uaca9\uc774 \ud615\uc131\ub418\ub294 \uc8fc\uc2dd\uc785\ub2c8\ub2e4.\\n- \uc774\uc775\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc774 \uba3c \ubbf8\ub798\uc5d0 \uc788\uae30 \ub54c\ubb38\uc5d0, \ud560\uc778\uc728\uc774 \uc624\ub974\uba74 \ud604\uc7ac\uac00\uce58\uac00 \ud06c\uac8c \uae4e\uc785\ub2c8\ub2e4.\\n- \uadf8\ub798\uc11c \uae08\ub9ac \uc0c1\uc2b9\uae30\uc5d0 \uc0c1\ub300\uc801\uc73c\ub85c \ub354 \ud070 \uc870\uc815\uc744 \ubc1b\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n#### \uac00\uce58\uc8fc\\n- \ud604\uc7ac\uc758 \uc774\uc775\uacfc \uc790\uc0b0\uc5d0 \ube44\ud574 \uac00\uaca9\uc774 \ub0ae\uac8c \ud3c9\uac00\ub41c \uc8fc\uc2dd\uc785\ub2c8\ub2e4.\\n- \uc774\uc775\uc774 \uac00\uae4c\uc6b4 \uc2dc\uae30\uc5d0 \ubc1c\uc0dd\ud558\ubbc0\ub85c \ud560\uc778\uc728 \ubcc0\ud654\uc758 \uc601\ud5a5\uc744 \ube44\uad50\uc801 \ub35c \ubc1b\uc2b5\ub2c8\ub2e4.\\n- \uae08\ub9ac \uc0c1\uc2b9\uae30\uc5d0\ub294 \uc131\uc7a5\uc8fc\ubcf4\ub2e4 \ubc29\uc5b4\uc801\uc778 \ubaa8\uc2b5\uc744 \ubcf4\uc774\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ubd05\ub2c8\ub2e4\\n\\n\uae08\ub9ac \ub274\uc2a4\ub97c \uc811\ud560 \ub54c\ub294 \uc778\uc0c1\xb7\uc778\ud558 \uc5ec\ubd80 \uc790\uccb4\ubcf4\ub2e4 \uc2dc\uc7a5\uc758 \uc608\uc0c1\uacfc \uc5bc\ub9c8\ub098 \ub2e4\ub978\uc9c0\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\uc774\ubbf8 \uc608\uc0c1\ub41c \uae08\ub9ac \uacb0\uc815\uc740 \uc8fc\uac00\uc5d0 \ubbf8\ub9ac \ubc18\uc601\ub41c \uacbd\uc6b0\uac00 \ub9ce\uc544, \ubc1c\ud45c \ud6c4\uc5d0\ub3c4 \uc2dc\uc7a5\uc774 \ud06c\uac8c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc608\uc0c1\uacfc \ub2e4\ub978 \uacb0\uc815\uc774\ub098 \uc911\uc559\uc740\ud589 \ucd1d\uc7ac\uc758 \ubc1c\uc5b8\uc740 \ud560\uc778\uc728\uc5d0 \ub300\ud55c \uae30\ub300 \uc790\uccb4\ub97c \ubc14\uafb8\uae30 \ub54c\ubb38\uc5d0 \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\uc720\ud55c \uc8fc\uc2dd\uc774 \uba3c \ubbf8\ub798\uc758 \uc131\uc7a5\uc5d0 \uae30\ub300\ub294 \uc720\ud615\uc778\uc9c0, \ud604\uc7ac \uc774\uc775 \uc911\uc2ec\uc758 \uc720\ud615\uc778\uc9c0 \uad6c\ubd84\ud574 \ub450\uba74 \uae08\ub9ac \ud658\uacbd \ubcc0\ud654\uc5d0 \ub530\ub978 \uc601\ud5a5\uc744 \uac00\ub2a0\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uae08\ub9ac\uc640 \uc8fc\uac00\uc758 \uad00\uacc4\ub294 \uacb0\uad6d \ubbf8\ub798\uc758 \ub3c8\uc744 \uc624\ub298\uc758 \uac00\uce58\ub85c \ubc14\uafb8\ub294 \ud560\uc778\uc728\uc5d0\uc11c \ucd9c\ubc1c\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uc6d0\ub9ac\ub97c \uc54c\uc544\ub450\uba74 \uae08\ub9ac \uad00\ub828 \ub274\uc2a4\uac00 \ub098\uc62c \ub54c\ub9c8\ub2e4 \uc2dc\uc7a5\uc774 \uc65c \uadf8\ub807\uac8c \ubc18\uc751\ud558\ub294\uc9c0 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZjZnNzNwamZvb2kxNTVyNG9tNW5ycG9manhwZHg2cHU1czQ2cHI3eiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/12Eo7WogCAoj84/giphy.gif\\" alt=\\"Money\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"kospi-5700-rally","metadata":{"permalink":"/blog/finance/kospi-5700-rally","source":"@site/finance/2026-10-21-kospi-5700-rally/index.mdx","title":"\ucf54\uc2a4\ud53c 5,700\uc120 \ub3cc\ud30c \u2014 \uc9c0\uc218\uac00 \uc624\ub97c \ub54c \ud655\uc778\ud574\uc57c \ud560 \uac83\ub4e4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-21T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"market","permalink":"/blog/finance/tags/market"},{"inline":true,"label":"kospi","permalink":"/blog/finance/tags/kospi"}],"readingTime":2.44,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kospi-5700-rally","title":"\ucf54\uc2a4\ud53c 5,700\uc120 \ub3cc\ud30c \u2014 \uc9c0\uc218\uac00 \uc624\ub97c \ub54c \ud655\uc778\ud574\uc57c \ud560 \uac83\ub4e4","authors":["way"],"tags":["finance","market","kospi"]},"unlisted":false,"prevItem":{"title":"\uae08\ub9ac\uc640 \uc8fc\uac00\uc758 \uad00\uacc4 \u2014 \uae30\uc900\uae08\ub9ac\uac00 \uc6c0\uc9c1\uc774\uba74 \uc8fc\uac00\ub294 \uc65c \uc6c0\uc9c1\uc77c\uae4c","permalink":"/blog/finance/interest-rate-and-stocks"},"nextItem":{"title":"PER\uacfc PBR \uc77d\ub294 \ubc95 \u2014 \uc774\uc775\uacfc \uc790\uc0b0\uc73c\ub85c \uc8fc\uac00\ub97c \uac00\ub2a0\ud558\ub294 \ub450 \uac00\uc9c0 \uc9c0\ud45c","permalink":"/blog/finance/per-pbr-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \ucf54\uc2a4\ud53c\uac00 5,700\uc120\uc744 \ub118\uc740 \uc2dc\uc7a5 \ub3d9\ud5a5\uacfc, \uc9c0\uc218\uac00 \uc624\ub97c \ub54c \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud560 \uc9c0\ud45c\ub4e4\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc624\ub298\uc758 \uc2dc\uc7a5\\n\\n2026\ub144 10\uc6d4 21\uc77c, \ucf54\uc2a4\ud53c\ub294 \uc624\ud6c4 2\uc2dc \ubb34\ub835 5,712.46\uc744 \uae30\ub85d\ud558\uba70 5,700\uc120\uc744 \ub118\uc5b4\uc130\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 159.72\ud3ec\uc778\ud2b8, 2.88% \uc624\ub978 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 792.38\ub85c \uc804\uc77c \ub300\ube44 10.41\ud3ec\uc778\ud2b8, 1.33% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615\uc8fc \uc911\uc2ec\uc758 \ucf54\uc2a4\ud53c200 \uc9c0\uc218\ub294 886.28\ub85c 3.20% \uc624\ub974\uba70 \ucf54\uc2a4\ud53c\ubcf4\ub2e4 \ud070 \uc0c1\uc2b9\ud3ed\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 1,324.0\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.15% \ud558\ub77d\ud574 \uc6d0\ud654\uac00 \uc18c\ud3ed \uac15\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uc2dc\uc7a5\uc740 \ub098\uc2a4\ub2e5 \uc885\ud569\uc9c0\uc218\uac00 0.02% \ud558\ub77d\ud558\uace0 S&P500\uc774 0.28% \uc624\ub974\ub294 \ub4f1 \ubc29\ud5a5\uc131\uc774 \uc5c7\uac08\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc989, \uc624\ub298 \uad6d\ub0b4 \uc99d\uc2dc\uc758 \uc0c1\uc2b9\uc740 \ud574\uc678 \uc2dc\uc7a5\uc758 \ud750\ub984\ub9cc\uc73c\ub85c\ub294 \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4, \uad6d\ub0b4 \uc694\uc778\uc774 \uac15\ud558\uac8c \uc791\uc6a9\ud55c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZnN6MWxzOGNpMmF2N3BtaXFsYzZyYWFmMXVjbWdqdTY2bXV0NHduaiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/5RNNQvq3fhYlOYDIQ2/giphy.gif\\" alt=\\"Stock market\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc9c0\uc218\uac00 \uc624\ub97c \ub54c \ud655\uc778\ud574\uc57c \ud560 \uac83\ub4e4\\n\\n\uc9c0\uc218 \uc0c1\uc2b9\ub960\ub9cc \ubcf4\uace0 \uc2dc\uc7a5\uc744 \ud310\ub2e8\ud558\uba74 \ud750\ub984\uc744 \uc798\ubabb \uc77d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uc0c1\uc2b9\uc774\ub77c\ub3c4 \uc5b4\ub5a4 \ub3c8\uc774, \uc5b4\ub5a4 \uc885\ubaa9\uc744 \uc0ac\uc11c \uc62c\ub790\ub294\uc9c0\uc5d0 \ub530\ub77c \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c0\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\ub300\ud45c\uc801\uc73c\ub85c \ub2e4\uc74c \ub124 \uac00\uc9c0\ub97c \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.\\n\\n#### \uac70\ub798\ub300\uae08\\n- \uc9c0\uc218\uac00 \uc624\ub974\uba74\uc11c \uac70\ub798\ub300\uae08\ub3c4 \ud568\uaed8 \ub298\uc5c8\ub294\uc9c0\ub97c \ubd05\ub2c8\ub2e4.\\n- \uac70\ub798\ub300\uae08\uc774 \ub4b7\ubc1b\uce68\ub418\ub294 \uc0c1\uc2b9\uc740 \uc2dc\uc7a5\uc5d0 \ucc38\uc5ec\ud558\ub294 \uc790\uae08 \uc790\uccb4\uac00 \ub298\uc5c8\ub2e4\ub294 \uc2e0\ud638\ub85c \ud574\uc11d\ud569\ub2c8\ub2e4.\\n- \ubc18\ub300\ub85c \uac70\ub798\uac00 \ud55c\uc0b0\ud55c\ub370 \uc9c0\uc218\ub9cc \uc624\ub974\uba74, \uc801\uc740 \ub9e4\uc218\uc138\uc5d0\ub3c4 \uac00\uaca9\uc774 \uc6c0\uc9c1\uc778 \uac83\uc77c \uc218 \uc788\uc5b4 \uc0c1\uc2b9\uc758 \uc9c0\uc18d\uc131\uc744 \ubcf4\uc218\uc801\uc73c\ub85c \ubcf4\uac8c \ub429\ub2c8\ub2e4.\\n\\n#### \uc678\uad6d\uc778\xb7\uae30\uad00 \uc218\uae09\\n- \uc678\uad6d\uc778\uacfc \uae30\uad00, \uac1c\uc778 \uc911 \ub204\uac00 \uc21c\ub9e4\uc218\ub97c \uc8fc\ub3c4\ud588\ub294\uc9c0\ub97c \ud655\uc778\ud569\ub2c8\ub2e4.\\n- \ud2b9\ud788 \uc678\uad6d\uc778\uc758 \ub9e4\ub9e4\ub294 \ud658\uc728\uacfc \uae00\ub85c\ubc8c \uc790\uae08 \ud750\ub984\uc758 \uc601\ud5a5\uc744 \ud06c\uac8c \ubc1b\uae30 \ub54c\ubb38\uc5d0, \uad6d\ub0b4 \uc99d\uc2dc\uc758 \ubc29\ud5a5\uc744 \uac00\ub2a0\ud558\ub294 \ub370 \uc790\uc8fc \ucc38\uace0\ud569\ub2c8\ub2e4.\\n- \uae30\uad00 \uc911\uc5d0\uc11c\ub3c4 \uc5f0\uae30\uae08, \ud22c\uc2e0, \uae08\uc735\ud22c\uc790 \ub4f1 \uc8fc\uccb4\ubcc4\ub85c \uc131\uaca9\uc774 \ub2ec\ub77c, \uc5b4\ub290 \uc8fc\uccb4\uac00 \uc0c0\ub294\uc9c0\ub3c4 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.\\n\\n#### \uc8fc\ub3c4 \uc5c5\uc885\\n- \uc5b4\ub5a4 \uc5c5\uc885\uc774 \uc0c1\uc2b9\uc744 \uc774\ub04c\uc5c8\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.\\n- \uc2dc\uac00\ucd1d\uc561\uc774 \ud070 \uc5c5\uc885\uc774 \uc8fc\ub3c4\ud558\uba74 \uc9c0\uc218 \uc0c1\uc2b9\ud3ed\uc774 \ucee4\uc9c0\uae30 \uc27d\uace0, \ud2b9\uc815 \uc5c5\uc885\uc5d0 \uc0c1\uc2b9\uc774 \uc9d1\uc911\ub410\ub294\uc9c0 \uc2dc\uc7a5 \uc804\ubc18\uc73c\ub85c \ud655\uc0b0\ub410\ub294\uc9c0\uc5d0 \ub530\ub77c \uccb4\uac10 \uac15\ub3c4\uac00 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.\\n- \uc624\ub298\ucc98\ub7fc \ucf54\uc2a4\ud53c200\uc758 \uc0c1\uc2b9\ub960\uc774 \ucf54\uc2a4\ud53c\ub97c \uc6c3\ub3c4\ub294 \ub0a0\uc740 \ub300\ud615\uc8fc \uc911\uc2ec\uc758 \uc0c1\uc2b9\uc774\uc5c8\uc74c\uc744 \uc9d0\uc791\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n#### \ud658\uc728\\n- \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc758 \ubc29\ud5a5\uc744 \uc9c0\uc218\uc640 \ud568\uaed8 \ubd05\ub2c8\ub2e4.\\n- \uc77c\ubc18\uc801\uc73c\ub85c \uc6d0\ud654 \uac15\uc138(\ud658\uc728 \ud558\ub77d)\ub294 \uc678\uad6d\uc778 \uc790\uae08 \uc720\uc785\uacfc \ub9de\ubb3c\ub9ac\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc544, \uc9c0\uc218 \uc0c1\uc2b9\uacfc \ud658\uc728 \ud558\ub77d\uc774 \ub3d9\uc2dc\uc5d0 \ub098\ud0c0\ub098\uba74 \uc218\uae09 \ud658\uacbd\uc744 \uc6b0\ud638\uc801\uc73c\ub85c \ud574\uc11d\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.\\n- \ub2e4\ub9cc \ud658\uc728\uc740 \uc218\ucd9c \uae30\uc5c5\uc758 \uc2e4\uc801\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uae30 \ub54c\ubb38\uc5d0, \ubc29\ud5a5 \ud558\ub098\ub9cc\uc73c\ub85c \uc88b\uace0 \ub098\uc068\uc744 \ub2e8\uc815\ud558\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\nMTS\uc5d0\uc11c\ub294 \uc9c0\uc218 \ud654\uba74\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \uc218\uae09 \ud654\uba74\uacfc \uc5c5\uc885\ubcc4 \uc9c0\uc218\ub97c \ud568\uaed8 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uac00 \uc624\ub978 \ub0a0\uc77c\uc218\ub85d \uc0c1\uc2b9\ub960\ubcf4\ub2e4 \uba3c\uc800 \uac70\ub798\ub300\uae08 \ucd94\uc774\uc640 \uc678\uad6d\uc778\xb7\uae30\uad00\uc758 \ub9e4\ub9e4 \ub3d9\ud5a5\uc744 \ub300\uc870\ud574 \ubd05\ub2c8\ub2e4.<br/>\\n\ud2b9\uc815 \uc5c5\uc885\uc774 \uae09\ub4f1\ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \uc5c5\uc885 \uc548\uc5d0\uc11c \ub300\uc7a5\uc8fc\uac00 \uc6c0\uc9c1\uc600\ub294\uc9c0, \uc5c5\uc885 \uc804\ubc18\uc774 \ub530\ub77c \uc62c\ub790\ub294\uc9c0\ub3c4 \uad6c\ubd84\ud574\uc11c \ubd05\ub2c8\ub2e4.<br/>\\n\uc774\ub807\uac8c \uc9c0\ud45c\ub97c \uacb9\uccd0\uc11c \ubcf4\uba74 \ud558\ub8e8\uc758 \uc0c1\uc2b9\uc774 \uc790\uae08 \uc720\uc785\uc5d0 \uae30\ubc18\ud55c \uac83\uc778\uc9c0, \ub2e8\uae30\uc801\uc778 \uc218\uae09 \uc3e0\ub9bc\uc778\uc9c0 \ud310\ub2e8\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc9c0\uc218\uac00 \ud070 \ud3ed\uc73c\ub85c \uc624\ub978 \ub0a0\uc5d0\ub294 \uc0c1\uc2b9\ub960 \uc790\uccb4\ubcf4\ub2e4 \uadf8 \uc548\uc758 \ub0b4\uc6a9\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uac70\ub798\ub300\uae08, \uc218\uae09, \uc8fc\ub3c4 \uc5c5\uc885, \ud658\uc728\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\ub294 \uc2b5\uad00\uc774 \uc2dc\uc7a5\uc758 \ud750\ub984\uc744 \uc77d\ub294 \uae30\ubcf8\uae30\uac00 \ub429\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExcG1ocTFtbTk0aWY0d2hzZGJpNnhtN3J3dmUwaGRxNXNtbGFsb20zYSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/U7gTVK2ch30xsUskCL/giphy.gif\\" alt=\\"Chart\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"per-pbr-guide","metadata":{"permalink":"/blog/finance/per-pbr-guide","source":"@site/finance/2026-10-21-per-pbr-guide/index.mdx","title":"PER\uacfc PBR \uc77d\ub294 \ubc95 \u2014 \uc774\uc775\uacfc \uc790\uc0b0\uc73c\ub85c \uc8fc\uac00\ub97c \uac00\ub2a0\ud558\ub294 \ub450 \uac00\uc9c0 \uc9c0\ud45c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-21T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/finance/tags/finance"},{"inline":true,"label":"valuation","permalink":"/blog/finance/tags/valuation"},{"inline":true,"label":"basics","permalink":"/blog/finance/tags/basics"}],"readingTime":3.27,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"per-pbr-guide","title":"PER\uacfc PBR \uc77d\ub294 \ubc95 \u2014 \uc774\uc775\uacfc \uc790\uc0b0\uc73c\ub85c \uc8fc\uac00\ub97c \uac00\ub2a0\ud558\ub294 \ub450 \uac00\uc9c0 \uc9c0\ud45c","authors":["way"],"tags":["finance","valuation","basics"]},"unlisted":false,"prevItem":{"title":"\ucf54\uc2a4\ud53c 5,700\uc120 \ub3cc\ud30c \u2014 \uc9c0\uc218\uac00 \uc624\ub97c \ub54c \ud655\uc778\ud574\uc57c \ud560 \uac83\ub4e4","permalink":"/blog/finance/kospi-5700-rally"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uc8fc\uc2dd\uc758 \uac00\uaca9 \uc218\uc900\uc744 \ud310\ub2e8\ud560 \ub54c \uac00\uc7a5 \uba3c\uc800 \ud655\uc778\ud558\uac8c \ub418\ub294 \uc9c0\ud45c\uc778 PER\uacfc PBR\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\uc885\ubaa9\uc744 \uac80\uc0c9\ud558\uba74 \ud604\uc7ac\uac00\uc640 \ud568\uaed8 PER, PBR \uac19\uc740 \uc22b\uc790\uac00 \ub098\ub780\ud788 \ud45c\uc2dc\ub429\ub2c8\ub2e4.<br/>\\n\uc22b\uc790\uac00 \ub0ae\uc73c\uba74 \uc2f8\uace0 \ub192\uc73c\uba74 \ube44\uc2f8\ub2e4\uace0 \ub2e8\uc21c\ud558\uac8c \uc774\ud574\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\uc9c0\ub9cc \uc774 \uc9c0\ud45c\ub4e4\uc740 \uc5b4\ub5a4 \uc22b\uc790\ub97c \ub098\ub204\uc5b4 \ub9cc\ub4e0 \uac83\uc778\uc9c0, \uadf8\ub9ac\uace0 \uc5c5\uc885\uc758 \ud2b9\uc131\uc774 \ubb34\uc5c7\uc778\uc9c0\uc640 \ud568\uaed8 \ubd10\uc57c \uc81c\ub300\ub85c \uc77d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac01 \uc9c0\ud45c\uc758 \uacc4\uc0b0 \ubc29\uc2dd\ubd80\ud130 \ucc28\ub840\ub85c \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExa2dvNTI5bTQ2dzUyMTQ2MjN5N3h1dXVsdnJzczMxaXNsOGtpemw3dCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/3tEFVAbfzzcwo/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### PER \u2014 \uc774\uc775\uacfc \ube44\uad50\ud55c \uac00\uaca9\\n\\n#### \uc815\uc758\uc640 \uacc4\uc0b0\uc2dd\\n\\nPER(\uc8fc\uac00\uc218\uc775\ube44\uc728, Price Earnings Ratio)\uc740 \uc8fc\uac00\ub97c \uc8fc\ub2f9\uc21c\uc774\uc775(EPS)\uc73c\ub85c \ub098\ub208 \uac12\uc785\ub2c8\ub2e4.<br/>\\n\uae30\uc5c5\uc774 \ubc8c\uc5b4\ub4e4\uc774\ub294 \uc774\uc775\uc5d0 \ube44\ud574 \uc8fc\uac00\uac00 \uba87 \ubc30\ub85c \uac70\ub798\ub418\uace0 \uc788\ub294\uc9c0\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.<br/>\\n\\n```text\\nPER = \uc8fc\uac00 \xf7 EPS(\uc8fc\ub2f9\uc21c\uc774\uc775)\\nEPS = \ub2f9\uae30\uc21c\uc774\uc775 \xf7 \ubc1c\ud589\uc8fc\uc2dd\uc218\\n\\n\uc608\uc2dc) \uc8fc\uac00 50,000\uc6d0, EPS 5,000\uc6d0\uc778 \uacbd\uc6b0\\n     PER = 50,000 \xf7 5,000 = 10\ubc30\\n```\\n\\nPER\uc774 10\ubc30\ub77c\ub294 \uac83\uc740 \ud604\uc7ac\uc758 \uc774\uc775 \uc218\uc900\uc774 \uadf8\ub300\ub85c \uc720\uc9c0\ub41c\ub2e4\uace0 \uac00\uc815\ud558\uba74, \ud22c\uc790\ud55c \uae08\uc561\uacfc \uac19\uc740 \ud06c\uae30\uc758 \uc774\uc775\uc774 \uc313\uc774\uae30\uae4c\uc9c0 10\ub144\uc774 \uac78\ub9b0\ub2e4\ub294 \uc758\ubbf8\ub85c \ud574\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### PER\uc744 \uc77d\uc744 \ub54c \uc8fc\uc758\ud560 \uc810\\n\\n\uc774\uc775\uc774 \uc77c\uc2dc\uc801\uc73c\ub85c \ud754\ub4e4\ub9ac\uba74 PER\ub3c4 \ud568\uaed8 \ud06c\uac8c \ud754\ub4e4\ub9bd\ub2c8\ub2e4.<br/>\\n\uc77c\ud68c\uc131 \uc774\uc775\uc774 \ubc1c\uc0dd\ud55c \ud574\uc5d0\ub294 \uc774\uc775\uc774 \ubd80\ud480\ub824\uc838 PER\uc774 \uc2e4\uc81c\ubcf4\ub2e4 \ub0ae\uc544 \ubcf4\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc801\uc790 \uae30\uc5c5\uc740 EPS\uac00 \uc74c\uc218\uac00 \ub418\uc5b4 PER\uc744 \uacc4\uc0b0\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uacbd\uc6b0 PER\uc774 \ud45c\uc2dc\ub418\uc9c0 \uc54a\ub294\ub2e4\uace0 \ud574\uc11c \uc774\uc0c1\ud55c \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n### PBR \u2014 \uc790\uc0b0\uacfc \ube44\uad50\ud55c \uac00\uaca9\\n\\n#### \uc815\uc758\uc640 \uacc4\uc0b0\uc2dd\\n\\nPBR(\uc8fc\uac00\uc21c\uc790\uc0b0\ube44\uc728, Price Book-value Ratio)\uc740 \uc8fc\uac00\ub97c \uc8fc\ub2f9\uc21c\uc790\uc0b0(BPS)\uc73c\ub85c \ub098\ub208 \uac12\uc785\ub2c8\ub2e4.<br/>\\n\ud68c\uc0ac\uac00 \uac00\uc9c4 \uc21c\uc790\uc0b0\uc5d0 \ube44\ud574 \uc8fc\uac00\uac00 \uc5b4\ub290 \uc218\uc900\uc778\uc9c0\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.<br/>\\n\\n```text\\nPBR = \uc8fc\uac00 \xf7 BPS(\uc8fc\ub2f9\uc21c\uc790\uc0b0)\\nBPS = \uc790\ubcf8\ucd1d\uacc4 \xf7 \ubc1c\ud589\uc8fc\uc2dd\uc218\\n\\n\uc608\uc2dc) \uc8fc\uac00 50,000\uc6d0, BPS 100,000\uc6d0\uc778 \uacbd\uc6b0\\n     PBR = 50,000 \xf7 100,000 = 0.5\ubc30\\n```\\n\\nPBR\uc774 1\ubc30\ubcf4\ub2e4 \ub0ae\uc73c\uba74 \uc7a5\ubd80\uc0c1 \uc21c\uc790\uc0b0\ubcf4\ub2e4 \uc8fc\uac00\uac00 \ub0ae\uac8c \ud615\uc131\ub418\uc5b4 \uc788\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc7a5\ubd80\uc5d0 \uae30\ub85d\ub41c \uc790\uc0b0 \uac00\uce58\uc640 \uc2e4\uc81c \uac00\uce58\uac00 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n### \uc5c5\uc885\ub9c8\ub2e4 \uae30\uc900\uc774 \ub2e4\ub978 \uc774\uc720\\n\\n\uc131\uc7a5 \uc0b0\uc5c5\uc740 \ubbf8\ub798 \uc774\uc775\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \uac00\uaca9\uc5d0 \uba3c\uc800 \ubc18\uc601\ub418\uc5b4 PER\uc774 \ub192\uac8c \ud615\uc131\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc740\ud589\xb7\ubcf4\ud5d8 \uac19\uc740 \uae08\uc735 \uc5c5\uc885\uc740 \uc790\uc0b0 \uaddc\ubaa8\uac00 \ud06c\uace0 \uc774\uc775\uc758 \ubcc0\ub3d9\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \uc791\uc544, PER\uacfc \ud568\uaed8 PBR\uc744 \ubcf4\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\ud50c\ub7ab\ud3fc\xb7\uc18c\ud504\ud2b8\uc6e8\uc5b4 \uae30\uc5c5\uc740 \uc7a5\ubd80\uc5d0 \uc7a1\ud788\uc9c0 \uc54a\ub294 \ubb34\ud615\uc790\uc0b0\uc758 \ube44\uc911\uc774 \ucee4\uc11c PBR\uc774 \ub192\uac8c \ub098\ud0c0\ub098\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uc808\ub300\uc801\uc778 \uc22b\uc790 \ud558\ub098\ub9cc\uc73c\ub85c \ube44\uad50\ud558\uae30\ubcf4\ub2e4, \uac19\uc740 \uc5c5\uc885 \uc548\uc5d0\uc11c \ube44\uad50\ud558\uace0 \uadf8 \uae30\uc5c5\uc758 \uacfc\uac70 \ud750\ub984\uacfc \ube44\uad50\ud558\ub294 \uac83\uc774 \uba3c\uc800\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ub0ae\ub2e4\uace0 \ubb34\uc870\uac74 \uc2fc \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4\\n\\nPER\uacfc PBR\uc774 \ub0ae\uac8c \uba38\ubb34\ub294 \ub370\uc5d0\ub294 \uadf8\ub9cc\ud55c \uc774\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub807\uac8c \uc2f8 \ubcf4\uc774\ub294 \uc0c1\ud0dc\uac00 \uc624\ub798 \uc9c0\uc18d\ub418\ub294 \uc0c1\ud669\uc744 \uac00\uce58 \ud568\uc815\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4.<br/>\\n\uc774\uc775\uc774 \uc904\uc5b4\ub4dc\ub294 \ucd94\uc138\uc774\uac70\ub098, \uc0b0\uc5c5 \uc790\uccb4\uac00 \uc1e0\ud1f4\ud558\uace0 \uc788\uac70\ub098, \uc7ac\ubb34 \uad6c\uc870\uc5d0 \ubb38\uc81c\uac00 \uc788\uc73c\uba74 \ub0ae\uc740 \uc9c0\ud45c\uac00 \uc624\ud788\ub824 \uc704\ud5d8 \uc2e0\ud638\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\ud45c\uac00 \ub0ae\uc740 \uc774\uc720\ub97c \ud655\uc778\ud558\uc9c0 \uc54a\uace0 \uc22b\uc790\ub9cc \ubcf4\uace0 \uc811\uadfc\ud558\uba74, \uc2f8 \ubcf4\uc774\ub294 \uac00\uaca9\uc774 \uacc4\uc18d \uc2f8\uac8c \uba38\ubb34\ub294 \uc0c1\ud669\uc744 \uacaa\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### ROE\uc640 \ud568\uaed8 \ubcf4\ub294 \ubc95\\n\\nROE(\uc790\uae30\uc790\ubcf8\uc774\uc775\ub960)\ub294 \ud68c\uc0ac\uac00 \uc790\ubcf8\uc744 \uc5bc\ub9c8\ub098 \ud6a8\uc728\uc801\uc73c\ub85c \uc774\uc775\uc73c\ub85c \ubc14\uafb8\ub294\uc9c0\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.<br/>\\n\uc138 \uc9c0\ud45c \uc0ac\uc774\uc5d0\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 \uad00\uacc4\uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4.<br/>\\n\\n```text\\nROE = \ub2f9\uae30\uc21c\uc774\uc775 \xf7 \uc790\ubcf8\ucd1d\uacc4 \xd7 100\\n\\n\uad00\uacc4\uc2dd) PBR = PER \xd7 ROE\\n```\\n\\nROE\uac00 \ub192\uc740 \uae30\uc5c5\uc740 \uac19\uc740 \uc790\ubcf8\uc73c\ub85c \ub354 \ub9ce\uc740 \uc774\uc775\uc744 \ub0b4\ubbc0\ub85c, \uc2dc\uc7a5\uc774 \ub354 \ub192\uc740 PBR\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c PBR\uc774 \ub0ae\uc740\ub370 ROE\uae4c\uc9c0 \ub0ae\ub2e4\uba74, \uc790\uc0b0\uc740 \uc788\uc9c0\ub9cc \uc774\uc775\uc744 \uc798 \ub0b4\uc9c0 \ubabb\ud558\ub294 \uae30\uc5c5\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\nPER, PBR, ROE \uc138 \uac00\uc9c0\ub97c \ud568\uaed8 \ubcf4\uba74 \uac00\uaca9 \uc218\uc900\uacfc \uc218\uc775\uc131\uc744 \uac19\uc774 \ub193\uace0 \ud310\ub2e8\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\nMTS\ub098 \ud3ec\ud138\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 PER\xb7PBR\uc740 \uc5b4\ub5a4 \ub0a0\uc9dc\uc758 \uc7ac\ubb34\uc81c\ud45c\ub97c \uae30\uc900\uc73c\ub85c \uacc4\uc0b0\ud588\ub294\uc9c0\uc5d0 \ub530\ub77c \uc22b\uc790\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd5c\uadfc \ud655\uc815 \uc2e4\uc801 \uae30\uc900\uc778\uc9c0, \uc608\uc0c1 \uc2e4\uc801 \uae30\uc900\uc778\uc9c0 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc9c0\ud45c\ub97c \ube44\uad50\ud560 \ub54c\ub294 \uac19\uc740 \uae30\uc900, \uac19\uc740 \uc5c5\uc885, \uac19\uc740 \uc2dc\uc810\uc73c\ub85c \ub9de\ucd94\ub294 \uac83\uc774 \uae30\ubcf8\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\nPER\uacfc PBR\uc740 \uc8fc\uac00\uac00 \uc774\uc775\uacfc \uc790\uc0b0\uc5d0 \ube44\ud574 \uc5b4\ub290 \uc218\uc900\uc778\uc9c0 \uc54c\ub824\uc8fc\ub294 \ucd9c\ubc1c\uc810\uc77c \ubfd0, \uadf8 \uc790\uccb4\ub85c \uacb0\ub860\uc774 \ub418\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5c5\uc885\uc758 \ud2b9\uc131\uacfc ROE\ub97c \ud568\uaed8 \ub193\uace0, \uc9c0\ud45c\uac00 \ub0ae\uc740 \uc774\uc720\uae4c\uc9c0 \ud655\uc778\ud558\ub294 \uc21c\uc11c\ub85c \uc77d\uc5b4\ubcf4\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExeG9rczN5dWlqdWtlNWM2N3pkcWxsa25seDk5a285b3hscmUzd3FhbiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/U7gTVK2ch30xsUskCL/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"}]}}')}}]);